        const bulkLog = (...args) => console.log('[Bulk NF Clarify]', ...args);
        const normalizeText = (value) => String(value || '').replace(/\s+/g, ' ').trim();
        const isIndexPage = () => window.location.pathname === '/admin/domain/customer-request/index';
        const isUpdatePage = () => window.location.pathname === '/admin/domain/customer-request/update';
        const readQueue = () => GM_getValue(QUEUE_KEY, null);
