        const clearQueue = () => GM_setValue(QUEUE_KEY, null);
        const isQueueBusy = (queue) => Boolean(queue && (queue.status === 'running' || queue.status === 'building'));

        function extractAuthorIdFromHeaderSmallNodes(nodes) {
            const authorNode = Array.from(nodes || []).find((node) => {
                const text = normalizeText(node?.textContent || '');
                return /договор\s*№/i.test(text);
            });
            const authorText = normalizeText(authorNode?.textContent || '');
            const match = authorText.match(/договор\s*№\s*(\d+)/i);
            return match?.[1] || '';
        }

        function getBulkHeaderInfoSmallNodes() {
            return Array.from(document.querySelectorAll('#navbarSupportedContent .header-user-info.nav-item.text-center .text-nowrap small'));
        }

        function getCurrentBulkAuthorId() {
            return extractAuthorIdFromHeaderSmallNodes(getBulkHeaderInfoSmallNodes());
        }

        function buildBulkFilterUrl(authorId = getCurrentBulkAuthorId()) {
            const normalizedAuthorId = normalizeText(authorId);
            if (!normalizedAuthorId) {
                return '';
            }

            const params = new URLSearchParams();
            params.set('CRSearch[id]', '');
            params.set('CRSearch[opened_at_dates]', '');
            params.set('CRSearch[type]', '');
            params.set('CRSearch[status]', '');
            params.append('CRSearch[status][]', '3');
            params.set('CRSearch[city_id]', '');
            params.set('CRSearch[phone]', '');
            params.set('CRSearch[created_at_dates]', '');
            params.set('CRSearch[closed_at_dates]', '');
            params.set('CRSearch[author_id]', normalizedAuthorId);

            return `${window.location.origin}/admin/domain/customer-request/index?${params.toString()}`;
        }

        function isBulkQueueAuthorized(queue = readQueue()) {
            const queueAuthorId = normalizeText(queue?.sourceAuthorId || '');
            if (!queueAuthorId) {
                return false;
            }

            const currentAuthorId = normalizeText(getCurrentBulkAuthorId());
            return !currentAuthorId || currentAuthorId === queueAuthorId;
        }

        function isBulkAuthorAllowed() {
            if (workerMode) {
                return isBulkQueueAuthorized();
            }

            return isIndexPage() && Boolean(getCurrentBulkAuthorId());
        }

        function formatDateKey(date) {
            const year = date.getFullYear();
            const month = String(date.getMonth() + 1).padStart(2, '0');
            const day = String(date.getDate()).padStart(2, '0');
            return `${year}-${month}-${day}`;
        }

        function getCurrentMonthKey(date = new Date()) {
            const year = date.getFullYear();
            const month = String(date.getMonth() + 1).padStart(2, '0');
            return `${year}-${month}`;
        }

        function hasMonthlyAutoRunForMonth(monthKey = getCurrentMonthKey()) {
            return normalizeText(GM_getValue(MONTHLY_AUTO_RUN_MONTH_KEY, '')) === normalizeText(monthKey);
        }

        function markMonthlyAutoRunForMonth(monthKey = getCurrentMonthKey()) {
            GM_setValue(MONTHLY_AUTO_RUN_MONTH_KEY, normalizeText(monthKey));
        }

        function isFridayToday() {
            return new Date().getDay() === 5;
        }

        function isMondayToday() {
            return new Date().getDay() === 1;
        }

        function isScheduleMenuDisplayTime() {
            const now = new Date();
            const configuredDay = readAutoMenuShowDaySetting();
            if (configuredDay === SCRIPT_SETTINGS_AUTO_MENU_DISABLED) {
                return false;
            }

            const showDay = normalizeScriptSettingsWeekday(configuredDay);
            const normalizedShowDay = showDay === null ? SCHEDULE_MENU_SHOW_DAY : showDay;
            return now.getDay() === normalizedShowDay && now.getHours() >= SCHEDULE_MENU_SHOW_HOUR;
        }

        function getTodayDateKey() {
            return formatDateKey(new Date());
        }

        function getTomorrowDateKey() {
            const tomorrow = new Date();
            tomorrow.setDate(tomorrow.getDate() + 1);
            return formatDateKey(tomorrow);
        }

        function clearFridayShiftSchedule() {
            GM_setValue(FRIDAY_SHIFT_END_KEY, DEFAULT_FRIDAY_SHIFT_END);
            GM_setValue(FRIDAY_SHIFT_DATE_KEY, getTodayDateKey());
        }

        function readConfirmedFridayScheduleKey() {
            return normalizeText(GM_getValue(FRIDAY_CONFIRMED_SCHEDULE_KEY, ''));
        }

        function markFridayScheduleConfirmed(scheduleKey = getFridayScheduleKey()) {
            GM_setValue(FRIDAY_CONFIRMED_SCHEDULE_KEY, scheduleKey || '');
        }

        function clearFridayScheduleConfirmed() {
            GM_setValue(FRIDAY_CONFIRMED_SCHEDULE_KEY, '');
        }

        function hasConfirmedFridaySchedule() {
            const currentScheduleKey = getFridayScheduleKey();
            return Boolean(currentScheduleKey) && readConfirmedFridayScheduleKey() === currentScheduleKey;
        }

        function resetStoredFridayScheduleState(options = {}) {
            clearFridayShiftSchedule();
            clearFridayAutoRunToday();
            clearFridayScheduleConfirmed();
            fridayWarningSuppressedKey = '';
            resetFridayAutoStartState();
            cancelFridayWarningCountdown(false);

            if (options.resetPanel !== false) {
                fridayShiftEditing = true;
                setFridayShiftPanelMinimized(false);
            }
        }

        function clearFridayScheduleIfButtonShouldStayHidden() {
            if (!isBulkAuthorAllowed()) {
                return;
            }

            if (isScheduleMenuDisplayTime() || hasFridayScheduleReachedDay()) {
                return;
            }

            if (!hasSavedFridaySchedule() && !hasConfirmedFridaySchedule()) {
                return;
            }

            resetStoredFridayScheduleState({ resetPanel: false });
        }

        function resetFridayShiftScheduleForMenuIfNeeded() {
            if (!isBulkAuthorAllowed()) {
                return;
            }

            if (!isScheduleMenuDisplayTime()) {
                return;
            }

            const todayKey = getTodayDateKey();
            const lastResetDay = normalizeText(GM_getValue(SCHEDULE_MENU_RESET_DAY_KEY, ''));
            if (lastResetDay === todayKey) {
                return;
            }

            resetStoredFridayScheduleState();
            GM_setValue(SCHEDULE_MENU_RESET_DAY_KEY, todayKey);
        }

        function expandFridayShiftPanelForSessionIfNeeded() {
            if (!isBulkAuthorAllowed()) {
                return;
            }

            if (!isScheduleMenuDisplayTime()) {
                return;
            }

            const todayKey = getTodayDateKey();
            const expandedSessionKey = sessionStorage.getItem(SCHEDULE_MENU_EXPANDED_SESSION_KEY) || '';
            if (expandedSessionKey === todayKey) {
                return;
            }

            setFridayShiftPanelMinimized(false);
            fridayShiftEditing = !hasConfirmedFridaySchedule();
            sessionStorage.setItem(SCHEDULE_MENU_EXPANDED_SESSION_KEY, todayKey);
        }

        function getStoredFridayShiftDateValue() {
            return normalizeText(GM_getValue(FRIDAY_SHIFT_DATE_KEY, ''));
        }

        function hasExpiredFridayShiftSchedule() {
            const storedValue = getStoredFridayShiftDateValue();
            if (!/^\d{4}-\d{2}-\d{2}$/.test(storedValue)) {
                return false;
            }

            const storedDate = parseDateKey(storedValue);
            const todayDate = parseDateKey(getTodayDateKey());
            if (!storedDate || !todayDate) {
                return false;
            }

            return storedDate.getTime() < todayDate.getTime();
        }

        function readFridayShiftEnd() {
            if (hasExpiredFridayShiftSchedule()) {
                clearFridayShiftSchedule();
                return DEFAULT_FRIDAY_SHIFT_END;
            }

            return normalizeText(GM_getValue(FRIDAY_SHIFT_END_KEY, DEFAULT_FRIDAY_SHIFT_END)) || DEFAULT_FRIDAY_SHIFT_END;
        }

        function readFridayShiftDate() {
            const fallback = getTodayDateKey();
            const normalized = normalizeText(GM_getValue(FRIDAY_SHIFT_DATE_KEY, fallback)) || fallback;
            if (!/^\d{4}-\d{2}-\d{2}$/.test(normalized)) {
                return fallback;
            }

            const storedDate = parseDateKey(normalized);
            const todayDate = parseDateKey(fallback);
            if (!storedDate || !todayDate) {
                return fallback;
            }

            if (storedDate.getTime() < todayDate.getTime()) {
                clearFridayShiftSchedule();
                return fallback;
            }

            return normalized;
        }

        function writeFridayShiftEnd(value) {
            const normalized = normalizeText(value);
            if (/^\d{2}:\d{2}$/.test(normalized)) {
                GM_setValue(FRIDAY_SHIFT_END_KEY, normalized);
            }
        }

        function writeFridayShiftDate(value) {
            const normalized = normalizeText(value);
            if (/^\d{4}-\d{2}-\d{2}$/.test(normalized)) {
                GM_setValue(FRIDAY_SHIFT_DATE_KEY, normalized);
            }
        }

        function parseDateKey(value) {
            const normalized = normalizeText(value);
            const match = normalized.match(/^(\d{4})-(\d{2})-(\d{2})$/);
            if (!match) return null;
            const year = Number(match[1]);
            const month = Number(match[2]);
            const day = Number(match[3]);
            const date = new Date(year, month - 1, day, 0, 0, 0, 0);
            return Number.isNaN(date.getTime()) ? null : date;
        }

        function formatShiftDateLabel(value) {
            const date = parseDateKey(value);
            if (!date) return value;
            return `${String(date.getDate()).padStart(2, '0')}.${String(date.getMonth() + 1).padStart(2, '0')}`;
        }

        function parseScheduledDateTime(dateValue, timeValue) {
            const normalized = normalizeText(timeValue);
            const match = normalized.match(/^(\d{1,2}):(\d{2})$/);
            if (!match) return null;
            const hours = Number(match[1]);
            const minutes = Number(match[2]);
            if (!Number.isFinite(hours) || !Number.isFinite(minutes) || hours < 0 || hours > 23 || minutes < 0 || minutes > 59) {
                return null;
            }
            const date = parseDateKey(dateValue);
            if (!date) return null;
            date.setHours(hours, minutes, 0, 0);
            return date;
        }

        function getNormalizedFridayShiftDateForTime(dateValue, timeValue) {
            const normalizedDate = parseDateKey(dateValue) ? dateValue : getTodayDateKey();
            const scheduledDate = parseScheduledDateTime(normalizedDate, timeValue);
            const todayKey = getTodayDateKey();

            if (normalizedDate === todayKey && scheduledDate && scheduledDate.getTime() <= Date.now()) {
                return getTomorrowDateKey();
            }

            return normalizedDate;
        }

        function formatRemainingTime(ms) {
            const totalSeconds = Math.max(0, Math.ceil(ms / 1000));
            const hours = Math.floor(totalSeconds / 3600);
            const minutes = Math.floor((totalSeconds % 3600) / 60);
            const seconds = totalSeconds % 60;
            if (hours > 0) {
                return `${hours}ч ${String(minutes).padStart(2, '0')}м`;
            }
            if (minutes > 0) {
                return `${minutes}м ${String(seconds).padStart(2, '0')}с`;
            }
            return `${seconds}с`;
        }

        function hasFridayAutoRunForCurrentSchedule() {
            return normalizeText(GM_getValue(FRIDAY_AUTO_RUN_DAY_KEY, '')) === readFridayShiftDate();
        }

        function markFridayAutoRunToday() {
            GM_setValue(FRIDAY_AUTO_RUN_DAY_KEY, readFridayShiftDate());
        }

        function clearFridayAutoRunToday() {
            GM_setValue(FRIDAY_AUTO_RUN_DAY_KEY, '');
        }

        function hasSavedFridaySchedule() {
            return Boolean(parseScheduledDateTime(readFridayShiftDate(), readFridayShiftEnd()));
        }

        function isCleanupTabActive() {
            const hasFocus = typeof document.hasFocus !== 'function' || document.hasFocus();
            return document.visibilityState === 'visible' && document.hidden !== true && hasFocus;
        }

        function isFridayShiftTabActive() {
            return isCleanupTabActive();
        }

        function resetFridayAutoStartState(options = {}) {
            fridayAutoStartCountdownEndsAt = 0;
            fridayAutoStartWaitingForFocus = options.keepWaiting === true;
        }

        function isFridayShiftPanelMinimized() {
            return GM_getValue(FRIDAY_PANEL_MINIMIZED_KEY, false) === true;
        }

        function setFridayShiftPanelMinimized(value) {
            GM_setValue(FRIDAY_PANEL_MINIMIZED_KEY, value === true);
        }

        function ensureFridayShiftMinimizedDot() {
            const existing = document.getElementById('bulk-nf-clarify-friday-dot');
            if (existing) {
                existing.remove();
            }
            return null;
        }

        function fillFridayShiftEditor(panel, useSavedValues = false) {
            if (!panel) return;
            const dateInput = panel.querySelector('#bulk-nf-clarify-friday-date');
            const timeInput = panel.querySelector('#bulk-nf-clarify-friday-time');
            if (dateInput) {
                dateInput.value = useSavedValues ? (readFridayShiftDate() || getTodayDateKey()) : getTodayDateKey();
            }
            if (timeInput) {
                timeInput.value = useSavedValues ? readFridayShiftEnd() : '';
            }
            updateFridayShiftEditorHint(panel);
        }

        function syncFridayShiftDraftDate(panel) {
            if (!panel) return;
            const dateInput = panel.querySelector('#bulk-nf-clarify-friday-date');
            const timeInput = panel.querySelector('#bulk-nf-clarify-friday-time');
            if (!dateInput || !timeInput) return;

            const draftTime = normalizeText(timeInput.value);
            if (!/^\d{2}:\d{2}$/.test(draftTime)) {
                return;
            }

            const draftDate = parseDateKey(dateInput.value) ? dateInput.value : getTodayDateKey();
            const normalizedDate = getNormalizedFridayShiftDateForTime(draftDate, draftTime);
            if (normalizedDate !== draftDate) {
                dateInput.value = normalizedDate;
            }
        }

        function updateFridayShiftEditorHint(panel) {
            if (!panel) return;
            const hintNode = panel.querySelector('#bulk-nf-clarify-friday-hint');
            const dateInput = panel.querySelector('#bulk-nf-clarify-friday-date');
            const timeInput = panel.querySelector('#bulk-nf-clarify-friday-time');
            if (!hintNode || !dateInput || !timeInput) return;

            const draftDate = parseDateKey(dateInput.value) ? dateInput.value : getTodayDateKey();
            const draftTime = normalizeText(timeInput.value);
            if (!draftTime) {
                hintNode.textContent = 'Поля специально пустые. Укажи время вручную. Если дату не заполнить, при сохранении возьмётся сегодняшний день.';
                return;
            }

            const normalizedDate = getNormalizedFridayShiftDateForTime(draftDate, draftTime);
            if (normalizedDate !== draftDate) {
                hintNode.textContent = `Это время на сегодня уже прошло. При сохранении дата станет ${formatShiftDateLabel(normalizedDate)}.`;
                return;
            }

            hintNode.textContent = `Будет сохранено: ${formatShiftDateLabel(draftDate)} ${draftTime}.`;
        }

        function getFridayScheduleKey(dateValue = readFridayShiftDate(), timeValue = readFridayShiftEnd()) {
            return parseScheduledDateTime(dateValue, timeValue) ? `${dateValue}|${timeValue}` : '';
        }

        function hasFridayScheduleReachedDay() {
            const scheduledDate = parseDateKey(readFridayShiftDate());
            const todayDate = parseDateKey(getTodayDateKey());
            if (!scheduledDate || !todayDate || !hasSavedFridaySchedule()) {
                return false;
            }

            return scheduledDate.getTime() <= todayDate.getTime();
        }

        function shouldTrackFridayShiftSchedule() {
            if (!isBulkAuthorAllowed()) {
                return false;
            }

            if (isScheduleMenuDisplayTime()) {
                return true;
            }

            if (hasFridayAutoRunForCurrentSchedule()) {
                return false;
            }

            if (readAutoMenuShowDaySetting() === SCRIPT_SETTINGS_AUTO_MENU_DISABLED) {
                return false;
            }

            return hasFridayScheduleReachedDay();
        }

        function ensureFridayWarningDialog() {
            if (!isIndexPage()) return null;

            let dialog = document.getElementById('bulk-nf-clarify-friday-warning');
            if (!dialog) {
                dialog = document.createElement('div');
                dialog.id = 'bulk-nf-clarify-friday-warning';
                dialog.innerHTML = `
                    <div class="bulk-nf-clarify-warning__card bulk-nf-clarify-warning__card--scheduled">
                        <div class="bulk-nf-clarify-warning__title">Запланированная автоуборка</div>
                        <div class="bulk-nf-clarify-warning__text" id="bulk-nf-clarify-friday-warning-text"></div>
                        <div class="bulk-nf-clarify-warning__actions">
                            <button type="button" class="btn btn-warning" id="bulk-nf-clarify-friday-warning-start">Запустить сейчас</button>
                            <button type="button" class="btn btn-default" id="bulk-nf-clarify-friday-warning-cancel">Отмена</button>
                        </div>
                    </div>
                `;
                document.body.appendChild(dialog);

                dialog.querySelector('#bulk-nf-clarify-friday-warning-start').addEventListener('click', () => {
                    cancelFridayWarningCountdown(false);
                    void launchFridayScheduledBulkProcessing('friday-warning-manual');
                });

                dialog.querySelector('#bulk-nf-clarify-friday-warning-cancel').addEventListener('click', () => {
                    cancelFridayWarningCountdown(true);
                    renderFridayShiftPanel();
                });
            }

            return dialog;
        }

        function renderFridayWarningDialog() {
            const dialog = ensureFridayWarningDialog();
            if (!dialog) return;

            if (!fridayWarningEndsAt || !fridayWarningScheduleKey) {
                dialog.classList.remove('is-visible');
                return;
            }

            const secondsLeft = Math.max(0, Math.ceil((fridayWarningEndsAt - Date.now()) / 1000));
            const text = dialog.querySelector('#bulk-nf-clarify-friday-warning-text');
            if (text) {
                text.textContent = `Время наступило. Все заявки на уточнении будут убраны через ${secondsLeft} сек.`;
            }
            dialog.classList.add('is-visible');
        }

        function cancelFridayWarningCountdown(suppressCurrent = false) {
            if (fridayWarningInterval) {
                clearInterval(fridayWarningInterval);
                fridayWarningInterval = null;
            }

            if (suppressCurrent && fridayWarningScheduleKey) {
                fridayWarningSuppressedKey = fridayWarningScheduleKey;
            }

            fridayWarningEndsAt = 0;
            fridayWarningScheduleKey = '';
            renderFridayWarningDialog();
        }

        async function launchFridayScheduledBulkProcessing(source) {
            resetFridayAutoStartState();
            cancelFridayWarningCountdown(false);
            markFridayAutoRunToday();
            try {
                await launchBulkProcessing({ includeRecent: true, skipConfirm: true, source });
            } catch (error) {
                clearFridayAutoRunToday();
                throw error;
            }
        }

        function beginFridayWarningCountdown() {
            const scheduleKey = getFridayScheduleKey();
            if (!scheduleKey) {
                cancelFridayWarningCountdown(false);
                return;
            }

            cancelFridayWarningCountdown(false);
            fridayWarningScheduleKey = scheduleKey;
            fridayWarningEndsAt = Date.now() + FRIDAY_AUTO_START_COUNTDOWN_MS;
            renderFridayWarningDialog();

            fridayWarningInterval = setInterval(() => {
                const queue = readQueue();
                if (isQueueBusy(queue) || hasFridayAutoRunForCurrentSchedule() || getFridayScheduleKey() !== fridayWarningScheduleKey) {
                    cancelFridayWarningCountdown(false);
                    renderFridayShiftPanel();
                    return;
                }

                if (!isFridayShiftTabActive()) {
                    cancelFridayWarningCountdown(false);
                    resetFridayAutoStartState({ keepWaiting: true });
                    renderFridayShiftPanel();
                    return;
                }

                if (Date.now() >= fridayWarningEndsAt) {
                    cancelFridayWarningCountdown(false);
                    void launchFridayScheduledBulkProcessing('friday-warning-auto').catch(() => {
                        clearFridayAutoRunToday();
                    });
                    return;
                }

                renderFridayWarningDialog();
                renderFridayShiftPanel();
            }, 250);
        }

        function markAsWorkerTabIfNeeded() {
            const url = new URL(window.location.href);
            if (url.searchParams.get(WORKER_QUERY_PARAM) === '1') {
                sessionStorage.setItem(WORKER_TAB_KEY, '1');
            }
        }

        function isWorkerTab() {
            markAsWorkerTabIfNeeded();
            return sessionStorage.getItem(WORKER_TAB_KEY) === '1';
        }

        function getCurrentRequestId() {
            const url = new URL(window.location.href);
            return String(url.searchParams.get('id') || '').trim();
        }

        function getPendingSuccess() {
            const pendingRaw = sessionStorage.getItem(PENDING_SUCCESS_KEY);
            if (!pendingRaw) return null;
            try {
                return JSON.parse(pendingRaw);
            } catch (error) {
                sessionStorage.removeItem(PENDING_SUCCESS_KEY);
                return null;
            }
        }

        function getNavigationType() {
            try {
                const entries = performance.getEntriesByType?.('navigation');
                if (entries && entries.length > 0) {
                    return String(entries[0].type || '');
                }
            } catch (error) {
                bulkLog('Не удалось определить тип навигации', error);
            }

            try {
                if (performance.navigation) {
                    return performance.navigation.type === 1 ? 'reload' : 'navigate';
                }
            } catch (error) {
                bulkLog('Не удалось определить тип навигации через legacy API', error);
            }

            return '';
        }

        function updateQueue(mutator) {
            const queue = readQueue();
            if (!queue) return null;
            const nextQueue = mutator({ ...queue, processed: [...(queue.processed || [])], failed: [...(queue.failed || [])] });
            if (!nextQueue) return null;
            nextQueue.updatedAt = Date.now();
            writeQueue(nextQueue);
            return nextQueue;
        }

        function getExpectedRequestId(queue) {
            if (!queue || queue.status !== 'running') return '';
            return String(queue.ids?.[queue.currentIndex] || '').trim();
        }

        function copyTextToClipboard(text) {
            if (!text) return;
            copyTextSafely(text).then((copied) => {
                if (!copied) {
                    bulkLog('Не удалось скопировать текст');
                }
            }).catch((error) => bulkLog('Не удалось скопировать текст', error));
        }

        function addProcessedId(requestId) {
            const nextQueue = updateQueue((queue) => {
                const expectedId = getExpectedRequestId(queue);
                if (expectedId !== requestId) return queue;
                queue.processed.push({ requestId, completedAt: Date.now() });
                queue.currentIndex += 1;
                if (queue.currentIndex >= queue.ids.length) {
                    queue.status = 'completed';
                    queue.completedAt = Date.now();
                }
                return queue;
            });

            const processedIds = (nextQueue?.processed || []).map((item) => String(item.requestId || '').trim()).filter(Boolean);
            if (processedIds.length) {
                copyTextToClipboard(processedIds.join('\n'));
            }
        }

        function markCurrentAsFailed(reason) {
            updateQueue((queue) => {
                if (queue.status !== 'running') return queue;
                const requestId = getExpectedRequestId(queue);
                if (!requestId) return queue;
                queue.failed.push({ requestId, reason, failedAt: Date.now() });
                queue.currentIndex += 1;
                if (queue.currentIndex >= queue.ids.length) {
                    queue.status = 'completed';
                    queue.completedAt = Date.now();
                }
                return queue;
            });
        }

        function buildUpdateRequestUrl(requestId) {
            const url = new URL('https://bt-lead-centre.ru/admin/domain/customer-request/update');
            url.searchParams.set('id', requestId);
            return url.toString();
        }

        function buildWorkerRequestUrl(requestId) {
            const url = new URL(buildUpdateRequestUrl(requestId));
            url.searchParams.set(WORKER_QUERY_PARAM, '1');
            return url.toString();
        }

        function getCurrentStatusText() {
            const headerStatus = document.querySelector('form#customerRequestForm > div > div > h1 > div.ml-auto');
            if (headerStatus) {
                const text = normalizeText(headerStatus.textContent);
                if (text) return text;
            }
            const badge = document.querySelector('.crm-status-badge');
            if (badge) {
                const badgeText = normalizeText(badge.querySelector('.badge-text')?.textContent || badge.textContent || '');
                if (badgeText) return badgeText;
            }
            return '';
        }

        function isClarificationLikeStatus(text) {
            const normalized = normalizeText(text).toLowerCase();
            return normalized.includes('на уточнении') || normalized.includes('модерац');
        }

        function parseCreatedAtDate(value) {
            const normalized = normalizeText(value);
            if (!normalized) return null;
            const match = normalized.match(/^(\d{1,2})[./](\d{1,2})[./](\d{2,4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?/);
            if (!match) return null;
            const day = Number(match[1]);
            const month = Number(match[2]);
            const yearRaw = Number(match[3]);
            const hours = Number(match[4] || '0');
            const minutes = Number(match[5] || '0');
            const seconds = Number(match[6] || '0');
            const year = yearRaw < 100 ? 2000 + yearRaw : yearRaw;
            const date = new Date(year, month - 1, day, hours, minutes, seconds, 0);
            return Number.isNaN(date.getTime()) ? null : date;
        }

        function isOlderThanPreviousCalendarDay(value) {
            const createdAtDate = parseCreatedAtDate(value);
            if (!createdAtDate) return false;
            const startOfYesterday = new Date();
            startOfYesterday.setHours(0, 0, 0, 0);
            startOfYesterday.setDate(startOfYesterday.getDate() - 1);
            return createdAtDate < startOfYesterday;
        }

        function triggerElementEvents(element) {
            element.dispatchEvent(new Event('input', { bubbles: true }));
            element.dispatchEvent(new Event('change', { bubbles: true }));
        }

        async function waitForElement(selector, timeout = 4000) {
            const startedAt = Date.now();
            while (Date.now() - startedAt < timeout) {
                const element = document.querySelector(selector);
                if (element) return element;
                await new Promise((resolve) => setTimeout(resolve, 50));
            }
            throw new Error(`Не найден элемент: ${selector}`);
        }

        function getCurrentCity() {
            const cityField = document.querySelector(SELECTORS.citySelect);
            if (!cityField) return '';
            const selectedOption = cityField.options[cityField.selectedIndex];
            return selectedOption ? normalizeText(selectedOption.textContent) : '';
        }

        function shouldChangeCityToAbakan() {
            const currentCity = getCurrentCity();
            return TRIGGER_CITIES.some((city) => currentCity.toLowerCase() === String(city).toLowerCase());
        }

        function selectClientInModal() {
            const select = document.getElementById('timeChangeReasonModalSelect');
            const modal = document.getElementById('timeChangeReasonModal');
            if (!select || !modal || !modal.classList.contains('show')) return false;
            if (modalUserChanged || modalAutoSelected) return false;
            const clientOption = Array.from(select.options).find((option) => normalizeText(option.textContent).toLowerCase() === 'клиент');
            if (!clientOption) return false;
            select.value = clientOption.value;
            triggerElementEvents(select);
            modalAutoSelected = true;
            select.addEventListener('change', () => { modalUserChanged = true; }, { once: true });
            const chooseButton = Array.from(modal.querySelectorAll('button')).find((button) => normalizeText(button.textContent).toLowerCase().includes('выбрать')) || modal.querySelector('button.btn-primary, button[type="submit"]');
            if (chooseButton) chooseButton.click();
            return true;
        }

        async function setCityToAbakanIfNeeded() {
            if (!shouldChangeCityToAbakan()) return false;
            const cityField = await waitForElement(SELECTORS.citySelect, 5000);
            const abakanOption = Array.from(cityField.options).find((option) => normalizeText(option.textContent) === 'Абакан');
            if (!abakanOption) throw new Error('Не найдена опция города Абакан');
            if (cityField.value !== abakanOption.value) {
                cityField.value = abakanOption.value;
                triggerElementEvents(cityField);
                if (typeof window.$ !== 'undefined' && typeof window.$(cityField).trigger === 'function') {
                    window.$(cityField).trigger('change');
                }
            }
            modalAutoSelected = false;
            modalUserChanged = false;
            await new Promise((resolve) => setTimeout(resolve, 100));
            selectClientInModal();
            return true;
        }

        function findNotCompletedButton() {
            return document.querySelector('button[onclick*="saveAndClose(this, 2)"]')
                || document.querySelector('button[onclick*="saveAndClose(this, 21)"]')
                || null;
        }

        function setNamedFieldValue(fieldName, targetValue) {
            const fields = Array.from(document.getElementsByName(fieldName));
            let applied = false;
            fields.forEach((field) => {
                if (field instanceof HTMLInputElement && (field.type === 'radio' || field.type === 'checkbox')) {
                    const shouldCheck = String(field.value) === String(targetValue);
                    if (field.checked !== shouldCheck) {
                        field.checked = shouldCheck;
                        triggerElementEvents(field);
                    }
                    applied = applied || shouldCheck;
                    return;
                }
                if ('value' in field && String(field.value) !== String(targetValue)) {
                    field.value = String(targetValue);
                    triggerElementEvents(field);
                }
                applied = true;
            });
            return applied;
        }

        function getCustomerRequestForm() {
            return document.querySelector('form#customerRequestForm') || document.querySelector('form');
        }

        function buildBackgroundSubmitData(form, targetStatusId, saveButton) {
            const formData = new FormData(form);
            formData.set('CustomerRequest[status_change_type]', String(targetStatusId));
            if (saveButton?.name) {
                formData.set(saveButton.name, saveButton.value || '1');
            }
            return formData;
        }

        async function submitFormInBackground(form, formData) {
            if (!form) throw new Error('Форма заявки не найдена');
            const method = normalizeText(form.getAttribute('method') || 'POST').toUpperCase() || 'POST';
            const action = form.getAttribute('action') || window.location.href;
            const url = new URL(action, window.location.href).toString();
            return fetch(url, {
                method,
                body: formData || new FormData(form),
                credentials: 'include',
                keepalive: true,
                redirect: 'follow'
            });
        }

        function delay(ms) {
            return new Promise((resolve) => setTimeout(resolve, ms));
        }

        function getDocumentCustomerRequestForm(doc) {
            return doc?.querySelector?.('form#customerRequestForm')
                || doc?.querySelector?.('form[action*="/customer-request/update"]')
                || doc?.querySelector?.('form');
        }

        function getDocumentStatusSelect(doc) {
            return doc?.querySelector?.(SELECTORS.statusChangeType)
                || doc?.querySelector?.('#customerrequest-status_change_type')
                || null;
        }

        function getDocumentSaveButton(doc) {
            return doc?.querySelector?.(SELECTORS.saveButton)
                || doc?.querySelector?.('button.btn-primary, input.btn-success[type="submit"], input.btn-primary[type="submit"]')
                || doc?.querySelector?.('form .submit-group button[type="submit"], form .submit-group input[type="submit"], form button[type="submit"], form input[type="submit"]')
                || null;
        }

        function findNotCompletedButtonInDocument(doc) {
            return doc?.querySelector?.('button[onclick*="saveAndClose(this, 2)"]')
                || doc?.querySelector?.('button[onclick*="saveAndClose(this, 21)"]')
                || null;
        }

        function getFormActionUrl(form, fallbackUrl) {
            const action = form?.getAttribute?.('action') || fallbackUrl || window.location.href;
            return new URL(action, fallbackUrl || window.location.href).toString();
        }

        function getSelectedOptionText(select) {
            const options = Array.from(select?.options || []);
            const selected = options.find((option) => option.selected)
                || options.find((option) => String(option.value) === String(select?.value || ''));
            return normalizeText(selected?.textContent || '');
        }

        function applyAbakanCityIfNeeded(doc, formData) {
            const citySelect = doc?.querySelector?.(SELECTORS.citySelect);
            if (!citySelect || !formData) return false;
            const currentCity = getSelectedOptionText(citySelect);
            const shouldChange = TRIGGER_CITIES.some((city) => currentCity.toLowerCase() === String(city).toLowerCase());
            if (!shouldChange) return false;
            const abakanOption = Array.from(citySelect.options || []).find((option) => normalizeText(option.textContent) === 'Абакан');
            if (!abakanOption) return false;
            formData.set('CustomerRequest[city_id]', String(abakanOption.value || ''));
            return true;
        }

        function setDocumentStatusReason(doc, targetStatusId) {
            const select = getDocumentStatusSelect(doc);
            if (!select) return false;
            select.value = String(targetStatusId);
            const options = Array.from(select.options || []);
            const matchedIndex = options.findIndex((option) => String(option.value) === String(targetStatusId));
            if (matchedIndex >= 0) {
                select.selectedIndex = matchedIndex;
                options[matchedIndex].selected = true;
            }
            return String(select.value) === String(targetStatusId) || matchedIndex >= 0;
        }

        async function fetchDocumentByPost(url, formData, label) {
            const response = await fetch(url, {
                method: 'POST',
                body: formData,
                credentials: 'include',
                cache: 'no-store',
                redirect: 'follow'
            });
            if (!response.ok) {
                throw new Error(`${label || 'POST'} HTTP ${response.status}`);
            }
            const html = await response.text();
            return {
                url: response.url || url,
                doc: new DOMParser().parseFromString(String(html || ''), 'text/html')
            };
        }

        async function prepareReasonDocumentByPost(requestId, updateDoc, updateUrl) {
            if (getDocumentStatusSelect(updateDoc)) {
                return { doc: updateDoc, url: updateUrl };
            }

            const actionButton = findNotCompletedButtonInDocument(updateDoc);
            if (!actionButton) {
                throw new Error(`Заявка ${requestId}: не найдена кнопка "Не оформлена"`);
            }

            const form = (actionButton.form || actionButton.closest?.('form')) || getDocumentCustomerRequestForm(updateDoc);
            if (!form) {
                throw new Error(`Заявка ${requestId}: форма заявки не найдена`);
            }

            const formData = new FormData(form);
            applyAbakanCityIfNeeded(updateDoc, formData);
            formData.set('precheck_to_nottaken', '1');
            if (!formData.has('CustomerRequest[status]')) {
                formData.set('CustomerRequest[status]', '20');
            }
            if (actionButton.name) {
                formData.set(actionButton.name, actionButton.value || '1');
            }

            const actionUrl = getFormActionUrl(form, updateUrl);
            const prepared = await fetchDocumentByPost(actionUrl, formData, `Заявка ${requestId}: подготовка НФ`);
            if (!getDocumentStatusSelect(prepared.doc)) {
                throw new Error(`Заявка ${requestId}: CRM не вернула форму выбора причины`);
            }
            return prepared;
        }

        async function submitRequestByPost(requestId, targetStatusId = TARGET_STATUS_ID) {
            const updateUrl = buildUpdateRequestUrl(requestId);
            const updateDoc = await fetchHtmlDocument(updateUrl);
            const prepared = await prepareReasonDocumentByPost(requestId, updateDoc, updateUrl);
            const reasonDoc = prepared.doc;
            const form = getDocumentCustomerRequestForm(reasonDoc);
            if (!form) {
                throw new Error(`Заявка ${requestId}: форма причины не найдена`);
            }

            if (!setDocumentStatusReason(reasonDoc, targetStatusId)) {
                throw new Error(`Заявка ${requestId}: причина ${targetStatusId} не найдена в списке`);
            }

            const formData = new FormData(form);
            formData.set('CustomerRequest[status_change_type]', String(targetStatusId));
            const saveButton = getDocumentSaveButton(reasonDoc);
            if (saveButton?.name) {
                formData.set(saveButton.name, saveButton.value || '1');
            }

            const actionUrl = getFormActionUrl(form, prepared.url || updateUrl);
            const requestPromise = fetch(actionUrl, {
                method: normalizeText(form.getAttribute('method') || 'POST').toUpperCase() || 'POST',
                body: formData,
                credentials: 'include',
                cache: 'no-store',
                redirect: 'follow'
            });
            requestPromise
                .then((response) => {
                    if (!response?.ok) {
                        bulkLog(`POST заявки ${requestId} вернул HTTP ${response ? response.status : 'нет ответа'}`);
                    }
                })
                .catch((error) => {
                    bulkLog(`POST заявки ${requestId} не завершился`, error);
                });
            return true;
        }

        function claimNextPostRequestId() {
            let claimedId = '';
            updateQueue((queue) => {
                if (!queue || queue.status !== 'running' || queue.engine !== POST_ENGINE) return queue;
                const nextId = String(queue.ids?.[queue.currentIndex] || '').trim();
                if (!nextId) return queue;
                claimedId = nextId;
                queue.currentIndex += 1;
                queue.updatedAt = Date.now();
                return queue;
            });
            return claimedId;
        }

        function finishClaimedPostRequest(requestId, ok, reason = '') {
            updateQueue((queue) => {
                if (!queue || queue.status !== 'running' || queue.engine !== POST_ENGINE) return queue;
                if (ok) {
                    queue.processed.push({ requestId: String(requestId), completedAt: Date.now(), engine: POST_ENGINE, mode: 'fire-and-forget' });
                } else {
                    queue.failed.push({ requestId: String(requestId), reason, failedAt: Date.now(), engine: POST_ENGINE });
                }
                queue.updatedAt = Date.now();
                if ((queue.processed.length + queue.failed.length) >= queue.ids.length) {
                    queue.status = 'completed';
                    queue.completedAt = Date.now();
                }
                return queue;
            });
        }

        async function runDirectBulkPostWorker(workerIndex) {
            while (true) {
                const queue = readQueue();
                if (!queue || queue.status !== 'running' || queue.engine !== POST_ENGINE) break;
                if (!isBulkQueueAuthorized(queue)) {
                    clearQueue();
                    break;
                }

                const requestId = claimNextPostRequestId();
                if (!requestId) break;

                try {
                    bulkLog(`POST-очистка заявки ${requestId} [поток ${workerIndex}]`);
                    await submitRequestByPost(requestId, TARGET_STATUS_ID);
                    finishClaimedPostRequest(requestId, true);
                } catch (error) {
                    const message = error?.message || String(error);
                    bulkLog(`Ошибка POST-очистки заявки ${requestId}:`, error);
                    finishClaimedPostRequest(requestId, false, message);
                }

                renderPanel();
                renderOverdueWarningDialog();
                renderFridayShiftPanel();
                renderMonthlyWarningDialog();
                if (POST_REQUEST_DELAY_MS > 0) {
                    await delay(POST_REQUEST_DELAY_MS);
                }
            }
        }

        async function runDirectBulkPostProcessing() {
            if (directBulkProcessingActive) return;
            const initialQueue = readQueue();
            if (!initialQueue || initialQueue.status !== 'running' || initialQueue.engine !== POST_ENGINE) return;
            if (!isBulkQueueAuthorized(initialQueue)) {
                clearQueue();
                return;
            }

            directBulkProcessingActive = true;
            try {
                const workerCount = Math.max(1, Number(POST_PARALLEL_LIMIT) || 1);
                await Promise.all(Array.from({ length: workerCount }, (_item, index) => runDirectBulkPostWorker(index + 1)));
            } finally {
                directBulkProcessingActive = false;
                renderPanel();
                renderOverdueWarningDialog();
                renderFridayShiftPanel();
                renderMonthlyWarningDialog();
                refreshOverdueRequestCount();
                setTimeout(() => { try { window.focus(); } catch (error) {} }, 50);
            }
        }

        function resumeDirectBulkPostProcessingIfNeeded() {
            const queue = readQueue();
            if (!queue || queue.status !== 'running' || queue.engine !== POST_ENGINE) return;
            void runDirectBulkPostProcessing();
        }

        async function forceSetStatusReasonAndSave(targetValue, requestId, timeout = 7000) {
            const startedAt = Date.now();
            while (Date.now() - startedAt < timeout) {
                const queue = readQueue();
                if (!queue || queue.status !== 'running') {
                    closeWorkerTab();
                    return;
                }
                const statusSelect = document.querySelector(SELECTORS.statusChangeType);
                const saveButton = document.querySelector(SELECTORS.saveButton);
                if (statusSelect && saveButton) {
                    statusSelect.value = String(targetValue);
                    const options = Array.from(statusSelect.options || []);
                    const matchedIndex = options.findIndex((option) => String(option.value) === String(targetValue));
                    if (matchedIndex >= 0) {
                        statusSelect.selectedIndex = matchedIndex;
                        options[matchedIndex].selected = true;
                    }
                    triggerElementEvents(statusSelect);
                    if (typeof window.$ !== 'undefined' && typeof window.$(statusSelect).val === 'function') {
                        window.$(statusSelect).val(String(targetValue)).trigger('change');
                    }
                    const appliedByValue = String(statusSelect.value) === String(targetValue);
                    const appliedByField = setNamedFieldValue('CustomerRequest[status_change_type]', targetValue);
                    if (appliedByValue || appliedByField) {
                        const form = getCustomerRequestForm();
                        const formData = buildBackgroundSubmitData(form, targetValue, saveButton);
                        void submitFormInBackground(form, formData).catch((error) => bulkLog(`Ошибка фонового сохранения причины для заявки ${requestId}:`, error));
                        addProcessedId(requestId);
                        sessionStorage.removeItem(PENDING_SUCCESS_KEY);
                        sessionStorage.removeItem(ATTEMPT_ID_KEY);
                        navigateWorkerToNext();
                        return;
                    }
                }
                await new Promise((resolve) => setTimeout(resolve, 1));
            }
            throw new Error(`Заявка ${requestId}: не удалось принудительно установить причину ${targetValue}`);
        }

        async function openNotCompletedAndSave(targetStatusId, requestId) {
            await setCityToAbakanIfNeeded();
            const actionButton = findNotCompletedButton();
            if (!actionButton) throw new Error('Не найдена штатная кнопка saveAndClose(this, 2|21)');
            sessionStorage.setItem(PENDING_SUCCESS_KEY, JSON.stringify({ requestId, targetStatusId, savedAt: Date.now(), source: 'native-not-completed' }));
            actionButton.click();
        }

        function closeWorkerTab() {
            if (!isWorkerTab() || workerTabClosing) return;
            workerTabClosing = true;
            sessionStorage.removeItem(WORKER_TAB_KEY);
            sessionStorage.removeItem(PENDING_SUCCESS_KEY);
            sessionStorage.removeItem(ATTEMPT_ID_KEY);
            const focusSourcePage = () => {
                try {
                    if (window.opener && !window.opener.closed) {
                        window.opener.focus();
                        setTimeout(() => {
                            try { window.opener.focus(); } catch (error) {}
                        }, 80);
                    }
                } catch (error) {
                    bulkLog('Не удалось вернуть фокус на исходную вкладку', error);
                }
            };
            const attemptClose = () => {
                focusSourcePage();
                window.close();
                try {
                    window.open('', '_self');
                    window.close();
                } catch (error) {
                    bulkLog('Не удалось закрыть вкладку worker', error);
                }
            };
            focusSourcePage();
            setTimeout(attemptClose, 50);
            setTimeout(attemptClose, 150);
            setTimeout(attemptClose, 350);
        }

        function navigateWorkerToNext() {
            const queue = readQueue();
            if (!queue || queue.status !== 'running') {
                closeWorkerTab();
                return;
            }
            const nextId = getExpectedRequestId(queue);
            if (!nextId) {
                closeWorkerTab();
                return;
            }
            const nextUrl = buildWorkerRequestUrl(nextId);
            if (window.location.href !== nextUrl) {
                window.location.replace(nextUrl);
            }
        }

        function finalizePendingSuccessIfNeeded() {
            const pending = getPendingSuccess();
            if (!pending) return;
            const currentId = getCurrentRequestId();
            const stillSameRequest = isUpdatePage() && currentId === pending.requestId;
            if (stillSameRequest) {
                const currentStatusText = getCurrentStatusText();
                const processingDialogOpen = Boolean(document.querySelector(SELECTORS.statusChangeType));
                const pendingAge = Date.now() - Number(pending.savedAt || 0);
                const statusChangedAwayFromClarification = currentStatusText && !isClarificationLikeStatus(currentStatusText);
                const buttonGone = !processingDialogOpen;
                if (statusChangedAwayFromClarification || buttonGone) {
                    addProcessedId(String(pending.requestId));
                    sessionStorage.removeItem(PENDING_SUCCESS_KEY);
                    sessionStorage.removeItem(ATTEMPT_ID_KEY);
                    return;
                }
                if (pendingAge > 7000) {
                    markCurrentAsFailed(`Заявка ${pending.requestId}: зависла после нажатия кнопки НФ`);
                    sessionStorage.removeItem(PENDING_SUCCESS_KEY);
                    sessionStorage.removeItem(ATTEMPT_ID_KEY);
                    navigateWorkerToNext();
                }
                return;
            }
            addProcessedId(String(pending.requestId));
            sessionStorage.removeItem(PENDING_SUCCESS_KEY);
            sessionStorage.removeItem(ATTEMPT_ID_KEY);
        }

        async function continuePendingNativeNotCompletedIfNeeded() {
            const pending = getPendingSuccess();
            if (!pending || pending.source !== 'native-not-completed') return false;
            const currentId = getCurrentRequestId();
            if (!isUpdatePage() || currentId !== String(pending.requestId || '')) return false;
            const statusSelect = document.querySelector(SELECTORS.statusChangeType);
            const saveButton = document.querySelector(SELECTORS.saveButton);
            if (!statusSelect || !saveButton) return false;
            await forceSetStatusReasonAndSave(String(pending.targetStatusId || TARGET_STATUS_ID), String(pending.requestId), 7000);
            return true;
        }

        async function processCurrentRequest() {
            const queue = readQueue();
            const expectedId = getExpectedRequestId(queue);
            const currentId = getCurrentRequestId();
            if (!expectedId || currentId !== expectedId) return;
            if (sessionStorage.getItem(ATTEMPT_ID_KEY) === currentId) return;
            sessionStorage.setItem(ATTEMPT_ID_KEY, currentId);
            try {
                bulkLog(`Обрабатываю заявку ${currentId}`);
                await openNotCompletedAndSave(TARGET_STATUS_ID, currentId);
            } catch (error) {
                bulkLog(`Ошибка обработки заявки ${currentId}:`, error);
                sessionStorage.removeItem(ATTEMPT_ID_KEY);
                markCurrentAsFailed(error.message || String(error));
                navigateWorkerToNext();
            }
        }

        async function fetchHtmlDocument(url) {
            const response = await fetch(url, { credentials: 'include', cache: 'no-store' });
            if (!response.ok) throw new Error(`Не удалось загрузить страницу: ${response.status}`);
            const html = await response.text();
            return new DOMParser().parseFromString(html, 'text/html');
        }

        function findCreatedAtColumnIndex(doc) {
            const headerCells = Array.from(doc.querySelectorAll('table thead th'));
            const matchers = [/дата\s*созд/i, /создан/i, /created/i, /^созд/i];
            return headerCells.findIndex((cell) => matchers.some((pattern) => pattern.test(normalizeText(cell.textContent).toLowerCase())));
        }

        function parseRequestsFromDocument(doc, options = {}) {
            const includeRecent = options.includeRecent === true;
            const createdAtColumnIndex = findCreatedAtColumnIndex(doc);
            const items = [];
            const skippedRecentIds = [];
            doc.querySelectorAll('table tbody tr').forEach((row) => {
                const link = row.querySelector(SELECTORS.requestLinks);
                if (!link) return;
                let requestId = '';
                try {
                    const url = new URL(link.href, window.location.origin);
                    requestId = String(url.searchParams.get('id') || '').trim();
                } catch (error) {
                    if (!/^\d{2}:\d{2}$/.test(draftTime)) {
                        alert('Сначала укажи полное время в формате ЧЧ:ММ.');
                        return;
                    }
                }
                if (!requestId) return;
                const cells = Array.from(row.querySelectorAll('td'));
                const createdAtText = createdAtColumnIndex >= 0 ? normalizeText(cells[createdAtColumnIndex]?.textContent || '') : '';
                if (!includeRecent && createdAtText && !isOlderThanPreviousCalendarDay(createdAtText)) {
                    skippedRecentIds.push(requestId);
                    return;
                }
                items.push({ requestId, createdAtText });
            });
            return { items, createdAtColumnFound: createdAtColumnIndex >= 0, skippedRecentIds };
        }

        function getLastPageNumber(doc) {
            const pageNumbers = [1];
            doc.querySelectorAll('a[href]').forEach((link) => {
                try {
                    const url = new URL(link.href, window.location.origin);
                    const page = Number(url.searchParams.get('page') || '1');
                    if (Number.isFinite(page) && page > 0) pageNumbers.push(page);
                } catch (error) {
                }
            });
            return Math.max(...pageNumbers);
        }

        function buildPageUrl(baseUrl, pageNumber) {
            const url = new URL(baseUrl);
            if (pageNumber <= 1) url.searchParams.delete('page');
            else url.searchParams.set('page', String(pageNumber));
            return url.toString();
        }

        async function collectIdsFromFilter(options = {}) {
            const filterUrl = buildBulkFilterUrl();
            if (!isBulkAuthorAllowed()) {
                throw new Error('Автоочистка доступна только когда script нашёл номер договора в шапке CRM.');
            }

            if (!filterUrl) {
                throw new Error('Не удалось построить фильтр автоочистки: author_id не найден в шапке CRM.');
            }

            const includeRecent = options.includeRecent === true;
            const firstDoc = await fetchHtmlDocument(filterUrl);
            const lastPage = getLastPageNumber(firstDoc);
            const allIds = new Set();
            const skippedRecentIds = new Set();
            let createdAtColumnFound = false;
            const firstPageData = parseRequestsFromDocument(firstDoc, { includeRecent });
            createdAtColumnFound = firstPageData.createdAtColumnFound;
            firstPageData.items.forEach((item) => allIds.add(item.requestId));
            firstPageData.skippedRecentIds.forEach((requestId) => skippedRecentIds.add(requestId));
            const pageNumbers = [];
            for (let page = 2; page <= lastPage; page += 1) pageNumbers.push(page);
            const pageDocs = await Promise.all(pageNumbers.map((page) => fetchHtmlDocument(buildPageUrl(filterUrl, page))));
            pageDocs.forEach((pageDoc) => {
                const pageData = parseRequestsFromDocument(pageDoc, { includeRecent });
                createdAtColumnFound = createdAtColumnFound || pageData.createdAtColumnFound;
                pageData.items.forEach((item) => allIds.add(item.requestId));
                pageData.skippedRecentIds.forEach((requestId) => skippedRecentIds.add(requestId));
            });
            return { ids: Array.from(allIds), skippedRecentCount: skippedRecentIds.size, createdAtColumnFound, totalFoundCount: allIds.size + skippedRecentIds.size };
        }

        async function refreshOverdueRequestCount() {
            if (!isIndexPage()) return;
            if (!isBulkAuthorAllowed()) {
                overdueRequestCount = 0;
                cancelOverdueWarningCountdown(false);
                cancelFridayWarningCountdown(false);
                cancelMonthlyWarningCountdown(false);
                resetFridayAutoStartState();
                renderPanel();
                renderFridayShiftPanel();
                renderMonthlyWarningDialog();
                return;
            }

            const currentQueue = readQueue();
            if (currentQueue && (currentQueue.status === 'building' || currentQueue.status === 'running')) return;
            try {
                const result = await collectIdsFromFilter();
                overdueRequestCount = result.ids.length;
                periodicOverdueRefreshNextAt = Date.now() + OVERDUE_REFRESH_INTERVAL_MS;
                if (overdueRequestCount > 0) { overdueWarningSuppressedKey = ''; } // сбрасываем заглушку — предлагать очистку всегда
                renderPanel();
                renderFridayShiftPanel();
                evaluateOverdueAutoStart();
                evaluateFridayAutoStart();
                evaluateMonthlyAutoStart();
            } catch (error) {
                bulkLog('Не удалось обновить количество просроченных заявок', error);
            }
        }

        function escapeHtml(value) {
            return String(value || '')
                .replace(/&/g, '&amp;')
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#39;');
        }

        function formatButtonLabel(icon) {
            return escapeHtml(icon);
        }

        function getButtonLabel(queue) {
            if (!queue) {
                return formatButtonLabel(DEFAULT_BUTTON_LABEL);
            }

            if (queue.status === 'building') {
                return formatButtonLabel(BUILDING_BUTTON_LABEL);
            }

            if (queue.status === 'running') {
                return formatButtonLabel(RUNNING_BUTTON_LABEL);
            }

            if (queue.status === 'completed') {
                return formatButtonLabel(DONE_BUTTON_LABEL);
            }

            if (queue.status === 'empty') {
                return formatButtonLabel(EMPTY_BUTTON_LABEL);
            }

            return formatButtonLabel(DEFAULT_BUTTON_LABEL);
        }

        function getButtonModeClass(queue) {
            return 'bulk-nf-clarify-amber';
        }

        function shouldShowBulkActionButton(queue = readQueue()) {
            if (!isIndexPage() || !isBulkAuthorAllowed()) {
                return false;
            }

            if (shouldTrackFridayShiftSchedule()) {
                return true;
            }

            return Boolean(queue);
        }

        function openFridayShiftPanelFromButton() {
            if (!shouldTrackFridayShiftSchedule()) {
                return;
            }

            setFridayShiftPanelMinimized(false);
            if (!hasSavedFridaySchedule() || !hasConfirmedFridaySchedule()) {
                fridayShiftEditing = true;
            }
            renderFridayShiftPanel();
        }

        function handleBulkButtonClick(event) {
            if (event) {
                event.preventDefault();
            }

            openFridayShiftPanelFromButton();
        }

        function syncButtonSizeWithReference(button, referenceButton) {
            if (!button || !referenceButton) {
                return;
            }

            const referenceRect = referenceButton.getBoundingClientRect();
            const referenceStyles = window.getComputedStyle(referenceButton);
            const targetHeight = Math.round(referenceRect.height);

            button.style.minWidth = `${BUTTON_WIDTH}px`;
            button.style.height = `${targetHeight}px`;
            button.style.padding = '0 8px';
            button.style.fontSize = referenceStyles.fontSize;
            button.style.fontWeight = referenceStyles.fontWeight;
            button.style.lineHeight = '1';
            button.style.borderRadius = referenceStyles.borderRadius;
            button.style.whiteSpace = 'nowrap';
            button.style.boxSizing = 'border-box';
        }

        function lockButtonWidth(button, queue) {
            if (!button) {
                return;
            }

            button.style.width = 'auto';
            button.style.minWidth = `${BUTTON_WIDTH}px`;

            const shouldMeasureBaseWidth = !queue;
            if (shouldMeasureBaseWidth) {
                const measuredWidth = Math.max(BUTTON_WIDTH, Math.round(button.getBoundingClientRect().width));
                if (measuredWidth > 0) {
                    bulkButtonLockedWidth = measuredWidth;
                }
            }

            const targetWidth = bulkButtonLockedWidth || Math.max(BUTTON_WIDTH, Math.round(button.getBoundingClientRect().width));
            button.style.width = `${targetWidth}px`;
            button.style.minWidth = `${targetWidth}px`;
        }

        function scheduleQueueResetIfFinished(queue) {
            if (buttonResetTimer) {
                clearTimeout(buttonResetTimer);
                buttonResetTimer = null;
            }

            if (!queue || (queue.status !== 'completed' && queue.status !== 'stopped' && queue.status !== 'empty')) {
                return;
            }

            buttonResetTimer = setTimeout(() => {
                clearQueue();
                renderPanel();
                renderOverdueWarningDialog();
                refreshOverdueRequestCount();
            }, 2500);
        }

        function cleanupStaleQueueOnLoad() {
            const queue = readQueue();
            if (!queue) {
                return;
            }

            const isReloadNavigation = getNavigationType() === 'reload';
            const isActiveState = queue.status === 'running' || queue.status === 'building';
            const isPostRunningQueue = queue.engine === POST_ENGINE && queue.status === 'running';
            if (isReloadNavigation && isActiveState && isIndexPage() && !isPostRunningQueue) {
                clearQueue();
                sessionStorage.removeItem(PENDING_SUCCESS_KEY);
                sessionStorage.removeItem(ATTEMPT_ID_KEY);
                sessionStorage.removeItem(INDEX_SESSION_KEY);
                return;
            }

            const now = Date.now();
            const updatedAt = Number(queue.updatedAt || queue.startedAt || 0);
            const age = now - updatedAt;
            const isFinishedState = queue.status === 'stopped' || queue.status === 'completed';
            const isStaleRunningState = queue.status === 'running' && queue.engine !== POST_ENGINE && age > 15000;
            const isStaleBuildingState = queue.status === 'building' && age > 10000;

            if (isFinishedState || isStaleRunningState || isStaleBuildingState) {
                clearQueue();
                sessionStorage.removeItem(PENDING_SUCCESS_KEY);
                sessionStorage.removeItem(ATTEMPT_ID_KEY);
            }
        }

        function findOpenAllNumbersButton() {
            return document.querySelector('#clipboard-open-all-btn')
                || Array.from(document.querySelectorAll('button')).find((button) => normalizeText(button.textContent).toLowerCase().includes('открыть все номера'))
                || null;
        }

        function positionBulkPanel() {
            const panel = document.getElementById('bulk-nf-clarify-panel');
            if (!panel) return;

            if (!shouldShowBulkActionButton()) {
                panel.style.display = 'none';
                panel.style.visibility = 'hidden';
                return;
            }

            const referenceButton = findOpenAllNumbersButton();
            if (!referenceButton) {
                panel.style.visibility = 'hidden';
                return;
            }

            if (panel.parentElement !== document.body) {
                document.body.appendChild(panel);
            }

            const startButton = panel.querySelector('#bulk-nf-clarify-start');
            if (startButton) {
                syncButtonSizeWithReference(startButton, referenceButton);
                lockButtonWidth(startButton, readQueue());
            }

            const rect = referenceButton.getBoundingClientRect();
            const panelRect = panel.getBoundingClientRect();
            panel.style.position = 'fixed';
            panel.style.marginRight = '0';
            panel.style.zIndex = '9999';
            panel.style.top = `${Math.round(rect.top)}px`;
            panel.style.left = `${Math.max(8, Math.round(rect.left - (panelRect.width || BUTTON_WIDTH) - 4))}px`;
            panel.style.height = `${Math.round(rect.height)}px`;
            panel.style.right = 'auto';
            panel.style.visibility = 'visible';
        }

        function requestBulkPanelPositionUpdate() {
            if (bulkPanelPositionAnimationFrame !== null) {
                cancelAnimationFrame(bulkPanelPositionAnimationFrame);
            }

            bulkPanelPositionAnimationFrame = requestAnimationFrame(() => {
                bulkPanelPositionAnimationFrame = null;
                positionBulkPanel();
            });
        }

        function startBulkPanelTracking() {
            if (bulkPanelPositionTimer !== null) return;
            bulkPanelPositionTimer = window.setInterval(requestBulkPanelPositionUpdate, 250);
            window.addEventListener('resize', requestBulkPanelPositionUpdate);

            // MutationObserver УБРАН: он наблюдал document.body с subtree:true и
            // вызывал getBoundingClientRect() через rAF на КАЖДУЮ DOM-мутацию
            // (insertBefore из refreshTable / clarify-refresh = 5-30 мутаций/тик).
            // Каждый getBoundingClientRect в rAF → принудительный reflow следующего кадра.
            // Интервал 250 мс достаточен для позиционирования панели.
        }

        function ensurePanel() {
            if (!isIndexPage()) return null;
            const existing = document.getElementById('bulk-nf-clarify-panel');
            if (existing) {
                positionBulkPanel();
                return existing;
            }
            const panel = document.createElement('div');
            panel.id = 'bulk-nf-clarify-panel';
            panel.innerHTML = `<div class="bulk-nf-clarify-actions"><button id="bulk-nf-clarify-start" class="btn bulk-nf-clarify-amber" type="button">${DEFAULT_BUTTON_LABEL}</button></div>`;
            document.body.appendChild(panel);
            panel.style.zIndex = '9999';
            panel.querySelector('#bulk-nf-clarify-start').addEventListener('click', handleBulkButtonClick);
            requestBulkPanelPositionUpdate();
            renderPanel();
            return panel;
        }

        function renderPanel() {
            const panel = document.getElementById('bulk-nf-clarify-panel');
            if (!panel) return;
            const queue = readQueue();
            const startButton = panel.querySelector('#bulk-nf-clarify-start');
            const shouldShowButton = shouldShowBulkActionButton(queue);

            panel.style.display = shouldShowButton ? 'inline-flex' : 'none';
            panel.style.visibility = shouldShowButton ? 'visible' : 'hidden';

            if (!shouldShowButton) {
                scheduleQueueResetIfFinished(queue);
                return;
            }

            startButton.innerHTML = getButtonLabel(queue);
            startButton.disabled = false;
            startButton.classList.remove('btn-primary', 'btn-success', 'btn-danger', 'btn-default', 'btn-warning', 'bulk-nf-clarify-amber');
            startButton.classList.add('btn', getButtonModeClass(queue));
            startButton.title = shouldTrackFridayShiftSchedule()
                ? 'Открыть окно АВТО ЧИСТКА'
                : 'Автоочистка выполняется';

            const openAllButton = findOpenAllNumbersButton();
            if (openAllButton) {
                syncButtonSizeWithReference(startButton, openAllButton);
            }

            lockButtonWidth(startButton, queue);

            scheduleQueueResetIfFinished(queue);
        }

        function ensureOverdueWarningDialog() {
            if (!isIndexPage()) return null;

            let dialog = document.getElementById('bulk-nf-clarify-warning');
            if (!dialog) {
                dialog = document.createElement('div');
                dialog.id = 'bulk-nf-clarify-warning';
                dialog.innerHTML = `
                    <div class="bulk-nf-clarify-warning__card">
                        <div class="bulk-nf-clarify-warning__title">Просроченные заявки</div>
                        <div class="bulk-nf-clarify-warning__text" id="bulk-nf-clarify-warning-text"></div>
                        <div class="bulk-nf-clarify-warning__actions">
                            <button type="button" class="btn btn-warning" id="bulk-nf-clarify-warning-start">Запустить сейчас</button>
                            <button type="button" class="btn btn-default" id="bulk-nf-clarify-warning-cancel">Отмена</button>
                        </div>
                    </div>
                `;
                document.body.appendChild(dialog);

                dialog.querySelector('#bulk-nf-clarify-warning-start').addEventListener('click', () => {
                    cancelOverdueWarningCountdown(false);
                    void launchBulkProcessing({ includeRecent: false, skipConfirm: true, source: 'overdue-warning-manual' });
                });

                dialog.querySelector('#bulk-nf-clarify-warning-cancel').addEventListener('click', () => {
                    cancelOverdueWarningCountdown(true);
                });
            }

            return dialog;
        }

        function renderOverdueWarningDialog() {
            const dialog = ensureOverdueWarningDialog();
            if (!dialog) return;

            const queue = readQueue();
            const title = dialog.querySelector('.bulk-nf-clarify-warning__title');
            const text = dialog.querySelector('#bulk-nf-clarify-warning-text');
            const actions = dialog.querySelector('.bulk-nf-clarify-warning__actions');
            const isPostQueue = queue && queue.engine === POST_ENGINE;
            if (isPostQueue && (queue.status === 'building' || queue.status === 'running' || queue.status === 'completed' || queue.status === 'empty')) {
                if (actions) actions.style.display = 'none';

                if (queue.status === 'building') {
                    if (title) title.textContent = 'Автоочистка запускается';
                    if (text) text.textContent = 'Очищено заявок 0/0';
                    dialog.classList.add('is-visible');
                    return;
                }

                const total = Number(queue.ids?.length || queue.totalFoundCount || 0);
                const processed = Number(queue.processed?.length || 0);
                const failed = Number(queue.failed?.length || 0);
                const cleaned = processed + failed;

                if (queue.status === 'completed') {
                    if (title) title.textContent = 'Автоочистка готова';
                    if (text) text.textContent = `Очищено заявок ${cleaned}/${total}`;
                    dialog.classList.add('is-visible');
                    return;
                }

                if (queue.status === 'empty') {
                    if (title) title.textContent = 'Автоочистка готова';
                    if (text) text.textContent = 'Очищено заявок 0/0';
                    dialog.classList.add('is-visible');
                    return;
                }

                if (title) title.textContent = 'Автоочистка выполняется';
                if (text) {
                    text.textContent = `Очищено заявок ${cleaned}/${total}`;
                }
                dialog.classList.add('is-visible');
                return;
            }

            if (actions) actions.style.display = '';
            if (title) title.textContent = 'Просроченные заявки';

            if (!overdueWarningEndsAt || !overdueWarningCountSnapshot) {
                dialog.classList.remove('is-visible');
                return;
            }

            const secondsLeft = Math.max(0, Math.ceil((overdueWarningEndsAt - Date.now()) / 1000));
            if (text) {
                text.textContent = `Найдено ${overdueWarningCountSnapshot} просроченных заявок. Автозапуск через ${secondsLeft} сек.`;
            }
            dialog.classList.add('is-visible');
        }

        function cancelOverdueWarningCountdown(suppressCurrent = false) {
            if (overdueWarningInterval) {
                clearInterval(overdueWarningInterval);
                overdueWarningInterval = null;
            }

            if (suppressCurrent && overdueWarningCountSnapshot > 0) {
                overdueWarningSuppressedKey = String(overdueWarningCountSnapshot);
            }

            overdueWarningEndsAt = 0;
            overdueWarningCountSnapshot = 0;
            renderOverdueWarningDialog();
        }

        function schedulePeriodicOverdueRefresh(force = false) {
            if (!isIndexPage()) return;
            if (!isBulkAuthorAllowed()) return;
            if (!isCleanupTabActive()) return;
            if (periodicOverdueRefreshInFlight) return;
            if (!force && Date.now() < periodicOverdueRefreshNextAt) return;

            periodicOverdueRefreshInFlight = true;
            periodicOverdueRefreshNextAt = Date.now() + OVERDUE_REFRESH_INTERVAL_MS;
            Promise.resolve(refreshOverdueRequestCount())
                .catch((error) => bulkLog('Не удалось обновить просроченные заявки по таймеру', error))
                .finally(() => {
                    periodicOverdueRefreshInFlight = false;
                });
        }

        function scheduleNextOverdueMidnightCheck() {
            if (overdueMidnightTimer !== null) {
                clearTimeout(overdueMidnightTimer);
                overdueMidnightTimer = null;
            }

            const now = new Date();
            const nextMidnight = new Date(now);
            nextMidnight.setHours(24, 0, 1, 0);
            const delay = Math.max(1000, nextMidnight.getTime() - now.getTime());

            overdueMidnightTimer = window.setTimeout(() => {
                overdueMidnightTimer = null;
                checkDailyOverdueDateBoundary();
                scheduleNextOverdueMidnightCheck();
            }, delay);
        }

        function checkDailyOverdueDateBoundary(options = {}) {
            if (!isIndexPage()) return false;

            const todayKey = getTodayDateKey();
            const dateChanged = Boolean(overdueObservedDateKey) && overdueObservedDateKey !== todayKey;
            const initialize = !overdueObservedDateKey;
            overdueObservedDateKey = todayKey;

            if (!dateChanged && !initialize && options.force !== true) {
                return false;
            }

            if (dateChanged) {
                // После 00:00 прежнее количество уже устарело: заявки могли
                // перейти в просроченные именно при смене календарной даты.
                overdueRequestCount = 0;
                overdueWarningSuppressedKey = '';
                periodicOverdueRefreshNextAt = 0;
                cancelOverdueWarningCountdown(false);
                bulkLog(`Наступил новый день ${todayKey}: принудительно перепроверяю просроченные заявки`);
            }

            schedulePeriodicOverdueRefresh(true);
            return dateChanged;
        }

        function beginOverdueWarningCountdown(count) {
            cancelOverdueWarningCountdown(false);
            overdueWarningCountSnapshot = count;
            overdueWarningEndsAt = Date.now() + OVERDUE_AUTO_START_DELAY_MS;
            renderOverdueWarningDialog();

            overdueWarningInterval = setInterval(() => {
                const queue = readQueue();
                if (isQueueBusy(queue) || overdueRequestCount <= 0) {
                    cancelOverdueWarningCountdown(false);
                    return;
                }

                if (!isCleanupTabActive()) {
                    cancelOverdueWarningCountdown(false);
                    return;
                }

                if (Date.now() >= overdueWarningEndsAt) {
                    cancelOverdueWarningCountdown(false);
                    void launchBulkProcessing({ includeRecent: false, skipConfirm: true, source: 'overdue-warning-auto' });
                    return;
                }

                renderOverdueWarningDialog();
            }, 250);
        }

        function evaluateOverdueAutoStart() {
            if (!isIndexPage()) return;

            if (!isBulkAuthorAllowed()) {
                overdueRequestCount = 0;
                cancelOverdueWarningCountdown(false);
                return;
            }

            const queue = readQueue();
            if (isQueueBusy(queue)) {
                cancelOverdueWarningCountdown(false);
                return;
            }

            if (overdueRequestCount <= 0) {
                overdueWarningSuppressedKey = '';
                cancelOverdueWarningCountdown(false);
                return;
            }

            if (overdueWarningEndsAt > 0) {
                if (overdueWarningCountSnapshot !== overdueRequestCount) {
                    beginOverdueWarningCountdown(overdueRequestCount);
                } else {
                    renderOverdueWarningDialog();
                }
                return;
            }

            if (overdueWarningSuppressedKey === String(overdueRequestCount)) {
                return;
            }

            beginOverdueWarningCountdown(overdueRequestCount);
        }

        function shouldTriggerMonthlyAutoStart(now = new Date()) {
            return now.getDate() === 1 && now.getHours() === 0 && now.getMinutes() < MONTHLY_AUTO_TRIGGER_WINDOW_MINUTES;
        }

        function ensureMonthlyWarningDialog() {
            if (!isIndexPage()) return null;

            let dialog = document.getElementById('bulk-nf-clarify-monthly-warning');
            if (!dialog) {
                dialog = document.createElement('div');
                dialog.id = 'bulk-nf-clarify-monthly-warning';
                dialog.innerHTML = `
                    <div class="bulk-nf-clarify-warning__card bulk-nf-clarify-warning__card--scheduled">
                        <div class="bulk-nf-clarify-warning__title">Ежемесячная автоочистка</div>
                        <div class="bulk-nf-clarify-warning__text" id="bulk-nf-clarify-monthly-warning-text"></div>
                        <div class="bulk-nf-clarify-warning__actions">
                            <button type="button" class="btn btn-warning" id="bulk-nf-clarify-monthly-warning-start">Запустить сейчас</button>
                            <button type="button" class="btn btn-default" id="bulk-nf-clarify-monthly-warning-cancel">Отмена</button>
                        </div>
                    </div>
                `;
                document.body.appendChild(dialog);

                dialog.querySelector('#bulk-nf-clarify-monthly-warning-start').addEventListener('click', () => {
                    const monthKey = monthlyWarningMonthKey || getCurrentMonthKey();
                    cancelMonthlyWarningCountdown(false);
                    void launchMonthlyScheduledBulkProcessing('monthly-warning-manual', monthKey);
                });

                dialog.querySelector('#bulk-nf-clarify-monthly-warning-cancel').addEventListener('click', () => {
                    cancelMonthlyWarningCountdown(true);
                });
            }

            return dialog;
        }

        function renderMonthlyWarningDialog() {
            const dialog = ensureMonthlyWarningDialog();
            if (!dialog) return;

            if (!monthlyWarningEndsAt || !monthlyWarningMonthKey) {
                dialog.classList.remove('is-visible');
                return;
            }

            const secondsLeft = Math.max(0, Math.ceil((monthlyWarningEndsAt - Date.now()) / 1000));
            const [year = '', month = ''] = monthlyWarningMonthKey.split('-');
            const text = dialog.querySelector('#bulk-nf-clarify-monthly-warning-text');
            if (text) {
                text.textContent = `Наступило 01.${month}.${year}. Очистка всех заявок на уточнении запустится через ${secondsLeft} сек.`;
            }
            dialog.classList.add('is-visible');
        }

        function cancelMonthlyWarningCountdown(suppressCurrent = false) {
            if (monthlyWarningInterval) {
                clearInterval(monthlyWarningInterval);
                monthlyWarningInterval = null;
            }

            if (suppressCurrent && monthlyWarningMonthKey) {
                monthlyWarningSuppressedMonthKey = monthlyWarningMonthKey;
            }

            monthlyWarningEndsAt = 0;
            monthlyWarningMonthKey = '';
            renderMonthlyWarningDialog();
        }

        async function launchMonthlyScheduledBulkProcessing(source, monthKey = getCurrentMonthKey()) {
            markMonthlyAutoRunForMonth(monthKey);
            cancelMonthlyWarningCountdown(false);
            try {
                await launchBulkProcessing({ includeRecent: true, skipConfirm: true, source });
            } catch (error) {
                GM_setValue(MONTHLY_AUTO_RUN_MONTH_KEY, '');
                throw error;
            }
        }

        function beginMonthlyWarningCountdown(monthKey = getCurrentMonthKey()) {
            cancelMonthlyWarningCountdown(false);
            monthlyWarningMonthKey = monthKey;
            monthlyWarningEndsAt = Date.now() + MONTHLY_AUTO_START_COUNTDOWN_MS;
            renderMonthlyWarningDialog();

            monthlyWarningInterval = window.setInterval(() => {
                const queue = readQueue();
                if (!isBulkAuthorAllowed() || isQueueBusy(queue)) {
                    cancelMonthlyWarningCountdown(false);
                    return;
                }

                if (hasMonthlyAutoRunForMonth(monthKey)) {
                    cancelMonthlyWarningCountdown(false);
                    return;
                }

                if (Date.now() >= monthlyWarningEndsAt) {
                    cancelMonthlyWarningCountdown(false);
                    void launchMonthlyScheduledBulkProcessing('monthly-warning-auto', monthKey).catch(() => {
                        GM_setValue(MONTHLY_AUTO_RUN_MONTH_KEY, '');
                    });
                    return;
                }

                renderMonthlyWarningDialog();
            }, 250);
        }

        function evaluateMonthlyAutoStart() {
            if (!isIndexPage()) return;

            if (monthlyWarningSuppressedMonthKey && monthlyWarningSuppressedMonthKey !== getCurrentMonthKey()) {
                monthlyWarningSuppressedMonthKey = '';
            }

            const queue = readQueue();
            if (!isBulkAuthorAllowed() || isQueueBusy(queue)) {
                cancelMonthlyWarningCountdown(false);
                return;
            }

            const now = new Date();
            const monthKey = getCurrentMonthKey(now);
            if (hasMonthlyAutoRunForMonth(monthKey)) {
                cancelMonthlyWarningCountdown(false);
                return;
            }

            if (!shouldTriggerMonthlyAutoStart(now)) {
                if (monthlyWarningMonthKey && monthlyWarningMonthKey !== monthKey) {
                    cancelMonthlyWarningCountdown(false);
                }
                return;
            }

            if (monthlyWarningSuppressedMonthKey && monthlyWarningSuppressedMonthKey === monthKey) {
                return;
            }

            if (monthlyWarningEndsAt > 0) {
                if (monthlyWarningMonthKey !== monthKey) {
                    beginMonthlyWarningCountdown(monthKey);
                } else {
                    renderMonthlyWarningDialog();
                }
                return;
            }

            beginMonthlyWarningCountdown(monthKey);
        }

        function shouldShowFridayShiftPanel() {
            if (!isIndexPage()) {
                return false;
            }

            if (isScheduleMenuDisplayTime()) {
                return true;
            }

            if (!shouldTrackFridayShiftSchedule()) {
                return false;
            }

            return hasFridayScheduleReachedDay();
        }

        function ensureFridayShiftPanel() {
            clearFridayScheduleIfButtonShouldStayHidden();
            resetFridayShiftScheduleForMenuIfNeeded();
            expandFridayShiftPanelForSessionIfNeeded();

            const existing = document.getElementById('bulk-nf-clarify-friday-panel');
            const existingDot = document.getElementById('bulk-nf-clarify-friday-dot');
            const existingWarning = document.getElementById('bulk-nf-clarify-friday-warning');

            if (!shouldTrackFridayShiftSchedule()) {
                cancelFridayWarningCountdown(false);
                if (existing) existing.remove();
                if (existingDot) existingDot.remove();
                if (existingWarning) existingWarning.remove();
                return null;
            }

            if (!shouldShowFridayShiftPanel()) {
                if (existing) existing.remove();
                if (existingDot) existingDot.remove();
                return null;
            }

            if (existing) return existing;

            const panel = document.createElement('div');
            panel.id = 'bulk-nf-clarify-friday-panel';
            panel.innerHTML = `
                <div class="bulk-nf-clarify-friday__card">
                    <div class="bulk-nf-clarify-friday__header">
                        <div class="bulk-nf-clarify-friday__title">${SCHEDULE_MENU_TITLE}</div>
                        <button type="button" class="bulk-nf-clarify-friday__minimize" id="bulk-nf-clarify-friday-minimize" aria-label="Свернуть окно">×</button>
                    </div>
                    <div class="bulk-nf-clarify-friday__saved" id="bulk-nf-clarify-friday-saved">
                        <div class="bulk-nf-clarify-friday__saved-label">Запланировано</div>
                        <div class="bulk-nf-clarify-friday__saved-value" id="bulk-nf-clarify-friday-saved-value"></div>
                        <button type="button" class="btn btn-default bulk-nf-clarify-friday__edit" id="bulk-nf-clarify-friday-edit">Изменить</button>
                    </div>
                    <div class="bulk-nf-clarify-friday__editor" id="bulk-nf-clarify-friday-editor">
                        <div class="bulk-nf-clarify-friday__field">
                            <label class="bulk-nf-clarify-friday__label" for="bulk-nf-clarify-friday-date">Дата</label>
                            <input id="bulk-nf-clarify-friday-date" class="bulk-nf-clarify-friday__date" type="date" />
                        </div>
                        <div class="bulk-nf-clarify-friday__field">
                            <label class="bulk-nf-clarify-friday__label" for="bulk-nf-clarify-friday-time">Время</label>
                            <input id="bulk-nf-clarify-friday-time" class="bulk-nf-clarify-friday__time" type="time" step="60" />
                        </div>
                        <div class="bulk-nf-clarify-friday__hint" id="bulk-nf-clarify-friday-hint"></div>
                        <button type="button" class="btn btn-warning bulk-nf-clarify-friday__apply" id="bulk-nf-clarify-friday-apply">Сохранить время</button>
                    </div>
                    <div class="bulk-nf-clarify-friday__status" id="bulk-nf-clarify-friday-status"></div>
                </div>
            `;
            document.body.appendChild(panel);

            const dateInput = panel.querySelector('#bulk-nf-clarify-friday-date');
            const timeInput = panel.querySelector('#bulk-nf-clarify-friday-time');
            fillFridayShiftEditor(panel, false);

            const handleDraftChange = () => {
                syncFridayShiftDraftDate(panel);
                updateFridayShiftEditorHint(panel);
            };
            dateInput.addEventListener('input', handleDraftChange);
            dateInput.addEventListener('change', handleDraftChange);
            timeInput.addEventListener('input', handleDraftChange);
            timeInput.addEventListener('change', handleDraftChange);

            panel.querySelector('#bulk-nf-clarify-friday-minimize').addEventListener('click', () => {
                setFridayShiftPanelMinimized(true);
                renderFridayShiftPanel();
            });

            panel.querySelector('#bulk-nf-clarify-friday-edit').addEventListener('click', () => {
                fridayShiftEditing = true;
                clearFridayScheduleConfirmed();
                resetFridayAutoStartState();
                cancelFridayWarningCountdown(false);
                fillFridayShiftEditor(panel, true);
                renderFridayShiftPanel();
            });

            panel.querySelector('#bulk-nf-clarify-friday-apply').addEventListener('click', () => {
                const nextTime = normalizeText(timeInput.value);
                if (!/^\d{2}:\d{2}$/.test(nextTime)) {
                    alert('Сначала укажи полное время в формате ЧЧ:ММ.');
                    return;
                }

                const draftDate = parseDateKey(dateInput.value) ? dateInput.value : getTodayDateKey();
                const nextDate = getNormalizedFridayShiftDateForTime(draftDate, nextTime);
                writeFridayShiftEnd(nextTime);
                writeFridayShiftDate(nextDate);
                markFridayScheduleConfirmed(`${nextDate}|${nextTime}`);
                clearFridayAutoRunToday();
                fridayWarningSuppressedKey = '';
                resetFridayAutoStartState();
                cancelFridayWarningCountdown(false);
                fridayShiftEditing = false;
                renderFridayShiftPanel();
                evaluateFridayAutoStart();
            });

            return panel;
        }

        function renderFridayShiftPanel() {
            const panel = ensureFridayShiftPanel();
            if (!panel) return;

            if (!hasSavedFridaySchedule() || !hasConfirmedFridaySchedule()) {
                fridayShiftEditing = true;
            }

            ensureFridayShiftMinimizedDot();

            if (isFridayShiftPanelMinimized()) {
                panel.style.display = 'none';
                return;
            }

            panel.style.display = 'flex';

            const dateInput = panel.querySelector('#bulk-nf-clarify-friday-date');
            const timeInput = panel.querySelector('#bulk-nf-clarify-friday-time');
            const savedNode = panel.querySelector('#bulk-nf-clarify-friday-saved');
            const savedLabelNode = panel.querySelector('.bulk-nf-clarify-friday__saved-label');
            const savedValueNode = panel.querySelector('#bulk-nf-clarify-friday-saved-value');
            const editorNode = panel.querySelector('#bulk-nf-clarify-friday-editor');
            const applyButton = panel.querySelector('#bulk-nf-clarify-friday-apply');
            const statusNode = panel.querySelector('#bulk-nf-clarify-friday-status');
            const queue = readQueue();
            const shiftDateText = readFridayShiftDate();
            const shiftEnd = parseScheduledDateTime(shiftDateText, readFridayShiftEnd());
            const autoStartAt = shiftEnd ? new Date(shiftEnd.getTime() - FRIDAY_AUTO_START_LEAD_MINUTES * 60 * 1000) : null;
            const now = new Date();
            const isEditing = fridayShiftEditing || !shiftEnd;

            if (savedNode) {
                savedNode.style.display = isEditing ? 'none' : 'flex';
            }

            if (editorNode) {
                editorNode.style.display = isEditing ? 'grid' : 'none';
            }

            if (applyButton) {
                applyButton.textContent = shiftEnd ? 'Сохранить изменения' : 'Сохранить время';
            }

            if (!isEditing && savedValueNode) {
                if (hasFridayAutoRunForCurrentSchedule()) {
                    if (savedLabelNode) {
                        savedLabelNode.textContent = 'Сегодня';
                    }
                    savedValueNode.textContent = 'Заявки сегодня все убраны';
                } else {
                    if (savedLabelNode) {
                        savedLabelNode.textContent = 'Запланировано';
                    }
                    savedValueNode.textContent = `${formatShiftDateLabel(shiftDateText)} ${readFridayShiftEnd()}`;
                }
            }

            if (isEditing) {
                updateFridayShiftEditorHint(panel);
                if (statusNode) statusNode.textContent = 'Время не задано. Укажи его и сохрани.';
                return;
            }

            if (!statusNode) return;

            if (isQueueBusy(queue)) {
                statusNode.textContent = 'Идёт обработка заявок на уточнении.';
                return;
            }

            if (!shiftEnd || !autoStartAt || !hasConfirmedFridaySchedule()) {
                statusNode.textContent = 'Время ещё не задано. Укажи его вручную и сохрани.';
                return;
            }

            const shiftEndText = readFridayShiftEnd();
            const shiftDateLabel = formatShiftDateLabel(shiftDateText);

            if (hasFridayAutoRunForCurrentSchedule()) {
                statusNode.textContent = '';
                return;
            }

            if (fridayWarningSuppressedKey && fridayWarningSuppressedKey === getFridayScheduleKey()) {
                statusNode.textContent = `Конец смены ${shiftDateLabel} ${shiftEndText}. Автозапуск отменён для этого времени. Нажми «Изменить», если нужно задать новое.`;
                return;
            }

            if (fridayWarningEndsAt > 0) {
                statusNode.textContent = `Конец смены ${shiftDateLabel} ${shiftEndText}. Показываю предупреждение перед запуском.`;
                return;
            }

            if (fridayAutoStartWaitingForFocus) {
                statusNode.textContent = `Конец смены ${shiftDateLabel} ${shiftEndText}. Переключись на эту вкладку, после возврата начнётся отсчёт 5с.`;
                return;
            }

            if (now < autoStartAt) {
                statusNode.textContent = `Конец смены ${shiftDateLabel} ${shiftEndText}. Автозапуск через ${formatRemainingTime(autoStartAt.getTime() - now.getTime())}.`;
                return;
            }

            statusNode.textContent = `Конец смены ${shiftDateLabel} ${shiftEndText}. Время наступило, жду возврата на эту вкладку.`;
        }

        function evaluateFridayAutoStart() {
            if (!shouldTrackFridayShiftSchedule()) {
                resetFridayAutoStartState();
                cancelFridayWarningCountdown(false);
                return;
            }

            if (fridayShiftEditing) {
                resetFridayAutoStartState();
                cancelFridayWarningCountdown(false);
                return;
            }

            const queue = readQueue();
            if (isQueueBusy(queue) || hasFridayAutoRunForCurrentSchedule()) {
                resetFridayAutoStartState();
                cancelFridayWarningCountdown(false);
                return;
            }

            const shiftEnd = parseScheduledDateTime(readFridayShiftDate(), readFridayShiftEnd());
            if (!shiftEnd || !hasConfirmedFridaySchedule()) {
                resetFridayAutoStartState();
                cancelFridayWarningCountdown(false);
                return;
            }

            if (fridayWarningSuppressedKey && fridayWarningSuppressedKey === getFridayScheduleKey()) {
                resetFridayAutoStartState();
                cancelFridayWarningCountdown(false);
                return;
            }

            const autoStartAt = new Date(shiftEnd.getTime() - FRIDAY_AUTO_START_LEAD_MINUTES * 60 * 1000);
            if (Date.now() < autoStartAt.getTime()) {
                resetFridayAutoStartState();
                cancelFridayWarningCountdown(false);
                return;
            }

            if (!isFridayShiftTabActive()) {
                resetFridayAutoStartState({ keepWaiting: true });
                cancelFridayWarningCountdown(false);
                return;
            }

            if (fridayWarningEndsAt <= 0) {
                fridayAutoStartWaitingForFocus = false;
                setFridayShiftPanelMinimized(false);
                beginFridayWarningCountdown();
                return;
            }

            renderFridayWarningDialog();
        }

        function startFridayShiftTracking() {
            if (fridayShiftTimer !== null) return;

            if (!fridayShiftFocusListenerBound) {
                const handleFridayShiftFocus = () => {
                    if (!isCleanupTabActive()) {
                        if (fridayWarningEndsAt > 0) {
                            cancelFridayWarningCountdown(false);
                            resetFridayAutoStartState({ keepWaiting: true });
                        }
                        if (overdueWarningEndsAt > 0) {
                            cancelOverdueWarningCountdown(false);
                        }
                        renderFridayShiftPanel();
                        renderOverdueWarningDialog();
                        renderMonthlyWarningDialog();
                        return;
                    }

                    checkDailyOverdueDateBoundary();
                    scheduleNextOverdueMidnightCheck();
                    schedulePeriodicOverdueRefresh(true);
                    renderOverdueWarningDialog();
                    evaluateOverdueAutoStart();
                    renderFridayShiftPanel();
                    evaluateFridayAutoStart();
                    evaluateMonthlyAutoStart();
                    renderMonthlyWarningDialog();
                };
                document.addEventListener('visibilitychange', handleFridayShiftFocus);
                window.addEventListener('focus', handleFridayShiftFocus);
                fridayShiftFocusListenerBound = true;
            }

            fridayShiftTimer = window.setInterval(() => {
                checkDailyOverdueDateBoundary();
                if (fridayAutoStartCountdownEndsAt > 0 && !isFridayShiftTabActive()) {
                    resetFridayAutoStartState({ keepWaiting: true });
                }
                renderFridayShiftPanel();
                evaluateFridayAutoStart();
                evaluateMonthlyAutoStart();
                schedulePeriodicOverdueRefresh();
            }, 1000);
        }

        async function launchBulkProcessing(options = {}) {
            const includeRecent = options.includeRecent === true;
            const skipConfirm = options.skipConfirm === true;
            const currentAuthorId = getCurrentBulkAuthorId();
            const filterUrl = buildBulkFilterUrl(currentAuthorId);

            if (!currentAuthorId) {
                throw new Error('Автоочистка недоступна: author_id не найден в шапке CRM.');
            }

            if (!filterUrl) {
                throw new Error('Автоочистка недоступна: не удалось собрать фильтр по текущему author_id.');
            }

            sessionStorage.setItem(INDEX_SESSION_KEY, String(Date.now()));
            const activeQueue = readQueue();
            if (isQueueBusy(activeQueue)) {
                if (!skipConfirm) {
                    alert('Обработка уже запущена');
                }
                return;
            }

            cancelOverdueWarningCountdown(false);
            cancelMonthlyWarningCountdown(false);
            writeQueue({ status: 'building', engine: POST_ENGINE, ids: [], currentIndex: 0, processed: [], failed: [], startedAt: Date.now(), updatedAt: Date.now(), sourcePageUrl: window.location.href, filterUrl, skippedRecentCount: 0, totalFoundCount: 0, sourceAuthorId: currentAuthorId });
            renderPanel();
            renderOverdueWarningDialog();
            renderFridayShiftPanel();
            renderMonthlyWarningDialog();
            try {
                const result = await collectIdsFromFilter({ includeRecent });
                const ids = result.ids;
                if (!ids.length) {
                    overdueRequestCount = 0;
                    writeQueue({
                        status: 'empty',
                        engine: POST_ENGINE,
                        ids: [],
                        currentIndex: 0,
                        processed: [],
                        failed: [],
                        startedAt: Date.now(),
                        updatedAt: Date.now(),
                        sourcePageUrl: window.location.href,
                        filterUrl,
                        sourceAuthorId: currentAuthorId,
                        skippedRecentCount: result.skippedRecentCount,
                        totalFoundCount: result.totalFoundCount
                    });
                    renderPanel();
                    renderOverdueWarningDialog();
                    renderFridayShiftPanel();
                    return;
                }
                if (!includeRecent && !result.createdAtColumnFound) {
                    clearQueue();
                    renderPanel();
                    renderOverdueWarningDialog();
                    alert('Не удалось определить колонку даты создания в таблице.');
                    return;
                }
                const confirmMessage = includeRecent
                    ? `Найдено заявок: ${ids.length}. Убираем все заявки из фильтра?`
                    : `Найдено заявок: ${ids.length}. Убираем?`;
                if (!skipConfirm && !window.confirm(confirmMessage)) {
                    clearQueue();
                    renderPanel();
                    renderOverdueWarningDialog();
                    return;
                }
                writeQueue({ status: 'running', engine: POST_ENGINE, ids, currentIndex: 0, processed: [], failed: [], startedAt: Date.now(), updatedAt: Date.now(), sourcePageUrl: window.location.href, filterUrl, skippedRecentCount: result.skippedRecentCount, totalFoundCount: result.totalFoundCount, sourceAuthorId: currentAuthorId });
                renderPanel();
                renderOverdueWarningDialog();
                renderFridayShiftPanel();
                void runDirectBulkPostProcessing();
            } catch (error) {
                clearQueue();
                renderPanel();
                renderOverdueWarningDialog();
                renderFridayShiftPanel();
                alert(`Ошибка запуска: ${error.message || String(error)}`);
            }
        }

        async function startBulkProcessing(event) {
            const includeRecent = Boolean(event && (event.ctrlKey || event.metaKey));
            await launchBulkProcessing({ includeRecent, skipConfirm: false, source: 'manual' });
        }

        function bindQueueListener() {
            GM_addValueChangeListener(QUEUE_KEY, () => {
                const queue = readQueue();
                if ((!queue || queue.status !== 'running') && workerTabHandle && typeof workerTabHandle.close === 'function') {
                    try { workerTabHandle.close(); } catch (error) {}
                    workerTabHandle = null;
                }
                if (queue && queue.status === 'running' && queue.engine === POST_ENGINE) {
                    void runDirectBulkPostProcessing();
                }
                if (!queue || queue.status === 'completed' || queue.status === 'stopped') {
                    const sourcePageUrl = queue?.sourcePageUrl || sessionStorage.getItem(SOURCE_PAGE_URL_KEY) || '';
                    if (sourcePageUrl && isIndexPage() && window.location.href !== sourcePageUrl) {
                        window.location.replace(sourcePageUrl);
                        return;
                    }
                    refreshOverdueRequestCount();
                    setTimeout(() => { try { window.focus(); } catch (error) {} }, 50);
                }
                renderPanel();
                renderOverdueWarningDialog();
                renderFridayShiftPanel();
                evaluateOverdueAutoStart();
                evaluateFridayAutoStart();
                evaluateMonthlyAutoStart();
                renderMonthlyWarningDialog();
            });
        }

        function bindWorkerQueueStopListener() {
            if (!isWorkerTab() || workerQueueListenerBound) return;
            workerQueueListenerBound = true;
            GM_addValueChangeListener(QUEUE_KEY, () => {
                const queue = readQueue();
                if (!queue || queue.status !== 'running') closeWorkerTab();
            });
        }

        function buildDebugDump() {
            const statusSelect = document.querySelector(SELECTORS.statusChangeType);
            const saveButton = document.querySelector(SELECTORS.saveButton);
            return [
                '=== BULK NF DEBUG DUMP ===',
                `timestamp=${new Date().toISOString()}`,
                `url=${window.location.href}`,
                `requestId=${getCurrentRequestId()}`,
                `statusText=${getCurrentStatusText()}`,
                `isWorkerTab=${isWorkerTab()}`,
                `queue=${JSON.stringify(readQueue(), null, 2)}`,
                `pending=${sessionStorage.getItem(PENDING_SUCCESS_KEY) || ''}`,
                `attemptId=${sessionStorage.getItem(ATTEMPT_ID_KEY) || ''}`,
                `saveButton=${saveButton ? saveButton.outerHTML : 'NOT_FOUND'}`,
                `statusSelect=${statusSelect ? statusSelect.outerHTML : 'NOT_FOUND'}`
            ].join('\n');
        }

        function ensureDebugButton() {
            if (!workerMode || !isUpdatePage()) return;
            if (document.getElementById(DEBUG_BUTTON_ID)) return;
            const button = document.createElement('button');
            button.id = DEBUG_BUTTON_ID;
            button.type = 'button';
            button.textContent = 'DBG';
            button.addEventListener('click', () => {
                copyTextToClipboard(buildDebugDump());
                alert('Диагностика скопирована в буфер');
            });
            document.body.appendChild(button);
        }

