const STATUS_DIAG_BUTTON_ID = 'crm-na-utoch-debug-copy';
const STATUS_BADGE_AUTO_CLICK_KEY = 'crm_status_badge_autoclick_v2';
const STATUS_DIAG_MAX_EVENTS = 320;
const STATUS_DIAG_MAX_ERRORS = 80;
const STATUS_DIAG_MAX_INTERACTIONS = 260;
const STATUS_DIAG_MAX_NETWORK = 160;
const STATUS_DIAG_MAX_MUTATIONS = 140;
const STATUS_DIAG_MAX_SNAPSHOTS = 40;
const STATUS_DIAG_STATE = {
    version: '24.05-universal-fulltrace',
    lastNaUtochnenii: null,
    lastSendCall: null,
    lastSendResult: null,
    lastClipboard: null,
    recentEvents: [],
    lastErrors: [],
    recentInteractions: [],
    networkLog: [],
    domMutations: [],
    snapshots: [],
    eventCounters: {},
    startedAt: new Date().toISOString(),
    runtimeHooksInstalled: false
};

function trimForDiag(value, maxLen = 4000) {
    const text = String(value || '');
    return text.length > maxLen ? `${text.slice(0, maxLen)}...[truncated]` : text;
}

function safeStringifyForDiag(value, maxLen = 12000) {
    try {
        const text = JSON.stringify(value, null, 2);
        return text.length > maxLen ? `${text.slice(0, maxLen)}...[truncated]` : text;
    } catch (error) {
        return `stringify_error=${String(error && error.message ? error.message : error)}`;
    }
}

function appendDiagBounded(list, item, maxLen) {
    if (!Array.isArray(list)) return;
    list.push(item);
    if (list.length > maxLen) {
        list.splice(0, list.length - maxLen);
    }
}

function isDiagElementVisible(element) {
    if (!(element instanceof Element)) return false;
    const style = window.getComputedStyle(element);
    if (!style) return false;
    if (style.display === 'none' || style.visibility === 'hidden' || Number(style.opacity || '1') === 0) {
        return false;
    }
    const rect = element.getBoundingClientRect();
    return rect.width > 0 && rect.height > 0;
}

function buildDiagElementPath(element, maxDepth = 6) {
    if (!(element instanceof Element)) return '';
    const parts = [];
    let node = element;
    let depth = 0;
    while (node && depth < maxDepth) {
        const tag = String(node.tagName || '').toLowerCase();
        if (!tag) break;
        let part = tag;
        if (node.id) {
            part += `#${node.id}`;
            parts.unshift(part);
            break;
        }
        if (node.classList && node.classList.length) {
            const cls = Array.from(node.classList).slice(0, 2).join('.');
            if (cls) part += `.${cls}`;
        }
        const parent = node.parentElement;
        if (parent) {
            const siblings = Array.from(parent.children).filter((child) => child.tagName === node.tagName);
            if (siblings.length > 1) {
                part += `:nth-of-type(${siblings.indexOf(node) + 1})`;
            }
        }
        parts.unshift(part);
        node = parent;
        depth += 1;
    }
    return parts.join(' > ');
}

function getDiagElementMeta(element) {
    if (!(element instanceof Element)) return null;
    const textSource = element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement || element instanceof HTMLSelectElement
        ? (element.value || '')
        : (element.textContent || '');
    return {
        tag: String(element.tagName || '').toLowerCase(),
        id: String(element.id || ''),
        name: String(element.getAttribute('name') || ''),
        type: String(element.getAttribute('type') || ''),
        className: trimForDiag(String(element.className || ''), 180),
        role: String(element.getAttribute('role') || ''),
        placeholder: trimForDiag(String(element.getAttribute('placeholder') || ''), 140),
        valuePreview: trimForDiag(String(textSource || '').replace(/\s+/g, ' '), 220),
        checked: element instanceof HTMLInputElement ? Boolean(element.checked) : undefined,
        disabled: 'disabled' in element ? Boolean(element.disabled) : false,
        readOnly: 'readOnly' in element ? Boolean(element.readOnly) : false,
        visible: isDiagElementVisible(element),
        path: trimForDiag(buildDiagElementPath(element), 260)
    };
}

function normalizeDiagPayload(value, depth = 0) {
    if (depth > 4) return '[depth-limit]';
    if (value == null) return value;
    if (typeof value === 'string') return trimForDiag(value, 600);
    if (typeof value === 'number' || typeof value === 'boolean') return value;
    if (value instanceof Element) return getDiagElementMeta(value);
    if (value instanceof Error) {
        return {
            name: String(value.name || 'Error'),
            message: trimForDiag(String(value.message || ''), 600),
            stack: trimForDiag(String(value.stack || ''), 1200)
        };
    }
    if (Array.isArray(value)) {
        return value.slice(0, 20).map((item) => normalizeDiagPayload(item, depth + 1));
    }
    if (typeof value === 'object') {
        const entries = Object.entries(value).slice(0, 30);
        const result = {};
        for (const [key, val] of entries) {
            result[key] = normalizeDiagPayload(val, depth + 1);
        }
        return result;
    }
    return trimForDiag(String(value), 600);
}

function pushStatusDiagInteraction(type, payload) {
    appendDiagBounded(STATUS_DIAG_STATE.recentInteractions, {
        ts: new Date().toISOString(),
        type: String(type || 'interaction'),
        payload: normalizeDiagPayload(payload)
    }, STATUS_DIAG_MAX_INTERACTIONS);
}

function pushStatusDiagMutation(payload) {
    appendDiagBounded(STATUS_DIAG_STATE.domMutations, {
        ts: new Date().toISOString(),
        payload: normalizeDiagPayload(payload)
    }, STATUS_DIAG_MAX_MUTATIONS);
}

function pushStatusDiagNetwork(payload) {
    appendDiagBounded(STATUS_DIAG_STATE.networkLog, {
        ts: new Date().toISOString(),
        payload: normalizeDiagPayload(payload)
    }, STATUS_DIAG_MAX_NETWORK);
}

function collectUniversalStatusFieldSnapshot(source = 'snapshot') {
    const streetField = document.querySelector('input[name="Customer[address_street]"], textarea[name="Customer[address_street]"], #customer-address_street, input[name="Customer[street]"], textarea[name="Customer[street]"]');
    const localityField = document.querySelector('input[name="Customer[address_locality]"], textarea[name="Customer[address_locality]"], #customer-address_locality, input[name="Customer[address_settlement]"], textarea[name="Customer[address_settlement]"], #customer-address_settlement');
    const houseField = document.querySelector('input[name="Customer[address_building]"], textarea[name="Customer[address_building]"], #customer-address_building, input[name="Customer[address_house]"], textarea[name="Customer[address_house]"], #customer-address_house');
    const officeField = document.querySelector('input[name="Customer[address_office]"], textarea[name="Customer[address_office]"], #customer-address_office');
    const autoMenus = Array.from(document.querySelectorAll('ul.ui-autocomplete, ul.ui-menu.ui-autocomplete, #ui-id-1')).slice(0, 4).map((menu) => ({
        id: String(menu.id || ''),
        className: trimForDiag(String(menu.className || ''), 220),
        visible: isDiagElementVisible(menu),
        display: window.getComputedStyle(menu)?.display || '',
        top: Math.round(menu.getBoundingClientRect().top || 0),
        left: Math.round(menu.getBoundingClientRect().left || 0),
        width: Math.round(menu.getBoundingClientRect().width || 0),
        height: Math.round(menu.getBoundingClientRect().height || 0),
        textPreview: trimForDiag(String(menu.textContent || '').replace(/\s+/g, ' '), 260)
    }));

    return {
        source,
        href: window.location.href,
        title: trimForDiag(document.title, 220),
        visibilityState: document.visibilityState,
        activeElement: getDiagElementMeta(document.activeElement),
        requestId: trimForDiag(String(getRequestId() || ''), 120),
        city: trimForDiag(String(getCity() || ''), 120),
        statusText: trimForDiag(String(document.querySelector('.crm-status-badge .badge-text')?.textContent || document.querySelector('.crm-status-badge')?.textContent || '').replace(/\s+/g, ' ').trim(), 220),
        fields: {
            locality: getDiagElementMeta(localityField),
            street: getDiagElementMeta(streetField),
            house: getDiagElementMeta(houseField),
            office: getDiagElementMeta(officeField)
        },
        autocompleteMenus: autoMenus
    };
}

function saveUniversalStatusSnapshot(source = 'runtime') {
    const snapshot = {
        ts: new Date().toISOString(),
        data: collectUniversalStatusFieldSnapshot(source)
    };
    appendDiagBounded(STATUS_DIAG_STATE.snapshots, snapshot, STATUS_DIAG_MAX_SNAPSHOTS);
}

function pushStatusDiagEvent(type, payload) {
    return;
    const normalizedType = String(type || 'event');
    const event = {
        ts: new Date().toISOString(),
        type: normalizedType,
        payload: normalizeDiagPayload(payload)
    };
    STATUS_DIAG_STATE.eventCounters[normalizedType] = Number(STATUS_DIAG_STATE.eventCounters[normalizedType] || 0) + 1;
    appendDiagBounded(STATUS_DIAG_STATE.recentEvents, event, STATUS_DIAG_MAX_EVENTS);
}

function pushStatusDiagError(source, error) {
    return;
    const errorText = String(error && error.message ? error.message : error || 'unknown');
    const stackText = trimForDiag(error && error.stack ? error.stack : '', 3000);
    const entry = {
        ts: new Date().toISOString(),
        source: String(source || 'runtime'),
        message: errorText,
        stack: stackText
    };
    appendDiagBounded(STATUS_DIAG_STATE.lastErrors, entry, STATUS_DIAG_MAX_ERRORS);
    STATUS_DIAG_STATE.eventCounters.error = Number(STATUS_DIAG_STATE.eventCounters.error || 0) + 1;
}

function ensureStatusDiagRuntimeHooks() {
    return;
    if (STATUS_DIAG_STATE.runtimeHooksInstalled) {
        return;
    }
    STATUS_DIAG_STATE.runtimeHooksInstalled = true;
    STATUS_DIAG_STATE.startedAt = STATUS_DIAG_STATE.startedAt || new Date().toISOString();
    pushStatusDiagEvent('diag-runtime-hooks-installed', {
        href: window.location.href,
        title: trimForDiag(document.title, 200)
    });
    saveUniversalStatusSnapshot('hooks-installed');

    window.addEventListener('error', (event) => {
        pushStatusDiagError('window.error', event && event.error ? event.error : event && event.message);
        pushStatusDiagEvent('window-error', {
            message: String(event?.message || ''),
            filename: String(event?.filename || ''),
            lineno: Number(event?.lineno || 0),
            colno: Number(event?.colno || 0)
        });
    });

    window.addEventListener('unhandledrejection', (event) => {
        pushStatusDiagError('window.unhandledrejection', event ? event.reason : 'unknown rejection');
        pushStatusDiagEvent('window-unhandledrejection', {
            reason: normalizeDiagPayload(event ? event.reason : 'unknown rejection')
        });
    });

    const trackedDomEvents = ['click', 'mousedown', 'mouseup', 'keydown', 'focusin', 'focusout', 'input', 'change', 'paste', 'submit'];
    const lastInputTsByPath = new Map();
    const shouldSkipDomEvent = (eventName, event, targetPath) => {
        const now = Date.now();
        if (eventName === 'keydown') {
            const key = String(event?.key || '');
            const keepKey = key === 'Enter' || key === 'Escape' || key === 'Tab';
            const keepCombo = Boolean(event?.ctrlKey || event?.altKey || event?.metaKey);
            return !keepKey && !keepCombo;
        }
        if (eventName === 'input') {
            const lastTs = Number(lastInputTsByPath.get(targetPath) || 0);
            if ((now - lastTs) < 120) {
                return true;
            }
            lastInputTsByPath.set(targetPath, now);
        }
        return false;
    };

    const domEventHandler = (event) => {
        try {
            const eventName = String(event?.type || '');
            const target = event?.target instanceof Element ? event.target : null;
            const targetMeta = getDiagElementMeta(target);
            const targetPath = targetMeta?.path || '';
            if (shouldSkipDomEvent(eventName, event, targetPath)) {
                return;
            }
            pushStatusDiagInteraction(`dom-${eventName}`, {
                isTrusted: Boolean(event?.isTrusted),
                defaultPrevented: Boolean(event?.defaultPrevented),
                key: trimForDiag(String(event?.key || ''), 20),
                code: trimForDiag(String(event?.code || ''), 30),
                ctrlKey: Boolean(event?.ctrlKey),
                altKey: Boolean(event?.altKey),
                shiftKey: Boolean(event?.shiftKey),
                metaKey: Boolean(event?.metaKey),
                button: Number(event?.button ?? -1),
                target: targetMeta,
                activeElement: getDiagElementMeta(document.activeElement)
            });

            if (eventName === 'focusout' || eventName === 'change' || eventName === 'submit') {
                saveUniversalStatusSnapshot(`dom-${eventName}`);
            }
        } catch (error) {
            pushStatusDiagError('status-diag.dom-event-handler', error);
        }
    };

    trackedDomEvents.forEach((eventName) => {
        document.addEventListener(eventName, domEventHandler, true);
    });

    window.addEventListener('hashchange', () => {
        pushStatusDiagEvent('window-hashchange', { href: window.location.href });
        saveUniversalStatusSnapshot('hashchange');
    });
    window.addEventListener('popstate', () => {
        pushStatusDiagEvent('window-popstate', { href: window.location.href });
        saveUniversalStatusSnapshot('popstate');
    });
    document.addEventListener('visibilitychange', () => {
        pushStatusDiagEvent('document-visibilitychange', { visibilityState: document.visibilityState });
        saveUniversalStatusSnapshot('visibilitychange');
    });

    if (!window.__statusDiagFetchWrapped && typeof window.fetch === 'function') {
        window.__statusDiagFetchWrapped = true;
        const originalFetch = window.fetch.bind(window);
        window.fetch = function(...args) {
            const startedAt = Date.now();
            const input = args[0];
            const init = args[1] || {};
            const url = typeof input === 'string' ? input : String(input?.url || '');
            const method = String(init?.method || input?.method || 'GET').toUpperCase();
            pushStatusDiagNetwork({
                phase: 'fetch-start',
                method,
                url: trimForDiag(url, 700)
            });

            return originalFetch(...args).then((response) => {
                pushStatusDiagNetwork({
                    phase: 'fetch-success',
                    method,
                    url: trimForDiag(url, 700),
                    status: Number(response?.status || 0),
                    ok: Boolean(response?.ok),
                    durationMs: Date.now() - startedAt
                });
                return response;
            }).catch((error) => {
                pushStatusDiagNetwork({
                    phase: 'fetch-error',
                    method,
                    url: trimForDiag(url, 700),
                    durationMs: Date.now() - startedAt,
                    error: String(error && error.message ? error.message : error)
                });
                pushStatusDiagError('status-diag.fetch', error);
                throw error;
            });
        };
    }

    if (!window.__statusDiagXhrWrapped && window.XMLHttpRequest) {
        window.__statusDiagXhrWrapped = true;
        const originalOpen = window.XMLHttpRequest.prototype.open;
        const originalSend = window.XMLHttpRequest.prototype.send;

        window.XMLHttpRequest.prototype.open = function(method, url, ...rest) {
            this.__statusDiagMeta = {
                method: String(method || 'GET').toUpperCase(),
                url: trimForDiag(String(url || ''), 700),
                startedAt: 0
            };
            return originalOpen.call(this, method, url, ...rest);
        };

        window.XMLHttpRequest.prototype.send = function(...args) {
            const meta = this.__statusDiagMeta || {
                method: 'GET',
                url: '',
                startedAt: 0
            };
            meta.startedAt = Date.now();
            this.__statusDiagMeta = meta;
            pushStatusDiagNetwork({
                phase: 'xhr-start',
                method: meta.method,
                url: meta.url
            });

            this.addEventListener('loadend', () => {
                pushStatusDiagNetwork({
                    phase: 'xhr-end',
                    method: meta.method,
                    url: meta.url,
                    status: Number(this.status || 0),
                    durationMs: Date.now() - Number(meta.startedAt || Date.now())
                });
            }, { once: true });

            return originalSend.call(this, ...args);
        };
    }

    if (!window.__statusDiagConsoleWrapped) {
        window.__statusDiagConsoleWrapped = true;
        const originalWarn = console.warn ? console.warn.bind(console) : null;
        const originalError = console.error ? console.error.bind(console) : null;

        if (originalWarn) {
            console.warn = function(...args) {
                pushStatusDiagEvent('console-warn', {
                    args: args.map((arg) => normalizeDiagPayload(arg))
                });
                return originalWarn(...args);
            };
        }

        if (originalError) {
            console.error = function(...args) {
                pushStatusDiagEvent('console-error', {
                    args: args.map((arg) => normalizeDiagPayload(arg))
                });
                return originalError(...args);
            };
        }
    }

    if (!window.__statusDiagMutationObserverInstalled && window.MutationObserver) {
        window.__statusDiagMutationObserverInstalled = true;
        let mutationAdded = 0;
        let mutationRemoved = 0;
        let mutationAttr = 0;
        let autocompleteTouched = false;
        let flushTimer = 0;
        const flushMutationBatch = () => {
            flushTimer = 0;
            if (!mutationAdded && !mutationRemoved && !mutationAttr) return;
            pushStatusDiagMutation({
                addedNodes: mutationAdded,
                removedNodes: mutationRemoved,
                attributesChanged: mutationAttr,
                autocompleteTouched
            });
            mutationAdded = 0;
            mutationRemoved = 0;
            mutationAttr = 0;
            autocompleteTouched = false;
        };

        const observer = new MutationObserver((mutations) => {
            for (const mutation of mutations) {
                if (mutation.type === 'childList') {
                    mutationAdded += Number(mutation.addedNodes?.length || 0);
                    mutationRemoved += Number(mutation.removedNodes?.length || 0);
                    const nodes = [
                        ...Array.from(mutation.addedNodes || []),
                        ...Array.from(mutation.removedNodes || [])
                    ];
                    if (nodes.some((node) => node instanceof Element && (node.matches('ul.ui-autocomplete, ul.ui-menu.ui-autocomplete, #ui-id-1') || node.querySelector?.('ul.ui-autocomplete, ul.ui-menu.ui-autocomplete, #ui-id-1')))) {
                        autocompleteTouched = true;
                    }
                } else if (mutation.type === 'attributes') {
                    mutationAttr += 1;
                    if (mutation.target instanceof Element && mutation.target.matches('ul.ui-autocomplete, ul.ui-menu.ui-autocomplete, #ui-id-1')) {
                        autocompleteTouched = true;
                    }
                }
            }
            if (!flushTimer) {
                flushTimer = setTimeout(flushMutationBatch, 180);
            }
        });

        observer.observe(document.documentElement || document.body, {
            subtree: true,
            childList: true,
            attributes: true,
            attributeFilter: ['class', 'style', 'hidden', 'aria-expanded']
        });
    }

    if (!window.__statusDiagPeriodicSnapshotTimer) {
        window.__statusDiagPeriodicSnapshotTimer = setInterval(() => {
            saveUniversalStatusSnapshot('interval');
        }, 5000);
    }
}

function readPendingStatusBadgeAutoClick() {
    try {
        const raw = sessionStorage.getItem(STATUS_BADGE_AUTO_CLICK_KEY);
        if (!raw) return null;
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return null;
        return parsed;
    } catch (error) {
        return null;
    }
}

function clearPendingStatusBadgeAutoClick() {
    try {
        sessionStorage.removeItem(STATUS_BADGE_AUTO_CLICK_KEY);
    } catch (error) {}
}

function tryRunPendingStatusBadgeAutoClick(attempt = 0) {
    const pending = readPendingStatusBadgeAutoClick();
    if (!pending) {
        return;
    }

    const pendingRequestId = String(pending.requestId || '').trim();
    const currentRequestId = String(getRequestId() || '').trim();
    if (pendingRequestId && currentRequestId && pendingRequestId !== currentRequestId) {
        clearPendingStatusBadgeAutoClick();
        return;
    }

    const createdAt = Number(pending.createdAt || 0);
    if (!createdAt || (Date.now() - createdAt) > 2 * 60 * 1000) {
        clearPendingStatusBadgeAutoClick();
        return;
    }

    const expectedStatuses = Array.isArray(pending.expectedStatuses)
        ? pending.expectedStatuses.map((status) => String(status || '').trim().toLowerCase()).filter(Boolean)
        : [];

    const badge = document.querySelector('.crm-status-badge');
    const badgeText = String(badge?.querySelector('.badge-text')?.textContent || badge?.textContent || '').trim().toLowerCase();
    const statusMatched = expectedStatuses.length
        ? expectedStatuses.some((status) => badgeText.includes(status))
        : true;
    const hasClickHandler = Boolean(badge && badge.hasCopyHandler === true);

    if (!badge || !statusMatched || !hasClickHandler) {
        if (attempt < 120) {
            setTimeout(() => tryRunPendingStatusBadgeAutoClick(attempt + 1), 300);
        } else {
            clearPendingStatusBadgeAutoClick();
        }
        return;
    }

    pushStatusDiagEvent('pending-status-autoclick-run', {
        requestId: currentRequestId,
        badgeText: trimForDiag(badgeText, 200),
        attempt
    });

    try {
        badge.click();
    } catch (error) {
        pushStatusDiagError('tryRunPendingStatusBadgeAutoClick.click', error);
    } finally {
        clearPendingStatusBadgeAutoClick();
    }
}

function sendToAHK(city, message) {
    ensureStatusDiagRuntimeHooks();
    city = mapAhkSearchCity(city);
    message = (message || "").trim();
    if (!city || !message) {
        pushStatusDiagEvent('send-skipped-empty', {
            city: city || '',
            hasMessage: !!message
        });
        return Promise.resolve({ ok: false, skipped: true });
    }

    const now = Date.now();
    const key = city + "|" + message;

    // защита от двойного/тройного срабатывания одного и того же клика
    if (__ahkSendGuard.lastKey === key && (now - __ahkSendGuard.lastTs) < 450) {
        STATUS_DIAG_STATE.lastSendCall = {
            ts: new Date().toISOString(),
            skippedDuplicate: true,
            city,
            message: trimForDiag(message),
            messageLength: message.length
        };
        pushStatusDiagEvent('send-skipped-duplicate', {
            city,
            message: trimForDiag(message, 500),
            messageLength: message.length
        });
        console.log("?? AHK skip duplicate click:", key);
        return Promise.resolve({ ok: true, skippedDuplicate: true });
    }

    __ahkSendGuard.lastKey = key;
    __ahkSendGuard.lastTs = now;

    STATUS_DIAG_STATE.lastSendCall = {
        ts: new Date().toISOString(),
        skippedDuplicate: false,
        city,
        message: trimForDiag(message),
        messageLength: message.length,
        source: 'status_click'
    };
    pushStatusDiagEvent('send-start', {
        city,
        message: trimForDiag(message, 500),
        messageLength: message.length
    });

    console.log("?? Отправляем в AHK:", city, "->", message);
    const sendPromise = AHKBridge.send(city, message, { source: "status_click" });
    sendPromise.then((result) => {
        STATUS_DIAG_STATE.lastSendResult = {
            ts: new Date().toISOString(),
            ok: !!(result && result.ok),
            status: result && result.status,
            skipped: !!(result && result.skipped),
            skippedDuplicate: !!(result && result.skippedDuplicate),
            detail: safeStringifyForDiag(result, 3000)
        };
        pushStatusDiagEvent('send-result', STATUS_DIAG_STATE.lastSendResult);
    }).catch((error) => {
        STATUS_DIAG_STATE.lastSendResult = {
            ts: new Date().toISOString(),
            ok: false,
            error: String(error && error.message ? error.message : error)
        };
        pushStatusDiagEvent('send-error', STATUS_DIAG_STATE.lastSendResult);
        pushStatusDiagError('sendToAHK', error);
    });
    return sendPromise;
}

// Функция копирования в буфер
function copyToClipboard(text) {
    ensureStatusDiagRuntimeHooks();
    if (!text) {
        return Promise.resolve(false);
    }

    STATUS_DIAG_STATE.lastClipboard = {
        ts: new Date().toISOString(),
        text: trimForDiag(text),
        textLength: String(text).length
    };
    pushStatusDiagEvent('clipboard-copy-attempt', {
        textLength: STATUS_DIAG_STATE.lastClipboard.textLength
    });

    return copyTextSafely(text).then((copied) => {
        if (copied) {
            console.log('?? Скопировано в буфер:', text);
            pushStatusDiagEvent('clipboard-copy-success', {
                textLength: String(text).length,
                mode: 'primary'
            });
            return true;
        }
        return fallbackCopy(text);
    }).catch(err => {
        console.error('Ошибка копирования:', err);
        pushStatusDiagEvent('clipboard-copy-error', {
            mode: 'primary',
            error: String(err && err.message ? err.message : err)
        });
        pushStatusDiagError('copyToClipboard.primary', err);
        return fallbackCopy(text);
    });
}

function fallbackCopy(text) {
    return copyTextSafely(text).then((copied) => {
        if (copied) {
            console.log('?? Скопировано в буфер (fallback):', text);
            pushStatusDiagEvent('clipboard-copy-success', {
                textLength: String(text).length,
                mode: 'fallback'
            });
        } else {
            pushStatusDiagEvent('clipboard-copy-failed', {
                textLength: String(text).length,
                mode: 'fallback'
            });
        }
        return copied;
    }).catch((error) => {
        pushStatusDiagEvent('clipboard-copy-error', {
            mode: 'fallback',
            error: String(error && error.message ? error.message : error)
        });
        pushStatusDiagError('copyToClipboard.fallback', error);
        return false;
    });
}

function buildUniversalDiagnosticDump() {
    ensureStatusDiagRuntimeHooks();
    saveUniversalStatusSnapshot('dump-build');
    const badgeList = Array.from(document.querySelectorAll('.crm-status-badge')).map((badge, index) => {
        const badgeText = (badge.querySelector('.badge-text')?.textContent || badge.textContent || '').replace(/\s+/g, ' ').trim();
        const classText = Array.from(badge.classList || []).join(' ');
        return `${index + 1}. text="${trimForDiag(badgeText, 350)}" | class="${trimForDiag(classText, 350)}" | hasCopyHandler=${badge.hasCopyHandler ? 'yes' : 'no'}`;
    });

    const rawNow = copyRequestData();
    const normalizedNow = normalizeWhiteRequestAlertText(rawNow);
    const scriptVersion = typeof GM_info !== 'undefined' && GM_info && GM_info.script ? String(GM_info.script.version || 'unknown') : 'unknown';
    const currentStatusText = (document.querySelector('.crm-status-badge .badge-text')?.textContent || document.querySelector('.crm-status-badge')?.textContent || '').replace(/\s+/g, ' ').trim();
    const navEntry = performance.getEntriesByType && performance.getEntriesByType('navigation') ? performance.getEntriesByType('navigation')[0] : null;
    const fieldSnapshotNow = collectUniversalStatusFieldSnapshot('dump-inline');

    return [
        '=== UNIVERSAL STATUS DEBUG DUMP ===',
        `time=${new Date().toISOString()}`,
        `scriptVersion=${scriptVersion}`,
        `diagVersion=${STATUS_DIAG_STATE.version}`,
        `url=${window.location.href}`,
        `title=${trimForDiag(document.title, 300)}`,
        `userAgent=${trimForDiag(navigator.userAgent, 500)}`,
        `requestId=${getRequestId()}`,
        `city=${getCity() || 'EMPTY'}`,
        `statusText=${currentStatusText || 'EMPTY'}`,
        `badgeCount=${badgeList.length}`,
        `diagStartedAt=${STATUS_DIAG_STATE.startedAt || ''}`,
        `runtimeHooksInstalled=${STATUS_DIAG_STATE.runtimeHooksInstalled ? 'true' : 'false'}`,
        `documentReadyState=${document.readyState}`,
        `documentVisibility=${document.visibilityState}`,
        `referrer=${trimForDiag(document.referrer || '', 500) || 'EMPTY'}`,
        `navigationType=${String(navEntry?.type || '')}`,
        `navigationDurationMs=${Number(navEntry?.duration || 0).toFixed(2)}`,
        `performanceNowMs=${Math.round(performance.now ? performance.now() : 0)}`,
        `jsHeapUsedBytes=${Number(performance?.memory?.usedJSHeapSize || 0)}`,
        `jsHeapTotalBytes=${Number(performance?.memory?.totalJSHeapSize || 0)}`,
        `timezone=${Intl.DateTimeFormat().resolvedOptions().timeZone || 'unknown'}`,
        'badges:',
        badgeList.length ? badgeList.join('\n') : 'NONE',
        'generated.raw:',
        trimForDiag(rawNow, 6000) || 'EMPTY',
        'generated.normalized:',
        trimForDiag(normalizedNow, 6000) || 'EMPTY',
        `rawEqualsNormalized=${rawNow === normalizedNow}`,
        `rawHasWhiteMarker=${/БЕЛАЯ\s+ЗАЯВКА/i.test(rawNow)}`,
        `normalizedHasWhiteMarker=${/БЕЛАЯ\s+ЗАЯВКА/i.test(normalizedNow)}`,
        'live.fieldSnapshot:',
        safeStringifyForDiag(fieldSnapshotNow, 9000),
        'state.lastNaUtochnenii:',
        safeStringifyForDiag(STATUS_DIAG_STATE.lastNaUtochnenii, 6000),
        'state.lastSendCall:',
        safeStringifyForDiag(STATUS_DIAG_STATE.lastSendCall, 4000),
        'state.lastSendResult:',
        safeStringifyForDiag(STATUS_DIAG_STATE.lastSendResult, 4000),
        'state.lastClipboard:',
        safeStringifyForDiag(STATUS_DIAG_STATE.lastClipboard, 4000),
        'state.eventCounters:',
        safeStringifyForDiag(STATUS_DIAG_STATE.eventCounters, 5000),
        'state.lastErrors:',
        safeStringifyForDiag(STATUS_DIAG_STATE.lastErrors, 12000),
        'state.recentEvents:',
        safeStringifyForDiag(STATUS_DIAG_STATE.recentEvents, 20000),
        'state.recentInteractions:',
        safeStringifyForDiag(STATUS_DIAG_STATE.recentInteractions, 20000),
        'state.networkLog:',
        safeStringifyForDiag(STATUS_DIAG_STATE.networkLog, 18000),
        'state.domMutations:',
        safeStringifyForDiag(STATUS_DIAG_STATE.domMutations, 14000),
        'state.snapshots:',
        safeStringifyForDiag(STATUS_DIAG_STATE.snapshots, 24000)
    ].join('\n');
}

function ensureNaUtochneniiDiagnosticButton() {
    const existingButton = document.getElementById(STATUS_DIAG_BUTTON_ID);
    if (existingButton) existingButton.remove();
    return;
    if (!isDebugReportUnlocked()) {
        if (existingButton) existingButton.remove();
        return;
    }
    if (existingButton) return;

    const button = document.createElement('button');
    button.id = STATUS_DIAG_BUTTON_ID;
    button.type = 'button';
    button.textContent = 'DEBUG ОТЧЕТ';
    button.title = 'Скопировать универсальную диагностику скрипта';
    button.addEventListener('click', (event) => {
        event.preventDefault();
        event.stopPropagation();
        const dump = buildUniversalDiagnosticDump();
        pushStatusDiagEvent('debug-button-click', {
            dumpLength: dump.length,
            url: window.location.href
        });
        const initialText = button.textContent;
        button.textContent = 'КОПИРУЮ...';
        void copyToClipboard(dump).then((copied) => {
            button.textContent = copied ? 'ОТЧЕТ СКОПИРОВАН' : 'НЕ СКОПИРОВАЛОСЬ';
            setTimeout(() => {
                button.textContent = initialText;
            }, 1600);
            if (copied) {
                console.log('?? Универсальная диагностика скопирована в буфер');
                alert('Универсальная диагностика скопирована. Отправьте весь текст из буфера.');
            } else {
                alert('Не удалось скопировать универсальную диагностику. Попробуйте снова.');
            }
        });
    });

    document.body.appendChild(button);
}

function normalizeWhiteRequestAlertText(text) {
        let normalizedText = String(text || '')
            .replace(/[\u200B-\u200D\uFEFF]/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();
        if (!normalizedText) {
            return '';
        }

        normalizedText = normalizedText.replace(/^[\s\u200B-\u200D\uFEFF]*/u, '');
        normalizedText = normalizedText.replace(/^(?:🛑\s*)+/u, '');

        // Normalize any white-request marker to a single canonical form.
        normalizedText = normalizedText.replace(
            /(?:🛑\s*)*БЕЛАЯ\s+ЗАЯВКА(?:\s*🛑)*/giu,
            '🛑БЕЛАЯ ЗАЯВКА 🛑'
        );

        // Keep partner-comment wording stable after white-request normalization.
        normalizedText = normalizedText.replace(
            /Комментарий\s*о\s*партнере\s*:\s*🛑\s*БЕЛАЯ\s+ЗАЯВКА\s*🛑/giu,
            'Комментарий о партнере: 🛑БЕЛАЯ ЗАЯВКА 🛑'
        );

        normalizedText = normalizedText.replace(/🛑\s*🛑/gu, '🛑 ');
        normalizedText = normalizedText.replace(/^[\s\u200B-\u200D\uFEFF]*/u, '');
        normalizedText = normalizedText.replace(/^(?:🛑\s*)+/u, '');

        return normalizedText.replace(/\s+/g, ' ').trim();
    }

    function normalizeRequestCommentText(text) {
        let normalizedText = String(text || '').replace(/\s+/g, ' ').trim();
        if (!normalizedText) {
            return '';
        }

        return normalizeWhiteRequestAlertText(normalizedText);
    }

    function removeLinksFromNaUtochneniiRequestText(text) {
        const cleaned = normalizeWhiteRequestAlertText(
            String(text || '')
                .replace(/(?:https?:\/\/|www\.)[^\s,;]+/giu, '')
                .replace(/\b(?:t\.me|telegram\.me|vk\.com|wa\.me|api\.whatsapp\.com|yandex\.ru|maps\.yandex\.ru|2gis\.ru)\/[^\s,;]+/giu, '')
                .replace(/\s+([,.;!?])/g, '$1')
                .replace(/([,;])\s*([,;])/g, '$1')
                .replace(/\s{2,}/g, ' ')
                .replace(/\s+,/g, ',')
                .replace(/^[\s,;:]+/g, '')
                .replace(/[\s,;:]+$/g, '')
                .trim()
        );
        // Эмодзи убираем ПОСЛЕ normalizeWhiteRequestAlertText: она сама ВСТАВЛЯЕТ 🛑 вокруг
        // «БЕЛАЯ ЗАЯВКА», поэтому чистка до неё бесполезна. Режем пиктограммы/символы/модификаторы/
        // VS-16/ZWJ/keycap, затем схлопываем пробелы и убираем висящие пробелы у знаков.
        return cleaned
            .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{FE0E}\u{FE0F}\u{200D}\u{20E3}]/gu, '')
            .replace(/\s+([,.;!?])/g, '$1')
            .replace(/\s{2,}/g, ' ')
            .trim();
    }

    // Функция копирования заявки (для статуса "На уточнении" и "Модерация")
    function copyRequestData() {
        try {
            // Собираем данные заявки
            const city = findCity();
            const settlement = findSettlement();
            const street = findStreet();
            const house = findHouse();
            const sourceType = findSourceType();
            const customerGenderAge = getCustomerGenderAgeText();

            // Получаем комментарии
            const mainComment = normalizeRequestCommentText(findMainComment());
            const partnerComment = normalizeRequestCommentText(findPartnerComment());

            console.log('📋 mainComment =', mainComment || 'ПУСТО');
            console.log('📋 partnerComment =', partnerComment || 'ПУСТО');

            // Формируем адрес
            const addressText = formatAddress(city, settlement, street, house);
            console.log('📋 Адрес:', addressText);

            // Определяем комментарий.
            // Если в обычном комментарии ТОЛЬКО ссылка (частый случай на модерации) — мастеру в
            // чате города она бесполезна, берём текст из комментария партнёра. Ссылка + осмысленный
            // текст рядом = обычный шлём как есть. Партнёрский пустой → падаем обратно на обычный.
            let finalComment = '';
            if (mainComment && !isOnlyLinkText(mainComment)) {
                finalComment = mainComment;
            } else if (isOnlyLinkText(mainComment) && partnerComment) {
                finalComment = partnerComment;
                console.log('📋 обычный = только ссылка → берём комментарий партнёра');
            } else if (mainComment) {
                finalComment = mainComment;
            } else if (partnerComment) {
                finalComment = partnerComment;
            } else {
                finalComment = 'Комментарий отсутствует';
            }

            // Формируем результат
            let result;
            if (addressText) {
                if (sourceType) {
                    if (customerGenderAge) {
                        result = `${addressText} , ${sourceType}, ${customerGenderAge}, ${finalComment}  Берем?, От сĸольĸи?, На когда?`;
                    } else {
                        result = `${addressText} , ${sourceType}, ${finalComment}  Берем?, От сĸольĸи?, На когда?`;
                    }
                } else if (customerGenderAge) {
                    result = `${addressText} , ${customerGenderAge}, ${finalComment}  Берем?, От сĸольĸи?, На когда?`;
                } else {
                    result = `${addressText} , ${finalComment}  Берем?, От сĸольĸи?, На когда?`;
                }
            } else {
                if (sourceType) {
                    if (customerGenderAge) {
                        result = `${sourceType}, ${customerGenderAge}, ${finalComment}  Берем?, От сĸольĸи?, На когда?`;
                    } else {
                        result = `${sourceType}, ${finalComment}  Берем?, От сĸольĸи?, На когда?`;
                    }
                } else if (customerGenderAge) {
                    result = `${customerGenderAge}, ${finalComment}  Берем?, От сĸольĸи?, На когда?`;
                } else {
                    result = `${finalComment}  Берем?, От сĸольĸи?, На когда?`;
                }
            }

            result = result.replace(/\s+/g, ' ');
            result = result.replace(/  Берем\?/g, '  Берем?');
            result = normalizeWhiteRequestAlertText(result);

            console.log('📋 Скопировано:', result);
            return result;
        } catch (error) {
            console.error('❌ Ошибка копирования заявки:', error);
            return '';
        }
    }

    // Вспомогательные функции для поиска данных
    function findCity() {
        const inputs = document.querySelectorAll('input, select');
        for (const input of inputs) {
            const name = (input.name || '').toLowerCase();
            const id = (input.id || '').toLowerCase();
            const placeholder = (input.placeholder || '').toLowerCase();
            if (name.includes('город') || name.includes('city') || id.includes('город') || id.includes('city') || placeholder.includes('город') || placeholder.includes('city')) {
                const value = ScriptManager.utils.getInputValue(input);
                if (value) return value;
            }
        }
        return '';
    }

    function getCityForRequest(city) {
        if (!city) return '';
        let cleaned = city;
        cleaned = cleaned.trim();
        cleaned = cleaned.replace(/\s*-\s*/g, '-');
        return cleaned;
    }

    function findSettlement() {
        const v11Locality = document.getElementById('addrLocality');
        const v11LocalityValue = ScriptManager.utils.getInputValue(v11Locality);
        if (v11LocalityValue) return v11LocalityValue;

        const labels = document.querySelectorAll('label');
        for (const label of labels) {
            const text = label.textContent.trim();
            if (text === 'Населенный пункт' || text === 'Населенный пункт:') {
                const value = ScriptManager.utils.findValueNearLabel(label);
                if (value && value !== '' && value !== 'Улица' && value !== 'Дом') return value;
            }
        }
        const inputs = document.querySelectorAll('input, select');
        for (const input of inputs) {
            const name = (input.name || '').toLowerCase();
            const id = (input.id || '').toLowerCase();
            const placeholder = (input.placeholder || '').toLowerCase();
            if (name.includes('поселение') || name.includes('населен') || id.includes('поселение') || id.includes('населен') || placeholder.includes('поселение') || placeholder.includes('населен') || name.includes('settlement') || id.includes('settlement')) {
                const value = ScriptManager.utils.getInputValue(input);
                if (value) return value;
            }
        }
        return '';
    }

    function findStreet() {
        const v11Street = document.getElementById('addrStreet');
        const v11StreetValue = ScriptManager.utils.getInputValue(v11Street);
        if (v11StreetValue) return v11StreetValue;

        const inputs = document.querySelectorAll('input, select');
        for (const input of inputs) {
            const name = (input.name || '').toLowerCase();
            const id = (input.id || '').toLowerCase();
            const placeholder = (input.placeholder || '').toLowerCase();
            if (name.includes('улиц') || name.includes('ул.') || id.includes('улиц') || id.includes('ул.') || placeholder.includes('улиц') || placeholder.includes('ул.')) {
                const value = ScriptManager.utils.getInputValue(input);
                if (value) return value;
            }
        }
        return '';
    }

    function findHouse() {
        const v11House = document.getElementById('addrHouse');
        const v11HouseValue = ScriptManager.utils.getInputValue(v11House);
        if (v11HouseValue) return v11HouseValue;

        const inputs = document.querySelectorAll('input, select');
        for (const input of inputs) {
            const name = (input.name || '').toLowerCase();
            const id = (input.id || '').toLowerCase();
            const placeholder = (input.placeholder || '').toLowerCase();
            if (name.includes('дом') || name === 'дом' || id.includes('дом') || placeholder.includes('дом')) {
                const value = ScriptManager.utils.getInputValue(input);
                if (value) return value;
            }
        }
        const labels = document.querySelectorAll('label');
        for (const label of labels) {
            const text = label.textContent.trim();
            if (text === 'Дом' || text === 'Дом:' || text === 'Номер дома' || text === 'Номер дома:') {
                if (label.htmlFor) {
                    const input = document.getElementById(label.htmlFor);
                    if (input) {
                        const value = ScriptManager.utils.getInputValue(input);
                        if (value) return value;
                    }
                }
                let current = label;
                for (let i = 0; i < 3; i++) {
                    current = current.nextElementSibling;
                    if (!current) break;
                    if (current.tagName === 'INPUT' || current.tagName === 'SELECT') {
                        const value = ScriptManager.utils.getInputValue(current);
                        if (value) return value;
                    }
                }
            }
        }
        return '';
    }

    function findSourceType() {
        const labels = document.querySelectorAll('label');
        let campaignValue = '', partnerValue = '';
        for (const label of labels) {
            const text = label.textContent.trim();
            if (text === 'Рекламная кампания' || text === 'Рекламная кампания:') {
                campaignValue = ScriptManager.utils.findValueNearLabel(label);
                break;
            }
        }
        for (const label of labels) {
            const text = label.textContent.trim();
            if (text === 'Партнер' || text === 'Партнер:') {
                partnerValue = ScriptManager.utils.findValueNearLabel(label);
                break;
            }
        }
        if (campaignValue && campaignValue !== '' && campaignValue !== 'Выберите' && campaignValue !== 'Выберите...' && campaignValue.toLowerCase() !== 'выберите') {
            return 'листовка';
        }
        if (partnerValue && partnerValue !== '' && partnerValue !== 'Без партнера' && partnerValue !== 'Выберите' && partnerValue.toLowerCase() !== 'без партнера' && /\d/.test(partnerValue)) {
            return 'партнер';
        }
        return null;
    }

    function findCustomerFirstName() {
        const byId = document.getElementById('customer-first_name');
        if (byId) {
            const value = ScriptManager.utils.getInputValue(byId);
            if (value) return String(value).trim();
        }

        const byName = document.querySelector('input[name="Customer[first_name]"]');
        if (byName) {
            const value = ScriptManager.utils.getInputValue(byName);
            if (value) return String(value).trim();
        }

        return '';
    }

    function findCustomerAge() {
        const byId = document.getElementById('customer-age');
        let value = '';

        if (byId) {
            value = ScriptManager.utils.getInputValue(byId) || '';
        }

        if (!value) {
            const byName = document.querySelector('input[name="Customer[age]"]');
            if (byName) {
                value = ScriptManager.utils.getInputValue(byName) || '';
            }
        }

        const digits = String(value || '').replace(/\D+/g, '');
        if (!digits) return '';

        const ageNum = parseInt(digits, 10);
        if (!Number.isFinite(ageNum) || ageNum < 1 || ageNum > 120) {
            return '';
        }

        return `${ageNum} лет`;
    }

    function inferGenderByFirstName(rawFirstName) {
        const source = String(rawFirstName || '').trim();
        if (!source) return null;

        let token = source.replace(/[\s,.;:!?]+/g, ' ').split(' ')[0] || '';
        token = token.replace(/[^a-zа-яё]/gi, '');
        if (!token) return null;

        const upper = token.toUpperCase();
        if (upper === 'М' || upper === 'M' || upper === 'МУЖ' || upper === 'МУЖЧИНА') {
            return 'Мужчина';
        }
        if (upper === 'Ж' || upper === 'ЖЕН' || upper === 'ЖЕНЩИНА') {
            return 'Женщина';
        }

        if (!/^[а-яё]+$/i.test(token)) {
            return null;
        }

        const name = token.toLowerCase();
        const femaleNames = [
            'анна', 'мария', 'елена', 'ольга', 'наталья', 'ирина', 'татьяна', 'екатерина', 'юлия', 'светлана',
            'кристина', 'алёна', 'алена', 'лидия', 'полина', 'дарья', 'валерия', 'евгения', 'вероника', 'любовь'
        ];
        const maleNames = [
            'иван', 'дмитрий', 'сергей', 'андрей', 'алексей', 'максим', 'денис', 'павел', 'владимир', 'михаил',
            'игорь', 'евгений', 'николай', 'константин', 'артем', 'артём', 'роман', 'станислав', 'виктор', 'кирилл'
        ];
        const maleEndingExceptions = ['никита', 'илья', 'кузьма', 'фома', 'лука', 'савва'];

        if (femaleNames.includes(name)) return 'Женщина';
        if (maleNames.includes(name)) return 'Мужчина';

        if (/[ая]$/i.test(name)) {
            if (maleEndingExceptions.includes(name)) {
                return 'Мужчина';
            }
            return 'Женщина';
        }

        if (/ь$/i.test(name)) {
            return null;
        }

        if (/[йнрмбвгджзклпстфхцчшщ]$/i.test(name)) {
            return 'Мужчина';
        }

        return null;
    }

    function getCustomerGenderAgeText() {
        const firstName = findCustomerFirstName();
        const gender = inferGenderByFirstName(firstName);

        if (!gender) {
            return '';
        }

        const ageText = findCustomerAge();
        return ageText ? `${gender} ${ageText}` : gender;
    }

    // Текст состоит ТОЛЬКО из ссылок (и мусора-разделителей)? Тогда для чата города он пустой:
    // мастеру ссылка (vk.cc / t.me / avito и т.п.) ничего не даёт. Вырезаем все URL и смотрим,
    // осталось ли хоть что-то буквенно-цифровое. Пустая строка НЕ считается «только ссылкой»
    // (иначе сломается ветка «нет обычного → партнёрский → Комментарий отсутствует»).
    function isOnlyLinkText(text) {
        try {
            const src = String(text == null ? '' : text).trim();
            if (!src) return false;
            const LINK_RE = /(https?:\/\/\S+|www\.\S+|\S+\.(?:ru|com|net|org|me|cc|io|by|kz|ua)(?:\/\S*)?)/gi;
            // Ссылка обязана быть: иначе мусор вроде «-» или «...» тоже считался бы «только ссылкой»
            // и уводил бы на комментарий партнёра, хотя речь шла именно про ссылки.
            if (!LINK_RE.test(src)) return false;
            LINK_RE.lastIndex = 0;              // regex с /g хранит позицию — сбрасываем перед replace
            const rest = src
                .replace(LINK_RE, ' ')
                .replace(/[\s.,;:!?()[\]{}«»"'\-—–\/\\|]+/g, ' ')
                .trim();
            return !/[a-zA-Zа-яА-ЯёЁ0-9]/.test(rest);
        } catch (_) {
            return false;
        }
    }

