    function formatAddress(city, settlement, street, house) {
        let result = '';
        const cleanedCity = getCityForRequest(city);
        if (cleanedCity) result += cleanedCity;
        if (settlement && settlement !== '' && settlement !== city && settlement !== 'Дом' && settlement !== 'Улица') {
            if (result) result += ' ';
            result += '(' + settlement + ')';
        }
        if (street) {
            if (result) result += ' ';
            result += street;
            if (house) result += ', ' + house;
        }
        return result;
    }

