    function animateCopy(badge, originalText) {
        if (isAnimating) return;

        let textContainer = badge.querySelector('.badge-text');
        if (!textContainer) return;

        isAnimating = true;

        if (animationTimeout) {
            clearTimeout(animationTimeout);
        }

        const currentWidth = badge.offsetWidth;
        badge.style.width = currentWidth + 'px';
        badge.style.whiteSpace = 'nowrap';
        textContainer.style.whiteSpace = 'nowrap';

        textContainer.classList.add('fade-out');

        setTimeout(() => {
            textContainer.textContent = 'Готово!';
            textContainer.classList.remove('fade-out');
            textContainer.classList.add('fade-in');
        }, 150);

        setTimeout(() => {
            textContainer.classList.remove('fade-in');
            textContainer.classList.add('fade-out');
        }, 500);

        animationTimeout = setTimeout(() => {
            textContainer.textContent = originalText;
            textContainer.classList.remove('fade-out');
            textContainer.classList.add('fade-in');

            setTimeout(() => {
                textContainer.classList.remove('fade-in');
                badge.style.width = '';
                badge.style.whiteSpace = '';
                textContainer.style.whiteSpace = '';
                isAnimating = false;
                animationTimeout = null;
            }, 150);
        }, 650);
    }

    function isProzvonActive() {
        const prozvonToggle = document.querySelector('input[name="CustomerRequest[is_prozvon]"], #customerrequest-is_prozvon, [class*="prozvon"] input[type="checkbox"]');

        if (prozvonToggle) {
            if (prozvonToggle.type === 'checkbox') {
                return prozvonToggle.checked;
            }
            return prozvonToggle.value === '1' || prozvonToggle.value === 'true' || prozvonToggle.value === 'on';
        }

        const labels = document.querySelectorAll('label');
        for (const label of labels) {
            if (label.textContent.toLowerCase().includes('прозвон')) {
                const input = label.querySelector('input[type="checkbox"]');
                if (input) {
                    return input.checked;
                }
                if (label.htmlFor) {
                    const input = document.getElementById(label.htmlFor);
                    if (input && input.type === 'checkbox') {
                        return input.checked;
                    }
                }
            }
        }

        return false;
    }

    function getRequestId() {
        const url = window.location.href;
        const match = url.match(/id=(\d+)/);
        return match ? match[1] : 'Неизвестно';
    }

    function extractAllPhonesFromText(text) {
        if (!text) return [];

        const phones = [];
        const phonePattern = /(?:\+7|8)[\s\-]?\(?\d{3}\)?[\s\-]?\d{3}[\s\-]?\d{2}[\s\-]?\d{2}/g;

        let match;
        while ((match = phonePattern.exec(text)) !== null) {
            phones.push(match[0]);
        }

        return phones;
    }

    function extractPhoneFromTelLink(href) {
        if (!href || !href.startsWith('tel:')) return null;

        const phoneNumber = href.replace('tel:', '').trim();
        if (phoneNumber.startsWith('+7') || phoneNumber.startsWith('8')) {
            return phoneNumber;
        }
        return phoneNumber;
    }

    function findAllPhones() {
        let allPhones = [];

        const telLinks = document.querySelectorAll('a[href^="tel:"]');
        telLinks.forEach(link => {
            const phone = extractPhoneFromTelLink(link.href);
            if (phone && !allPhones.includes(phone)) {
                allPhones.push(phone);
            }
        });

        const allElements = document.querySelectorAll('td, span, div, p, li, a, .phone, [class*="phone"], [id*="phone"]');

        for (let el of allElements) {
            const text = el.textContent || '';
            if (el.tagName === 'A' && el.href && el.href.startsWith('tel:')) continue;

            const phones = extractAllPhonesFromText(text);
            phones.forEach(phone => {
                if (!allPhones.includes(phone)) {
                    allPhones.push(phone);
                }
            });
        }

        const reqInfo = document.getElementById('reqInfo');
        if (reqInfo) {
            const text = reqInfo.value || reqInfo.textContent || '';
            const phones = extractAllPhonesFromText(text);
            phones.forEach(phone => {
                if (!allPhones.includes(phone)) {
                    allPhones.push(phone);
                }
            });
        }

        allPhones = [...new Set(allPhones)];
        return allPhones;
    }

    function findFirstPhoneNumber() {
        const phones = findAllPhones();
        return phones.length > 0 ? phones[0] : null;
    }

    function findSecondPhoneNumber() {
        const phones = findAllPhones();
        return phones.length >= 2 ? phones[1] : null;
    }

    // ===== КНОПКА-БЛОКНОТ (КОПИРОВАНИЕ С Ctrl+клик ДЛЯ ВТОРОГО НОМЕРА, БЕЗ ВЫДЕЛЕНИЯ) =====
    function createPhoneCopyButton() {
        const phoneContainer = document.querySelector('#customerInfo .col-lg-3');

        if (!phoneContainer) return;

        if (phoneContainer.querySelector('.crm-phone-copy-btn')) return;

        const text = phoneContainer.textContent || '';

        if (!text.includes('+7') && !text.includes('8(')) return;

        const btn = document.createElement('span');
        btn.className = 'crm-phone-copy-btn';
        btn.textContent = '🕿';
        btn.title = 'Копировать номер телефона\nОбычный клик: первый номер\nCtrl+клик: второй номер';

        // Запрет выделения текста
        btn.style.userSelect = 'none';
        btn.style.webkitUserSelect = 'none';
        btn.style.mozUserSelect = 'none';
        btn.style.msUserSelect = 'none';

        btn.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();

            if (e.ctrlKey) {
                const secondPhone = findSecondPhoneNumber();
                if (secondPhone) {
                    copyToClipboard(secondPhone);
                    console.log('📋 Скопирован второй номер:', secondPhone);
                } else {
                    console.log('ℹ️ Второй номер не найден - ничего не делаем');
                }
            } else {
                const firstPhone = findFirstPhoneNumber();
                if (firstPhone) {
                    copyToClipboard(firstPhone);
                    console.log('📋 Скопирован первый номер:', firstPhone);
                }
            }
        });

        const regionBadge = phoneContainer.querySelector('.region-badge');

        if (regionBadge) {
            phoneContainer.insertBefore(btn, regionBadge);
        } else {
            phoneContainer.appendChild(btn);
        }

        console.log('📝 Кнопка-блокнот добавлена (Ctrl+клик - второй номер, выделение запрещено)');
    }

