    function hasClaimButtonForStatusActions() {
        const fixedButton = document.querySelector('a.btn-outline-primary[data-chat-fixed="true"]');
        if (fixedButton) return true;

        const buttons = Array.from(document.querySelectorAll('a.btn-outline-primary'));

        return buttons.some((element) => {
            const text = (element.textContent || '').trim();
            const href = (element.getAttribute('href') || '').trim();
            const ariaDisabled = (element.getAttribute('aria-disabled') || '').trim().toLowerCase();

            return text === 'Претензия' &&
                   href !== '' &&
                   href !== '#' &&
                   href.toLowerCase() !== 'javascript:void(0)' &&
                   !element.classList.contains('disabled') &&
                   ariaDisabled !== 'true';
        });
    }

