// ============================================
// 25. КНОПКА ИСТОЧНИКА КЛИЕНТА
// ============================================
function loadCustomerSourceButton() {
    const log = (...args) => ScriptManager.log('Источник клиента', ...args);

    if (!window.location.href.includes('/customer/update?id')) {
        return;
    }

    const BUTTON_ID = 'tm-customer-source-button';
    const WRAPPER_ID = 'tm-customer-source-button-wrap';
    const STYLE_ID = 'tm-customer-source-button-style';
    const CACHE_KEY = 'tm-customer-source-reference-v1';
    const CACHE_TTL = 24 * 60 * 60 * 1000;
    const CREATE_URL = '/admin/domain/customer-request/create';
    const ACTIVE_STATUS_PATTERNS = ['На уточнении', 'В работе СД', 'В работе', 'В пути', 'Ожидает'];

    let lastSourceMatchKey = '';
    let lastSourceMatchResult = null;

    function normalize(value) {
        return String(value || '').replace(/\s+/g, ' ').trim();
    }

    function shorten(text, maxLength) {
        const value = normalize(text);
        if (value.length <= maxLength) return value;
        return `${value.slice(0, Math.max(0, maxLength - 1)).trim()}…`;
    }

    function ensureStyles() {
        if (document.getElementById(STYLE_ID)) return;

        const style = document.createElement('style');
        style.id = STYLE_ID;
        style.textContent = `
            #${BUTTON_ID},
            #${BUTTON_ID}:hover,
            #${BUTTON_ID}:active,
            #${BUTTON_ID}:focus {
                transform: none !important;
                transition: none !important;
                animation: none !important;
                box-shadow: none !important;
                filter: none !important;
                text-shadow: none !important;
                outline: none !important;
                background-image: none !important;
                background-repeat: no-repeat !important;
            }
        `;

        document.head.appendChild(style);
    }

    function lockVisualState(button, sourceButton) {
        if (!button || button.dataset.tmVisualLocked === '1') return;

        const baseline = {
            background: '#6c757d',
            backgroundColor: '#6c757d',
            border: '1px solid #6c757d',
            borderColor: '#6c757d',
            color: '#ffffff',
            boxShadow: 'none',
            textShadow: 'none',
            outline: 'none',
            filter: 'none',
            transform: 'none',
            transition: 'none',
            animation: 'none'
        };

        const applyTheme = function() {
            Object.assign(button.style, baseline);

            if (button.dataset.tmVisualTheme === 'success') {
                button.style.background = '#28a745';
                button.style.backgroundColor = '#28a745';
                button.style.borderColor = '#28a745';
                button.style.color = '#ffffff';
            }

            if (button.dataset.tmVisualTheme === 'danger') {
                button.style.background = '#dc3545';
                button.style.backgroundColor = '#dc3545';
                button.style.borderColor = '#dc3545';
                button.style.color = '#ffffff';
            }
        };

        button.dataset.tmVisualTheme = button.dataset.tmVisualTheme || 'baseline';
        button._tmApplyVisualTheme = applyTheme;

        applyTheme();
        button.dataset.tmVisualLocked = '1';

        ['mouseenter', 'mouseleave', 'mousedown', 'mouseup', 'focus', 'blur'].forEach(function(eventName) {
            button.addEventListener(eventName, applyTheme);
        });
    }

    function setVisualTheme(button, theme) {
        if (!button) return;
        button.dataset.tmVisualTheme = theme || 'baseline';
        if (typeof button._tmApplyVisualTheme === 'function') {
            button._tmApplyVisualTheme();
        }
    }

    function readCache() {
        try {
            const raw = localStorage.getItem(CACHE_KEY);
            if (!raw) return null;

            const parsed = JSON.parse(raw);
            if (!parsed || !parsed.savedAt || !parsed.data) return null;
            if ((Date.now() - parsed.savedAt) > CACHE_TTL) return null;

            return parsed.data;
        } catch (error) {
            return null;
        }
    }

    function writeCache(data) {
        try {
            localStorage.setItem(CACHE_KEY, JSON.stringify({
                savedAt: Date.now(),
                data
            }));
        } catch (error) {}
    }

    function mapOptions(select) {
        const result = {};

        if (!select) {
            return result;
        }

        Array.from(select.options).forEach(function(option) {
            const value = normalize(option.value);
            const text = normalize(option.text);
            if (!value || !text) return;
            result[value] = text;
        });

        return result;
    }

    async function fetchReferenceData() {
        const cached = readCache();
        if (cached) {
            return cached;
        }

        const response = await fetch(CREATE_URL, {
            method: 'GET',
            credentials: 'include'
        });

        if (!response.ok) {
            throw new Error(`Не удалось открыть ${CREATE_URL}: ${response.status}`);
        }

        const html = await response.text();
        const parser = new DOMParser();
        const doc = parser.parseFromString(html, 'text/html');

        const data = {
            partners: mapOptions(doc.querySelector('select[name="CustomerRequest[partner_id]"]')),
            adverts: mapOptions(doc.querySelector('select[name="CustomerRequest[advert_id]"]'))
        };

        writeCache(data);
        return data;
    }

    function getSourceParams() {
        const params = new URLSearchParams(window.location.search);
        return {
            partnerId: normalize(params.get('partner_id')),
            advertId: normalize(params.get('advert_id'))
        };
    }

    function buildSourceInfo(referenceData) {
        const params = getSourceParams();

        if (params.partnerId) {
            const partnerNumber = referenceData.partners[params.partnerId] || '';
            return {
                text: partnerNumber ? `Партнер: ${partnerNumber}` : `Партнер ID: ${params.partnerId}`,
                fullText: partnerNumber ? `Партнер: ${partnerNumber}` : `Партнер не найден, partner_id=${params.partnerId}`,
                copyText: partnerNumber || params.partnerId
            };
        }

        if (params.advertId) {
            const advertName = referenceData.adverts[params.advertId] || '';
            return {
                text: advertName ? `Листовка: ${shorten(advertName, 34)}` : `Листовка ID: ${params.advertId}`,
                fullText: advertName ? `Листовка: ${advertName}` : `Листовка не найдена, advert_id=${params.advertId}`,
                copyText: advertName || params.advertId
            };
        }

        return null;
    }

    function extractPartnerNumber(text) {
        const normalizedText = normalize(text);
        const match = normalizedText.match(/(?:парт(?:нер|нёр)?|парт)\s*[:№#-]?\s*(\d+)/i);
        return match ? String(match[1]).trim() : '';
    }

    function normalizePartnerNumber(value) {
        const normalizedValue = String(value || '').trim();
        if (!normalizedValue) {
            return '';
        }

        if (!/^\d+$/.test(normalizedValue)) {
            return normalizedValue;
        }

        const withoutLeadingZeros = normalizedValue.replace(/^0+/, '');
        return withoutLeadingZeros || '0';
    }

    function getRequestRowContainer(link) {
        if (!link) return null;

        return link.closest('tr')
            || link.closest('[data-key]')
            || link.closest('.kv-grid-table tr')
            || link.closest('.grid-view tbody tr')
            || link.closest('.card')
            || link.closest('li')
            || link.parentElement
            || null;
    }

    function buildExpectedSource(referenceData) {
        const params = getSourceParams();

        if (params.partnerId) {
            const partnerText = normalize(referenceData && referenceData.partners ? referenceData.partners[params.partnerId] : '');
            return {
                kind: 'partner',
                id: params.partnerId,
                partnerNumber: normalizePartnerNumber(extractPartnerNumber(partnerText) || partnerText)
            };
        }

        if (params.advertId) {
            const advertText = normalize(referenceData && referenceData.adverts ? referenceData.adverts[params.advertId] : '');
            return {
                kind: 'advert',
                id: params.advertId,
                advertText
            };
        }

        return null;
    }

    function getActiveRequestRows() {
        const rows = [];
        const seen = new Set();

        document.querySelectorAll('a[href*="/customer-request/update?id="]').forEach(function(link) {
            const row = getRequestRowContainer(link);
            if (!row) {
                return;
            }

            if (!getRowActiveStatuses(row).length) {
                return;
            }

            if (seen.has(row)) {
                return;
            }

            seen.add(row);
            rows.push(row);
        });

        return rows;
    }

    function getRowActiveStatuses(row) {
        if (!row) {
            return [];
        }

        const patterns = ACTIVE_STATUS_PATTERNS.map(function(status) {
            return normalize(status).toLowerCase();
        });

        const candidates = Array.from(row.querySelectorAll('td, th, span, div'))
            .map(function(node) {
                return normalize(node.textContent || '');
            })
            .filter(function(text) {
                return text && text.length <= 32;
            });

        return patterns.filter(function(pattern) {
            return candidates.some(function(text) {
                const lowerText = text.toLowerCase();
                return lowerText === pattern || lowerText.startsWith(pattern + ' ');
            });
        });
    }

    function getRowSourceTexts(row) {
        const texts = [];
        const pushText = function(value) {
            const normalizedValue = normalize(value);
            if (normalizedValue) {
                texts.push(normalizedValue);
            }
        };

        const pushAttributes = function(element) {
            if (!element || !element.attributes) {
                return;
            }

            Array.from(element.attributes).forEach(function(attribute) {
                pushText(attribute.value || '');
            });
        };

        if (!row) {
            return texts;
        }

        pushAttributes(row);

        const cells = row.querySelectorAll('td, th, div, span, a');
        cells.forEach(function(cell) {
            pushText(cell.textContent || '');
            pushAttributes(cell);
        });

        pushText(row.textContent || '');
        return texts;
    }

    function getRowCellTexts(row) {
        if (!row) {
            return [];
        }

        return Array.from(row.querySelectorAll('td, th'))
            .map(function(cell) {
                return normalize(cell.textContent || '');
            })
            .filter(Boolean);
    }

    function parseRowSource(row) {
        const sourceTexts = getRowSourceTexts(row);
        const cellTexts = getRowCellTexts(row);
        const rowText = sourceTexts.join(' | ');
        const lowerText = rowText.toLowerCase();
        const trailingCellText = cellTexts.length ? cellTexts[cellTexts.length - 1] : '';

        if (!rowText) {
            return { kind: 'unknown', raw: '' };
        }

        const partnerIdMatch = rowText.match(/partner[_-]?id(?:=|\s*[:#-]?\s*)(\d+)/i);
        if (partnerIdMatch) {
            return {
                kind: 'partner',
                raw: rowText,
                partnerNumber: String(partnerIdMatch[1] || '').trim()
            };
        }

        const advertIdMatch = rowText.match(/advert[_-]?id(?:=|\s*[:#-]?\s*)(\d+)/i);
        if (advertIdMatch) {
            return {
                kind: 'advert',
                raw: rowText,
                advertId: String(advertIdMatch[1] || '').trim()
            };
        }

        const psrcIdMatch = rowText.match(/psrc[_-]?id(?:=|\s*[:#-]?\s*)(\d+)/i);
        if (psrcIdMatch && (/\bрк\b/i.test(rowText) || lowerText.includes('листовк') || lowerText.includes('рекламн'))) {
            return {
                kind: 'advert',
                raw: rowText,
                advertId: String(psrcIdMatch[1] || '').trim()
            };
        }

        if (cellTexts.some(function(text) { return /^рк$/i.test(text); })) {
            return {
                kind: 'advert',
                raw: rowText,
                advertText: trailingCellText
            };
        }

        if (trailingCellText && !/^\d+$/.test(trailingCellText) && !(/\bрк\b/i.test(rowText) || lowerText.includes('листовк') || lowerText.includes('рекламн'))) {
            return {
                kind: 'advert',
                raw: rowText,
                advertText: trailingCellText
            };
        }

        if (/^\d+$/.test(trailingCellText) && !(/\bрк\b/i.test(rowText) || lowerText.includes('листовк') || lowerText.includes('рекламн'))) {
            return {
                kind: 'partner',
                raw: rowText,
                partnerNumber: trailingCellText
            };
        }

        if (/\bрк\b/i.test(rowText) || lowerText.includes('листовк') || lowerText.includes('рекламн')) {
            return {
                kind: 'advert',
                raw: rowText,
                advertText: trailingCellText
            };
        }

        const partnerNumber = extractPartnerNumber(rowText);
        if (partnerNumber || lowerText.includes('партнер') || lowerText.includes('партнёр') || /\bпарт\b/i.test(rowText)) {
            return {
                kind: 'partner',
                raw: rowText,
                partnerNumber: partnerNumber
            };
        }

        return {
            kind: 'unknown',
            raw: rowText
        };
    }

    function isRowMatchingExpectedSource(rowSource, expectedSource) {
        if (!rowSource || !expectedSource || rowSource.kind !== expectedSource.kind) {
            return false;
        }

        if (expectedSource.kind === 'advert') {
            const expectedAdvertText = normalize(expectedSource.advertText).toLowerCase();
            const rowAdvertText = normalize(rowSource.advertText).toLowerCase();

            if (!expectedAdvertText) {
                return rowSource.kind === 'advert';
            }

            if (!rowAdvertText) {
                return false;
            }

            return rowAdvertText === expectedAdvertText
                || rowAdvertText.includes(expectedAdvertText)
                || expectedAdvertText.includes(rowAdvertText);
        }

        if (expectedSource.kind === 'partner') {
            if (!rowSource.partnerNumber) {
                return true;
            }

            const expectedNumbers = [expectedSource.partnerNumber, expectedSource.id]
                .map(function(value) { return normalizePartnerNumber(value); })
                .filter(Boolean);

            return expectedNumbers.includes(normalizePartnerNumber(rowSource.partnerNumber));
        }

        return false;
    }

    async function getSourceMatchState(referenceData) {
        const expectedSource = buildExpectedSource(referenceData);
        if (!expectedSource) {
            return { hasActiveStatuses: false, isMismatch: false };
        }

        const activeRows = getActiveRequestRows();
        if (!activeRows.length) {
            return { hasActiveStatuses: false, isMismatch: false };
        }

        const rowsSignature = activeRows.map(function(row) {
            return normalize(row.textContent || '');
        }).join('|');

        const cacheKey = `${expectedSource.kind}:${expectedSource.id}:${expectedSource.partnerNumber || expectedSource.advertText || ''}|${rowsSignature}`;
        if (cacheKey === lastSourceMatchKey && lastSourceMatchResult) {
            return lastSourceMatchResult;
        }

        let hasRecognizedSource = false;
        let hasMismatch = false;

        activeRows.forEach(function(row) {
            const rowSource = parseRowSource(row);
            if (rowSource.kind === 'unknown') {
                return;
            }

            hasRecognizedSource = true;
            if (!isRowMatchingExpectedSource(rowSource, expectedSource)) {
                hasMismatch = true;
            }
        });

        const result = {
            hasActiveStatuses: true,
            hasRecognizedSource,
            isMismatch: hasRecognizedSource ? hasMismatch : true
        };

        lastSourceMatchKey = cacheKey;
        lastSourceMatchResult = result;
        return result;
    }

    function copyText(text) {
        if (!text) return;

        copyTextSafely(text).catch(function() {});
    }

    function findAddRequestButton() {
        const candidates = Array.from(document.querySelectorAll('a, button, input[type="button"], input[type="submit"]'));

        let best = null;
        let bestScore = -1;

        candidates.forEach(function(element) {
            const text = normalize(element.textContent || element.value || '');
            const href = normalize(element.getAttribute('href') || '');
            let score = 0;

            if (text.includes('Добавить заявку')) score += 10;
            if (href.includes('/customer-request/create')) score += 8;
            if (href.includes('customer_id=')) score += 4;
            if (element.className && String(element.className).includes('btn')) score += 2;

            if (score > bestScore) {
                best = element;
                bestScore = score;
            }
        });

        return bestScore > 0 ? best : null;
    }

    function createSourceButton(sourceButton) {
        const existingButton = document.getElementById(BUTTON_ID);
        if (existingButton) {
            return existingButton;
        }

        let wrapper = document.getElementById(WRAPPER_ID);
        if (!wrapper) {
            wrapper = document.createElement('span');
            wrapper.id = WRAPPER_ID;
            wrapper.style.display = 'inline-flex';
            wrapper.style.alignItems = 'center';
            wrapper.style.gap = '8px';
            wrapper.style.flexWrap = 'nowrap';

            sourceButton.parentNode.insertBefore(wrapper, sourceButton);
            wrapper.appendChild(sourceButton);
        }

        const tagName = sourceButton.tagName.toLowerCase() === 'a' ? 'a' : 'button';
        const button = document.createElement(tagName);
        button.id = BUTTON_ID;
        button.className = sourceButton.className;
        button.style.marginRight = '0';
        button.style.whiteSpace = 'nowrap';
        button.style.maxWidth = '360px';
        button.style.overflow = 'hidden';
        button.style.textOverflow = 'ellipsis';

        if (tagName === 'a') {
            button.href = 'javascript:void(0)';
        } else {
            button.type = 'button';
        }

        wrapper.insertBefore(button, sourceButton);
        lockVisualState(button, sourceButton);
        return button;
    }

    function setButtonState(button, text, title) {
        button.textContent = text;
        button.title = title || text;
    }

    let __tmSourceNullKey = null;
    async function renderButton() {
        const sourceButton = findAddRequestButton();
        if (!sourceButton || !sourceButton.parentNode) {
            return false;
        }

        const params = getSourceParams();
        if (!params.partnerId && !params.advertId) {
            return true;
        }

        // Дедуп: MutationObserver дёргает renderButton на КАЖДУЮ мутацию DOM. Без дедупа
        // кнопка каждый раз сбрасывается в «Определяю источник...» и заново фетчит — мигание.
        const sourceKey = String(params.partnerId || '') + '|' + String(params.advertId || '');
        const existingBtn = document.getElementById(BUTTON_ID);
        if (existingBtn && existingBtn.dataset.tmSourceResolvedKey === sourceKey) {
            return true;                       // уже определён для этих параметров — не трогаем
        }
        if (!existingBtn && __tmSourceNullKey === sourceKey) {
            return true;                       // источник для этих параметров не найден — не фетчим повторно
        }

        const button = createSourceButton(sourceButton);
        setButtonState(button, 'Определяю источник...', 'Определяю источник заявки');
        setVisualTheme(button, 'baseline');

        try {
            const referenceData = await fetchReferenceData();
            const info = buildSourceInfo(referenceData);

            if (!info) {
                __tmSourceNullKey = sourceKey;
                button.remove();
                return true;
            }

            const matchState = await getSourceMatchState(referenceData);
            const hasActiveStatuses = matchState.hasActiveStatuses;
            const isDanger = hasActiveStatuses && matchState.isMismatch;
            const isSuccess = hasActiveStatuses && !matchState.isMismatch;

            setButtonState(button, info.text, info.fullText);
            setVisualTheme(button, isDanger ? 'danger' : (isSuccess ? 'success' : 'baseline'));
            button.dataset.tmSourceResolvedKey = sourceKey;   // определено — больше не мигаем на мутациях
            __tmSourceNullKey = null;

            if (isDanger) {
                button.title = `${info.fullText} | Есть заявка со статусом На уточнении / Ожидает / В пути / В работе / В работе СД, но источник не совпадает`;
            } else if (isSuccess) {
                button.title = `${info.fullText} | Есть заявка со статусом На уточнении / Ожидает / В пути / В работе / В работе СД, источник совпадает`;
            } else {
                button.title = `${info.fullText} | Нет активных заявок со статусом На уточнении / Ожидает / В пути / В работе / В работе СД`;
            }

            button.onclick = function(event) {
                event.preventDefault();
                copyText(info.copyText);
            };
        } catch (error) {
            setButtonState(button, 'Источник не найден', String(error && error.message ? error.message : error));
            setVisualTheme(button, 'danger');
            button.onclick = function(event) {
                event.preventDefault();
            };
            console.error('[TM] Ошибка определения источника:', error);
        }

        return true;
    }

    function init() {
        ensureStyles();

        let isRendering = false;

        const tryRender = function() {
            if (isRendering) return;
            isRendering = true;

            Promise.resolve(renderButton()).finally(function() {
                isRendering = false;
            });
        };

        tryRender();

        const observer = new MutationObserver(function() {
            tryRender();
        });

        observer.observe(document.documentElement, {
            childList: true,
            subtree: true
        });

        log('✅ Кнопка источника клиента активирована');
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
}

// ============================================
// 26. ЛОГИКА ПАРТНЕРА: Отзыв (723/007) + Комментарий (только 723)
// ============================================
function loadPartnerReviewLogic() {
    const log = (...args) => ScriptManager.log('Партнер/Отзыв', ...args);
    const isCreatePage = window.location.href.includes('/customer-request/create');
    const isUpdatePage = window.location.href.includes('/customer-request/update');
    const COMMENTS_SELECTOR = 'textarea[name="CustomerRequest[comments]"], textarea[name="CustomerRequest[comment]"]';
    let commentNormalizeObserver = null;
    const norm = (s) => (s || '').replace(/\s+/g, ' ').trim();

    function findCommentsField() {
        const byId = document.getElementById('customerrequest-comments');
        if (byId && byId.tagName === 'TEXTAREA') {
            return byId;
        }
        const byNewId = document.getElementById('customerrequest-comment');
        if (byNewId && byNewId.tagName === 'TEXTAREA') {
            return byNewId;
        }

        return document.querySelector(COMMENTS_SELECTOR);
    }

    if (!isCreatePage && !isUpdatePage) {
        log('ℹ️ Не create/update: включаю только ручную логику после изменения партнера');
    }

    function ensureCommentNormalizationBootstrap() {
        if (ensureNameSecondRowHandler()) {
            if (commentNormalizeObserver) {
                commentNormalizeObserver.disconnect();
                commentNormalizeObserver = null;
            }
            return true;
        }

        if (!commentNormalizeObserver && document.documentElement) {
            commentNormalizeObserver = new MutationObserver(() => {
                if (ensureNameSecondRowHandler()) {
                    commentNormalizeObserver.disconnect();
                    commentNormalizeObserver = null;
                }
            });

            commentNormalizeObserver.observe(document.documentElement, {
                childList: true,
                subtree: true
            });
        }

        [50, 200, 500, 1000, 2000, 3500].forEach((delay) => {
            setTimeout(() => {
                if (ensureNameSecondRowHandler() && commentNormalizeObserver) {
                    commentNormalizeObserver.disconnect();
                    commentNormalizeObserver = null;
                }
            }, delay);
        });

        return false;
    }

    function initManualPartnerChangeAutomation(attempt = 0) {
        if (window.__tmPartnerReviewManualBound) return true;

        const PARTNER_HIDDEN_MANUAL = '#customerrequest-partner_id, select[name="CustomerRequest[partner_id]"], input[name="CustomerRequest[partner_id]"]';
        const PARTNER_SHOWN_MANUAL = '#select2-customerrequest-partner_id-container';
        const REVIEW_CHECKBOX_MANUAL = [
            '#customerrequest-is_req_fback',
            'input[name="CustomerRequest[is_req_fback]"]',
            'input[type="checkbox"][id*="fback"]',
            'input[type="checkbox"][name*="fback"]',
            'input[type="checkbox"][id*="feedback"]',
            'input[type="checkbox"][name*="feedback"]'
        ].join(',');
        const PARTNER_TEXT_BLOCK_MANUAL = '#partnerCommentBlock';
        const REVIEW_HIDDEN_ALLOWED_MANUAL = new Set(['723', '773', '007', '7']);
        const REVIEW_SHOWN_ALLOWED_MANUAL = new Set(['723', '007', '7', '639', '699', '222', '685', '340', '701', '748']);
        const COMMENT_HIDDEN_ALLOWED_MANUAL = new Set(['723', '773']);
        const COMMENT_SHOWN_ALLOWED_MANUAL = new Set(['723']);

        const hasAnyPartnerUi = document.querySelector([
            PARTNER_HIDDEN_MANUAL,
            PARTNER_SHOWN_MANUAL,
            REVIEW_CHECKBOX_MANUAL,
            PARTNER_TEXT_BLOCK_MANUAL
        ].join(','));

        if (!hasAnyPartnerUi) {
            if (attempt < 24) {
                setTimeout(() => initManualPartnerChangeAutomation(attempt + 1), 500);
            } else {
                log('⏭️ Поля партнера на этой странице не найдены, ручная логика не активирована');
            }
            return false;
        }

        window.__tmPartnerReviewManualBound = true;
        let manualPartnerChangedUntil = 0;
        let lastManualCommentKey = '';
        let lastManualReviewLabelClickAt = 0;

        function getManualPartnerState() {
            const hidden = document.querySelector(PARTNER_HIDDEN_MANUAL);
            const shown = document.querySelector(PARTNER_SHOWN_MANUAL);
            return {
                hiddenValue: String(hidden?.value || '').trim(),
                shownText: norm(shown?.textContent || '')
            };
        }

        function getManualShownNumbers(shownText) {
            const nums = shownText.match(/\d+/g) || [];
            const expanded = new Set();
            for (const n of nums) {
                expanded.add(n);
                expanded.add((n.replace(/^0+/, '') || '0'));
            }
            return expanded;
        }

        function isManualAllowedForReview(state) {
            if (REVIEW_HIDDEN_ALLOWED_MANUAL.has(state.hiddenValue)) return true;
            const nums = getManualShownNumbers(state.shownText);
            for (const n of nums) {
                if (REVIEW_SHOWN_ALLOWED_MANUAL.has(n)) return true;
            }
            return false;
        }

        function isManualAllowedForComment(state) {
            if (COMMENT_HIDDEN_ALLOWED_MANUAL.has(state.hiddenValue)) return true;
            const nums = getManualShownNumbers(state.shownText);
            for (const n of nums) {
                if (COMMENT_SHOWN_ALLOWED_MANUAL.has(n)) return true;
            }
            return false;
        }

        function armManualPartnerChange() {
            manualPartnerChangedUntil = Date.now() + 8000;
        }

        function isManualPartnerTarget(target) {
            if (!(target instanceof Element)) return false;
            return Boolean(
                target.closest(PARTNER_HIDDEN_MANUAL)
                || target.closest(PARTNER_SHOWN_MANUAL)
                || target.closest('.field-customerrequest-partner_id')
                || target.closest('.select2-results__option')
            );
        }

        function isManualReviewLabel(el) {
            if (!(el instanceof Element)) return false;
            const text = norm(el.textContent || '').toLowerCase();
            return text === 'отзыв' || text.startsWith('отзыв ');
        }

        function findManualReviewLabel() {
            return Array.from(document.querySelectorAll('label, .custom-control-label'))
                .find(isManualReviewLabel);
        }

        function findManualReviewCheckboxByLabel(label) {
            if (!(label instanceof Element)) return null;

            const forId = label.getAttribute('for');
            if (forId) {
                const linked = document.getElementById(forId);
                if (linked && linked.matches('input[type="checkbox"], input[type="radio"]')) {
                    return linked;
                }
            }

            const wrap = label.closest('.custom-control, .custom-checkbox, .custom-switch, .form-group, .mb-2');
            return wrap ? wrap.querySelector('input[type="checkbox"], input[type="radio"]') : null;
        }

        function dispatchManualReviewEvents(el) {
            el.dispatchEvent(new Event('input', { bubbles: true }));
            el.dispatchEvent(new Event('change', { bubbles: true }));
            if (window.jQuery) {
                window.jQuery(el).trigger('input').trigger('change');
            }
        }

        function setManualReviewChecked() {
            const label = findManualReviewLabel();
            const cb = document.querySelector(REVIEW_CHECKBOX_MANUAL) || findManualReviewCheckboxByLabel(label);

            // Работаем по состоянию: если уже включено — не трогаем (иначе клик снял бы галку).
            if (cb) {
                if (cb.checked) {
                    return;
                }
                // Включаем проверенным путём (клик по label/чекбоксу — кастомный свитч реагирует именно на клик),
                // с прямым состоянием как страховкой, если клик не сработал.
                if (label) {
                    label.click();
                }
                if (!cb.checked && typeof cb.click === 'function') {
                    cb.click();
                }
                if (!cb.checked) {
                    cb.checked = true;
                    cb.setAttribute('checked', 'checked');
                    dispatchManualReviewEvents(cb);
                }
                console.log('[TM] Отзыв включен после ручного изменения партнера через UI/checkbox');
                return;
            }

            // Чекбокс напрямую не найден: кликаем по label, но сначала убеждаемся, что галки нет.
            if (label) {
                const linkedBefore = findManualReviewCheckboxByLabel(label);
                if (linkedBefore && linkedBefore.checked) {
                    // Уже включено — клик по label только снял бы отзыв.
                    return;
                }
                if (Date.now() - lastManualReviewLabelClickAt > 1500) {
                    lastManualReviewLabelClickAt = Date.now();
                    label.click();
                    console.log('[TM] Отзыв включен после ручного изменения партнера через label');
                    setTimeout(() => {
                        const cbAfterClick = findManualReviewCheckboxByLabel(label);
                        if (cbAfterClick && !cbAfterClick.checked) {
                            cbAfterClick.checked = true;
                            cbAfterClick.setAttribute('checked', 'checked');
                            dispatchManualReviewEvents(cbAfterClick);
                        }
                    }, 50);
                }
                return;
            }

            console.log('[TM] Не найден переключатель Отзыв после ручного изменения партнера');
        }

        function getManualPartnerText() {
            const el = document.querySelector(PARTNER_TEXT_BLOCK_MANUAL);
            return el ? norm(el.textContent) : '';
        }

        function appendManualPartnerTextToComments(state) {
            const ta = findCommentsField();
            if (!ta) return;

            const txt = getManualPartnerText();
            if (!txt) return;

            const key = `${state.hiddenValue}|${state.shownText}|${txt}`;
            if (key === lastManualCommentKey) return;

            const current = String(ta.value || '');
            const normalizedCurrent = norm(current);
            const normalizedText = norm(txt);
            if (normalizedText && normalizedCurrent.includes(normalizedText)) {
                lastManualCommentKey = key;
                return;
            }

            const trimmedEnd = current.replace(/\s+$/, '');
            ta.value = trimmedEnd ? `${trimmedEnd}\n${txt}` : txt;
            ta.dispatchEvent(new Event('input', { bubbles: true }));
            ta.dispatchEvent(new Event('change', { bubbles: true }));
            lastManualCommentKey = key;
            console.log('[TM] Комментарий партнера добавлен после ручного изменения:', txt);
        }

        function runManualAutomation(source) {
            if (Date.now() > manualPartnerChangedUntil) return;

            const state = getManualPartnerState();
            if (!state.hiddenValue && !state.shownText) return;

            if (isManualAllowedForReview(state)) {
                setTimeout(setManualReviewChecked, 50);
                setTimeout(setManualReviewChecked, 250);
                setTimeout(setManualReviewChecked, 700);
            }

            if (isManualAllowedForComment(state)) {
                [80, 350, 900, 1600, 2800].forEach((delay) => {
                    setTimeout(() => appendManualPartnerTextToComments(state), delay);
                });
            }

            console.log('[TM] manual partner run:', source, state, {
                reviewAllowed: isManualAllowedForReview(state),
                commentAllowed: isManualAllowedForComment(state)
            });
        }

        document.addEventListener('pointerdown', (event) => {
            if (isManualPartnerTarget(event.target)) {
                armManualPartnerChange();
            }
        }, true);

        document.addEventListener('keydown', (event) => {
            if (isManualPartnerTarget(event.target)) {
                armManualPartnerChange();
            }
        }, true);

        document.addEventListener('input', (event) => {
            if (isManualPartnerTarget(event.target)) {
                armManualPartnerChange();
                setTimeout(() => runManualAutomation('manual.input'), 80);
            }
        }, true);

        document.addEventListener('change', (event) => {
            if (isManualPartnerTarget(event.target)) {
                armManualPartnerChange();
                setTimeout(() => runManualAutomation('manual.change'), 80);
            }
        }, true);

        const shown = document.querySelector(PARTNER_SHOWN_MANUAL);
        if (shown) {
            const moShown = new MutationObserver(() => {
                setTimeout(() => runManualAutomation('manual.shown.mutation'), 80);
            });
            moShown.observe(shown, { childList: true, subtree: true, characterData: true, attributes: true });
        }

        const textBlock = document.querySelector(PARTNER_TEXT_BLOCK_MANUAL);
        if (textBlock) {
            const moText = new MutationObserver(() => {
                setTimeout(() => runManualAutomation('manual.partnerText.mutation'), 80);
            });
            moText.observe(textBlock, { childList: true, subtree: true, characterData: true, attributes: true });
        }

        log('✅ Ручная логика партнера активирована: срабатывает только после изменения поля партнера');
        return true;
    }

    if (!isCreatePage) {
        if (isUpdatePage) {
            ensureCommentNormalizationBootstrap();
        }
        initManualPartnerChangeAutomation();
        log('📝 Партнер/отзыв только после ручного изменения; нормализация первой строки активна только на update');
        return;
    }

    console.log('🤝 Логика партнера v2.3.1 - Отзыв (723/007) + Комментарий (только 723)');

    const PARTNER_HIDDEN = '#customerrequest-partner_id';
    const PARTNER_SHOWN = '#select2-customerrequest-partner_id-container';

    const REVIEW_CHECKBOX = '#customerrequest-is_req_fback';
    const PARTNER_TEXT_BLOCK = '#partnerCommentBlock';

    // Отзыв: 723 и 007
    const REVIEW_HIDDEN_ALLOWED = new Set(['723', '773', '007', '7']);
    const REVIEW_SHOWN_ALLOWED = new Set(['723', '007', '7', '639', '699', '222', '685', '340', '701', '748', '759']);

    // Комментарий: только 723
    const COMMENT_HIDDEN_ALLOWED = new Set(['723', '773']);
    const COMMENT_SHOWN_ALLOWED = new Set(['723']);

    let lastPartnerText = '';
    let lastCommentPartnerId = null; // сброс lastPartnerText при смене партнёра (см. runAutomation)

    function getPartnerState() {
        const hidden = document.querySelector(PARTNER_HIDDEN);
        const shown = document.querySelector(PARTNER_SHOWN);
        return {
            hiddenValue: String(hidden?.value || '').trim(),
            shownText: norm(shown?.textContent || '')
        };
    }

    function getShownNumbers(shownText) {
        const nums = shownText.match(/\d+/g) || [];
        const expanded = new Set();
        for (const n of nums) {
            expanded.add(n);
            expanded.add((n.replace(/^0+/, '') || '0')); // 007 -> 7
        }
        return expanded;
    }

    function isAllowedForReview(state) {
        if (REVIEW_HIDDEN_ALLOWED.has(state.hiddenValue)) return true;
        const nums = getShownNumbers(state.shownText);
        for (const n of nums) {
            if (REVIEW_SHOWN_ALLOWED.has(n)) return true;
        }
        return false;
    }

    function isAllowedForComment(state) {
        if (COMMENT_HIDDEN_ALLOWED.has(state.hiddenValue)) return true;
        const nums = getShownNumbers(state.shownText);
        for (const n of nums) {
            if (COMMENT_SHOWN_ALLOWED.has(n)) return true;
        }
        return false;
    }

    function setReviewChecked() {
        const cb = document.querySelector(REVIEW_CHECKBOX);
        if (!cb) return;
        if (!cb.checked) {
            cb.checked = true;
            cb.dispatchEvent(new Event('input', { bubbles: true }));
            cb.dispatchEvent(new Event('change', { bubbles: true }));
            console.log('[TM] Отзыв включен');
        }
    }

    function getPartnerText() {
        const el = document.querySelector(PARTNER_TEXT_BLOCK);
        return el ? norm(el.textContent) : '';
    }

    function appendPartnerTextToComments() {
        const ta = findCommentsField();
        if (!ta) return;

        const txt = getPartnerText();
        if (!txt) return;
        if (txt === lastPartnerText) return;
        lastPartnerText = txt;

        const current = ta.value || '';
        const trimmedEnd = current.replace(/\s+$/, '');
        if (trimmedEnd.endsWith(txt)) return;

        const wasFocused = document.activeElement === ta;
        const selectionStart = typeof ta.selectionStart === 'number' ? ta.selectionStart : null;
        const selectionEnd = typeof ta.selectionEnd === 'number' ? ta.selectionEnd : null;

        // Вставка в конец с новой строки (даже если было пусто)
        ta.value = `${trimmedEnd}\n${txt}`;
        ta.dispatchEvent(new Event('input', { bubbles: true }));
        ta.dispatchEvent(new Event('change', { bubbles: true }));

        if (wasFocused && typeof ta.setSelectionRange === 'function' && selectionStart !== null && selectionEnd !== null) {
            const safeStart = Math.max(0, Math.min(selectionStart, trimmedEnd.length));
            const safeEnd = Math.max(0, Math.min(selectionEnd, trimmedEnd.length));
            ta.setSelectionRange(safeStart, safeEnd);

            setTimeout(() => {
                if (document.activeElement === ta && typeof ta.setSelectionRange === 'function') {
                    ta.setSelectionRange(safeStart, safeEnd);
                }
            }, 0);
        }

        console.log('[TM] Комментарий добавлен (только для 723):', txt);
    }

    function looksLikePersonNameLine(line) {
        const cleanLine = norm(String(line || '').replace(/\./g, ' '));
        if (!cleanLine || /\d/.test(cleanLine) || /[,;:()\/\\]/.test(cleanLine)) {
            return false;
        }

        const words = cleanLine.split(/\s+/).filter(Boolean);
        if (words.length < 2 || words.length > 4) {
            return false;
        }

        const prefix = (words[0] || '').toLowerCase();
        if (prefix !== 'мс' && prefix !== 'мастер') {
            return false;
        }

        const nameWords = words.slice(1);
        if (nameWords.length < 1 || nameWords.length > 3) {
            return false;
        }

        return nameWords.every((word) => /^[А-Яа-яЁёA-Za-z-]{2,}$/.test(word));
    }

    function moveCommentLineToSecondRowIfNeeded(predicate, logLabel, options = {}) {
        const ta = findCommentsField();
        if (!ta) return;

        if (options.onlyWhenFieldFocused && document.activeElement !== ta) {
            return;
        }

        const currentValue = String(ta.value || '').replace(/\r/g, '');
        if (!currentValue || currentValue.startsWith('\n')) {
            return;
        }

        const lines = currentValue.split('\n');
        const firstLine = (lines[0] || '').trim();
        if (!predicate(firstLine)) {
            return;
        }

        const selectionStart = ta.selectionStart;
        const selectionEnd = ta.selectionEnd;
        const firstLineLength = (lines[0] || '').length;

        if (options.onlyWhenCaretOnFirstRow && typeof selectionStart === 'number' && selectionStart > firstLineLength) {
            return;
        }

        ta.value = `\n${currentValue}`;
        ta.dispatchEvent(new Event('input', { bubbles: true }));
        ta.dispatchEvent(new Event('change', { bubbles: true }));

        if (document.activeElement === ta && typeof ta.setSelectionRange === 'function') {
            if (options.keepCaretOnFirstRow) {
                ta.setSelectionRange(0, 0);
            } else {
                ta.setSelectionRange(selectionStart + 1, selectionEnd + 1);
            }
        }

        console.log(`[TM] ${logLabel} с первой строки перенесено на вторую:`, firstLine);
    }

    function moveNameLineToSecondRowIfNeeded() {
        moveCommentLineToSecondRowIfNeeded(
            (firstLine) => looksLikePersonNameLine(firstLine),
            'Имя',
            { onlyWhenFieldFocused: true }
        );
    }

    function shouldSuppressNameSecondRowMove(previousValue, currentValue) {
        const prev = String(previousValue || '').replace(/\r/g, '');
        const next = String(currentValue || '').replace(/\r/g, '');

        if (!prev.startsWith('\n') || next.startsWith('\n')) {
            return false;
        }

        const firstLine = (next.split('\n')[0] || '').trim();
        return looksLikePersonNameLine(firstLine);
    }

    function ensureDashSpaceInFirstLineIfNeeded() {
        const ta = findCommentsField();
        if (!ta) return;

        const currentValue = String(ta.value || '').replace(/\r/g, '');
        if (!currentValue) {
            ta.dataset.lastFirstLineValue = '';
            return;
        }

        const lines = currentValue.split('\n');
        const firstLine = lines[0] || '';
        const previousFirstLine = String(ta.dataset.lastFirstLineValue || '');

        if (firstLine.startsWith('-') && !firstLine.startsWith('- ') && !previousFirstLine.startsWith('-')) {
            lines[0] = `- ${firstLine.slice(1)}`;
            const nextValue = lines.join('\n');

            const selectionStart = ta.selectionStart;
            const selectionEnd = ta.selectionEnd;
            ta.value = nextValue;
            ta.dispatchEvent(new Event('input', { bubbles: true }));
            ta.dispatchEvent(new Event('change', { bubbles: true }));

            if (document.activeElement === ta && typeof ta.setSelectionRange === 'function') {
                ta.setSelectionRange(selectionStart + 1, selectionEnd + 1);
            }

            ta.dataset.lastFirstLineValue = '- ';
            return;
        }

        ta.dataset.lastFirstLineValue = firstLine;
    }

    function normalizeFirstCommentLine(options = {}) {
        ensureDashSpaceInFirstLineIfNeeded();
        if (options.moveNameOnFocus === true || options.moveNameOnInput === true) {
            moveNameLineToSecondRowIfNeeded();
        }
    }

    function ensureNameSecondRowHandler() {
        const comments = findCommentsField();
        if (!comments) {
            return false;
        }

        if (!comments.hasAttribute('data-name-second-row-handler')) {
            comments.setAttribute('data-name-second-row-handler', 'true');
            comments.addEventListener('focus', () => {
                comments.dataset.nameSecondRowSuppress = '0';
                comments.dataset.nameSecondRowPrevValue = String(comments.value || '').replace(/\r/g, '');
                setTimeout(() => normalizeFirstCommentLine({ moveNameOnFocus: true }), 0);
            });
            comments.addEventListener('input', () => {
                const previousValue = String(comments.dataset.nameSecondRowPrevValue || '');
                const currentValue = String(comments.value || '').replace(/\r/g, '');

                if (shouldSuppressNameSecondRowMove(previousValue, currentValue)) {
                    comments.dataset.nameSecondRowSuppress = '1';
                }

                comments.dataset.nameSecondRowPrevValue = currentValue;

                setTimeout(() => {
                    if (comments.dataset.nameSecondRowSuppress === '1') {
                        return;
                    }

                    normalizeFirstCommentLine({ moveNameOnInput: true });
                }, 0);
            });
            comments.addEventListener('blur', () => {
                comments.dataset.nameSecondRowPrevValue = String(comments.value || '').replace(/\r/g, '');
            });
        }

        setTimeout(() => normalizeFirstCommentLine({ moveNameOnFocus: false }), 0);
        return true;
    }

    function runAutomation(source) {
        const state = getPartnerState();

        // Сброс дедуп-guard при СМЕНЕ партнёра: иначе повторная заявка с тем же партнёром (та же
        // «БЕЛАЯ ЗАЯВКА») блокировалась (txt === lastPartnerText) и инфо НЕ дописывалось в комментарий
        // (баг «редко не переносится», подтверждён чёрным ящиком). Дубли внутри выбора ловит endsWith(txt).
        if (state.hiddenValue !== lastCommentPartnerId) { lastCommentPartnerId = state.hiddenValue; lastPartnerText = ''; }

        // 1) Отзыв для 723/007
        if (isAllowedForReview(state)) {
            setTimeout(setReviewChecked, 50);
            setTimeout(setReviewChecked, 250);
            setTimeout(setReviewChecked, 700);
        }

        // 2) Комментарий только для 723
        if (isAllowedForComment(state)) {
            setTimeout(appendPartnerTextToComments, 80);
            setTimeout(appendPartnerTextToComments, 350);
            setTimeout(appendPartnerTextToComments, 900);
        }

        console.log('[TM] run:', source, state, {
            reviewAllowed: isAllowedForReview(state),
            commentAllowed: isAllowedForComment(state)
        });
    }

    function init() {
        const commentsReady = ensureCommentNormalizationBootstrap();
        const hidden = document.querySelector(PARTNER_HIDDEN);
        const shown = document.querySelector(PARTNER_SHOWN);
        const textBlock = document.querySelector(PARTNER_TEXT_BLOCK);

        if (!hidden || !shown || !textBlock) {
            if (!commentsReady) {
                setTimeout(init, 1200);
                return;
            }
            setTimeout(init, 1200);
            return;
        }

        hidden.addEventListener('change', () => runAutomation('hidden.change'));
        hidden.addEventListener('input', () => runAutomation('hidden.input'));

        const moShown = new MutationObserver(() => {
            setTimeout(() => runAutomation('shown.mutation'), 80);
        });
        moShown.observe(shown, { childList: true, subtree: true, characterData: true, attributes: true });

        const moText = new MutationObserver(() => {
            setTimeout(() => runAutomation('partnerText.mutation'), 80);
        });
        moText.observe(textBlock, { childList: true, subtree: true, characterData: true, attributes: true });

        setInterval(() => runAutomation('interval'), 1500);
        setTimeout(() => runAutomation('init'), 700);
        setTimeout(() => normalizeFirstCommentLine({ moveNameOnFocus: false }), 300);

        console.log('[TM] init done');
    }

    init();
}

function loadCommentFirstLineNormalizer() {
    const isCreatePage = window.location.href.includes('/customer-request/create');
    const isUpdatePage = window.location.href.includes('/customer-request/update');
    const COMMENT_SELECTOR = 'textarea[name="CustomerRequest[comments]"], textarea[name="CustomerRequest[comment]"]';
    const COMMENT_LINK_PATTERN = /(?:https?:\/\/|www\.)\S+/i;
    let observer = null;
    let intervalId = null;

    if (!isCreatePage && !isUpdatePage) {
        return;
    }

    function findCommentField() {
        const byId = document.getElementById('customerrequest-comments');
        if (byId && byId.tagName === 'TEXTAREA') {
            return byId;
        }
        const byNewId = document.getElementById('customerrequest-comment');
        if (byNewId && byNewId.tagName === 'TEXTAREA') {
            return byNewId;
        }

        return document.querySelector(COMMENT_SELECTOR);
    }

    function moveLinkLineToSecondRowIfNeeded(field, options = {}) {
        if (!field) return false;

        const currentValue = String(field.value || '').replace(/\r/g, '');
        if (!currentValue || currentValue.startsWith('\n')) {
            return false;
        }

        const lines = currentValue.split('\n');
        const firstLine = String(lines[0] || '').trim();
        if (!COMMENT_LINK_PATTERN.test(firstLine)) {
            return false;
        }

        const selectionStart = field.selectionStart;
        const selectionEnd = field.selectionEnd;
        const firstLineLength = (lines[0] || '').length;

        if (options.onlyWhenCaretOnFirstRow && typeof selectionStart === 'number' && selectionStart > firstLineLength) {
            return false;
        }

        field.value = `\n${currentValue}`;
        field.dispatchEvent(new Event('input', { bubbles: true }));
        field.dispatchEvent(new Event('change', { bubbles: true }));

        if (document.activeElement === field && typeof field.setSelectionRange === 'function') {
            if (options.keepCaretOnFirstRow) {
                field.setSelectionRange(0, 0);
            } else if (typeof selectionStart === 'number' && typeof selectionEnd === 'number') {
                field.setSelectionRange(selectionStart + 1, selectionEnd + 1);
            }
        }

        return true;
    }

    function bindField(field) {
        if (!field || field.dataset.crmCommentFirstLineNormalizer === '1') {
            return;
        }

        field.addEventListener('focus', () => {
            setTimeout(() => moveLinkLineToSecondRowIfNeeded(field, {
                keepCaretOnFirstRow: true,
                onlyWhenCaretOnFirstRow: true
            }), 0);
        });
        field.dataset.crmCommentFirstLineNormalizer = '1';
    }

    function ensureRuntime() {
        const field = findCommentField();
        if (field) {
            bindField(field);
        }

        if (!observer && document.documentElement) {
            observer = new MutationObserver(() => {
                setTimeout(ensureRuntime, 0);
            });

            observer.observe(document.documentElement, {
                childList: true,
                subtree: true
            });
        }

        if (!intervalId) {
            intervalId = window.setInterval(() => {
                const activeField = findCommentField();
                if (!activeField) return;
                bindField(activeField);
            }, 1200);
        }
    }

    ensureRuntime();
}

function loadKeyboardLayoutAutoFix() {
    const isCreatePage = window.location.href.includes('/customer-request/create');
    const isUpdatePage = window.location.href.includes('/customer-request/update');
    const isCustomerPage = window.location.href.includes('/customer/update');
    const FIELD_SELECTOR = 'textarea, input[type="text"], input:not([type])';
    const BOUND_ATTR = 'data-tm-layout-fix-bound';
    const APPLYING_ATTR = 'data-tm-layout-fix-applying';
    const PENDING_ATTR = 'data-tm-layout-fix-pending';
    const TOKEN_BREAK_RE = /[\s!?(){}<>":|/\\@]+/;
    let observer = null;

    if (!isCreatePage && !isUpdatePage && !isCustomerPage) {
        return;
    }

    const EN_TO_RU = {
        q: 'й', w: 'ц', e: 'у', r: 'к', t: 'е', y: 'н', u: 'г', i: 'ш', o: 'щ', p: 'з', '[': 'х', ']': 'ъ',
        a: 'ф', s: 'ы', d: 'в', f: 'а', g: 'п', h: 'р', j: 'о', k: 'л', l: 'д', ';': 'ж', "'": 'э',
        z: 'я', x: 'ч', c: 'с', v: 'м', b: 'и', n: 'т', m: 'ь', ',': 'б', '.': 'ю', '`': 'ё'
    };
    const RU_TO_EN = Object.keys(EN_TO_RU).reduce((acc, key) => {
        acc[EN_TO_RU[key]] = key;
        return acc;
    }, {});

    function translateLayout(text, map) {
        return String(text || '').split('').map((char) => {
            const lower = char.toLowerCase();
            const translated = map[lower];
            if (!translated) {
                return char;
            }

            return char === lower ? translated : translated.toUpperCase();
        }).join('');
    }

    function countMatches(text, regex) {
        return (String(text || '').match(regex) || []).length;
    }

    function countPatternHits(text, patterns) {
        return patterns.reduce((total, pattern) => total + countMatches(text, pattern), 0);
    }

    function getMaxConsonantCluster(text, vowelRegex) {
        let maxCluster = 0;
        let currentCluster = 0;

        String(text || '').split('').forEach((char) => {
            if (!/[A-Za-zА-Яа-яЁё]/.test(char)) {
                currentCluster = 0;
                return;
            }

            if (vowelRegex.test(char)) {
                currentCluster = 0;
                return;
            }

            currentCluster += 1;
            if (currentCluster > maxCluster) {
                maxCluster = currentCluster;
            }
        });

        return maxCluster;
    }

    function getIntervocalicConsonantClusters(text) {
        const normalized = String(text || '').toLowerCase();
        const clusters = [];
        const regex = /[аеёиоуыэюя]([бвгджзйклмнпрстфхцчшщ]{2,3})(?=[аеёиоуыэюя])/gi;
        let match = null;

        while ((match = regex.exec(normalized))) {
            if (match[1]) {
                clusters.push(match[1]);
            }
        }

        return clusters;
    }

    function getRussianTokenScore(text) {
        const normalized = String(text || '').toLowerCase();
        const patterns = [
            /пр/g, /на/g, /не/g, /но/g, /ни/g, /ра/g, /ро/g, /ре/g, /ка/g, /ко/g,
            /по/g, /го/g, /ло/g, /во/g, /се/g, /те/g, /ли/g, /де/g, /ер/g, /ха/g,
            /су/g, /ун/g, /ск/g, /ин/g, /ан/g, /ен/g, /ов/g, /ев/g, /ть/g, /ся/g,
            /нг/g, /см/g, /ам/g, /са/g, /им/g, /ия/g, /ой/g, /ый/g, /ая/g,
            /зв/g, /ук/g, /ки/g, /ри/g, /ва/g, /ла/g, /ны/g, /но/g, /ми/g
        ];

        let score = countMatches(normalized, /[аеёиоуыэюя]/g) * 2;
        score += countPatternHits(normalized, patterns) * 2;

        if (/^[а-яё]/.test(normalized)) {
            score += 1;
        }

        if (getMaxConsonantCluster(normalized, /[аеёиоуыэюя]/i) <= 3) {
            score += 1;
        }

        return score;
    }

    function getEnglishTokenScore(text) {
        const normalized = String(text || '').toLowerCase();
        const patterns = [
            /th/g, /he/g, /in/g, /er/g, /an/g, /re/g, /on/g, /at/g, /en/g, /nd/g,
            /ti/g, /es/g, /or/g, /te/g, /of/g, /ed/g, /is/g, /it/g, /al/g, /ar/g,
            /st/g, /to/g, /nt/g, /ng/g, /se/g, /ha/g, /as/g, /ou/g, /io/g, /le/g,
            /ve/g, /co/g, /me/g, /de/g, /hi/g, /ri/g, /ro/g, /ic/g, /ll/g, /ss/g,
            /oo/g, /ee/g, /qu/g, /ck/g, /ph/g, /ing/g, /ion/g
        ];

        let score = countMatches(normalized, /[aeiouy]/g) * 2;
        score += countPatternHits(normalized, patterns) * 2;

        if (/^[a-z]/.test(normalized)) {
            score += 1;
        }

        if (getMaxConsonantCluster(normalized, /[aeiouy]/i) <= 3) {
            score += 1;
        }

        return score;
    }

    function getRussianWordConfidence(text) {
        const normalized = String(text || '').toLowerCase().replace(/-/g, '');
        if (!/^[а-яё]{3,}$/.test(normalized)) {
            return -100;
        }

        const vowels = countMatches(normalized, /[аеёиоуыэюя]/g);
        const consonantCluster = getMaxConsonantCluster(normalized, /[аеёиоуыэюя]/i);
        const intervocalicClusters = getIntervocalicConsonantClusters(normalized);
        let score = getRussianTokenScore(normalized);
        const allowedClusters = new Set([
            'бл', 'бр', 'вл', 'вр', 'гл', 'гр', 'др', 'жд', 'зв', 'зл', 'зр', 'кл',
            'кр', 'мл', 'мн', 'нд', 'нг', 'пл', 'пр', 'сл', 'см', 'сн', 'сп', 'ст',
            'ск', 'св', 'ср', 'тр', 'фл', 'фр', 'хл', 'чк', 'чн', 'шк', 'стр', 'скр', 'встр'
        ]);

        if (vowels === 0) {
            return -100;
        }

        if (vowels >= 2 && normalized.length >= 5) {
            score += 1;
        }

        if (/(?:ого|ему|ому|ими|ыми|ами|ями|иях|ах|ях|ую|юю|ая|яя|ое|ее|ий|ый|ой|ить|ать|ять|еть|ться|ешь|ете|ишь|ите|ник|чик|щик|тель|ость|ение|ание|ство|ировать|овать|ция|тура|изм)$/i.test(normalized)) {
            score += 2;
        }

        if (/([аеёиоуыэюя])\1/.test(normalized)) {
            score -= 2;
        }

        if (/[аеёиоуыэюя]{3,}/.test(normalized)) {
            score -= 3;
        }

        if (/^[ыьъ]/.test(normalized) || /[ъь]{2,}/.test(normalized)) {
            score -= 4;
        }

        if (consonantCluster >= 5) {
            score -= 4;
        }

        intervocalicClusters.forEach((cluster) => {
            if (!allowedClusters.has(cluster)) {
                score -= 3;
            }
        });

        return score;
    }

    function getEnglishCandidateConfidence(text) {
        const normalized = String(text || '').toLowerCase();
        let score = getEnglishTokenScore(normalized);

        if (/^[a-z]{3,6}$/i.test(normalized)) {
            score += 1;
        }

        if (/(.)\1/i.test(normalized)) {
            score += 1;
        }

        if (/(?:ch|sh|ph|th|ss|ll|ck|bb|ng|sm|lg|mi|ha|er|ar|or|on|el|tv)/i.test(normalized)) {
            score += 1;
        }

        return score;
    }

    function isPlausibleRussianWord(token) {
        const value = String(token || '').trim();
        if (!/^[А-Яа-яЁё\-]{3,}$/.test(value) || isUrlLikeToken(value)) {
            return false;
        }

        const confidence = getRussianWordConfidence(value);
        if (value.length <= 3) {
            return confidence >= 10;
        }

        if (value.length >= 5) {
            return confidence >= 7;
        }

        return confidence >= 8;
    }

    function isPlausibleShortCyrillicAbbreviation(token) {
        const value = String(token || '').trim().toLowerCase();
        if (!/^[а-яё]{2,5}$/.test(value)) {
            return false;
        }

        const vowelCount = countMatches(value, /[аеёиоуыэюя]/g);
        const consonantCount = countMatches(value, /[бвгджзйклмнпрстфхцчшщ]/g);

        if (vowelCount > 0) {
            return false;
        }

        if (consonantCount !== value.length) {
            return false;
        }

        return true;
    }

    function isProtectedCyrillicAbbreviation(token) {
        const rawValue = String(token || '').trim();
        if (!/^[А-Яа-яЁё]{2,6}$/.test(rawValue) || isUrlLikeToken(rawValue)) {
            return false;
        }

        const uppercaseOnly = /^[А-ЯЁ]{2,6}$/.test(rawValue);
        const normalized = rawValue.toLowerCase();
        const vowelCount = countMatches(normalized, /[аеёиоуыэюя]/g);
        const consonantCount = countMatches(normalized, /[бвгджзйклмнпрстфхцчшщ]/g);

        if (uppercaseOnly) {
            return true;
        }

        if (rawValue.length <= 4 && consonantCount >= Math.max(2, rawValue.length - 1)) {
            return true;
        }

        if (rawValue.length <= 5 && vowelCount <= 1 && consonantCount >= 2 && rawValue === rawValue.toUpperCase()) {
            return true;
        }

        return false;
    }

    function isLikelyMistypedEnglishToken(token, context = '') {
        const value = String(token || '').trim();
        if (!/^[А-Яа-яЁё\-]{3,8}$/.test(value) || isUrlLikeToken(value)) {
            return false;
        }

        if (isProtectedCyrillicAbbreviation(value)) {
            return false;
        }

        const translated = translateLayout(value, RU_TO_EN);
        if (translated === value || !/^[A-Za-z\-]{3,8}$/.test(translated)) {
            return false;
        }

        if (isPlausibleShortCyrillicAbbreviation(value)) {
            const englishAbbrevConfidence = getEnglishCandidateConfidence(translated);
            const englishAbbrevVowels = countMatches(translated, /[aeiouy]/gi);
            const hasCommonLatinPattern = /(?:ch|sh|ph|th|ss|ll|ck|bb|ng|sm|lg|mi|ha|er|ar|or|on|el|tv)/i.test(translated);

            if (englishAbbrevConfidence < 8 || (englishAbbrevVowels === 0 && !hasCommonLatinPattern)) {
                return false;
            }
        }

        const englishScore = getEnglishTokenScore(translated);
        const russianScore = getRussianTokenScore(value);
        const russianWordConfidence = getRussianWordConfidence(value);
        const englishCandidateConfidence = getEnglishCandidateConfidence(translated);
        const sourceRussianVowels = countMatches(value, /[аеёиоуыэюя]/gi);
        const englishVowels = countMatches(translated, /[aeiouy]/gi);
        const russianPatterns = countPatternHits(String(value || '').toLowerCase(), [
            /пр/g, /на/g, /не/g, /но/g, /ни/g, /ра/g, /ро/g, /ре/g, /ка/g, /ко/g,
            /по/g, /го/g, /ло/g, /во/g, /се/g, /те/g, /ли/g, /де/g, /ер/g, /су/g,
            /ун/g, /ск/g, /ин/g, /ан/g, /ен/g, /ов/g, /ев/g, /ть/g, /ся/g
        ]);
        const hasEnglishContext = /[A-Za-z]/.test(String(context || ''));
        const hasBrandLikeShape = /^[a-z]{3,6}$/i.test(translated) && englishVowels <= 1;
        const hasRepeatedLatin = /(.)\1/i.test(translated);
        const hasCommonLatinPattern = /(?:ch|sh|ph|th|ss|ll|ck|bb|ng|sm|lg|mi|ha|er|ar|or|on|el|tv)/i.test(translated);
        const hasTooManyLatinVowels = translated.length >= 5 && englishVowels >= Math.ceil(translated.length * 0.6);
        const hasStrongRussianStructure = sourceRussianVowels >= 2 && russianWordConfidence >= 7;
        const hasWeakEnglishShape = englishCandidateConfidence <= 3 && englishVowels === 0 && !hasRepeatedLatin && !hasCommonLatinPattern;

        if (!hasEnglishContext && russianWordConfidence >= 5 && hasWeakEnglishShape) {
            return false;
        }

        if (!hasEnglishContext && !hasBrandLikeShape) {
            if (hasTooManyLatinVowels) {
                return false;
            }

            if (isPlausibleRussianWord(value) && englishCandidateConfidence <= russianWordConfidence + 2) {
                return false;
            }
        }

        if (hasBrandLikeShape && hasStrongRussianStructure) {
            return false;
        }

        return (
            englishCandidateConfidence >= russianWordConfidence + 3 ||
            (hasEnglishContext && englishScore >= russianScore) ||
            (hasBrandLikeShape && !hasStrongRussianStructure && russianPatterns === 0 && (hasRepeatedLatin || hasCommonLatinPattern || englishScore >= 2))
        );
    }

    function isUrlLikeToken(token) {
        const value = String(token || '').trim();
        return !value
            || /[@/:\\?#=&%]/.test(value)
            || /^https?/i.test(value)
            || /^www\./i.test(value)
            || /(?:[a-z0-9-]+\.)+[a-z]{2,}/i.test(value);
    }

    function getNonWhitespaceChunk(text, range) {
        const value = String(text || '');
        if (!range) {
            return '';
        }

        let start = Math.max(0, Math.min(range.start, value.length));
        let end = Math.max(0, Math.min(range.end, value.length));

        while (start > 0 && !/\s/.test(value.charAt(start - 1))) {
            start -= 1;
        }

        while (end < value.length && !/\s/.test(value.charAt(end))) {
            end += 1;
        }

        return value.slice(start, end);
    }

    function isUrlContext(text, range) {
        const chunk = getNonWhitespaceChunk(text, range);
        if (!chunk) {
            return false;
        }

        if (/^(?:https?:\/\/|www\.)/i.test(chunk)) {
            return true;
        }

        if (/^(?:mailto:|tel:)/i.test(chunk)) {
            return true;
        }

        if (/(?:[a-z0-9-]+\.)+[a-z]{2,}/i.test(chunk) && /[/:?#=&%]/.test(chunk)) {
            return true;
        }

        return /(?:vk\.cc|t\.me|wa\.me)/i.test(chunk);
    }

    function looksLikeEnglishModelToken(token) {
        const value = String(token || '').trim();
        return /\d/.test(value) && /^[A-Za-z]{1,5}\d[A-Za-z0-9-]{3,}$/i.test(value);
    }

    function isLikelyMistypedModelToken(token) {
        const value = String(token || '').trim();
        if (!value || !/[А-Яа-яЁё]/.test(value) || !/\d/.test(value) || isUrlLikeToken(value)) {
            return false;
        }

        return looksLikeEnglishModelToken(translateLayout(value, RU_TO_EN));
    }

    function isLikelyMistypedRussianToken(token, context = '') {
        const value = String(token || '').trim();
        if (!/^[A-Za-z\[\];'`,.\-]{4,}$/.test(value) || looksLikeEnglishModelToken(value) || isUrlLikeToken(value)) {
            return false;
        }

        const translated = translateLayout(value, EN_TO_RU);
        if (translated === value || !/^[А-Яа-яЁё-]+$/.test(translated)) {
            return false;
        }

        const ruVowels = countMatches(translated, /[аеёиоуыэюя]/gi);
        const hasRussianContext = /[А-Яа-яЁё]/.test(String(context || ''));
        const hasLayoutSignal = /[\[\];'`,.]/.test(value);
        const russianScore = getRussianTokenScore(translated);
        const englishScore = getEnglishTokenScore(value);
        const englishCluster = getMaxConsonantCluster(value, /[aeiouy]/i);

        return ruVowels >= 1 && (
            (russianScore >= englishScore + 3) ||
            (hasRussianContext && russianScore >= englishScore + 1) ||
            (englishCluster >= 4 && russianScore >= englishScore) ||
            (hasLayoutSignal && russianScore >= englishScore)
        );
    }

    function getPreviousTokenRange(text, caret) {
        const value = String(text || '');
        let end = Math.max(0, Math.min(Number(caret) || 0, value.length));

        while (end > 0 && TOKEN_BREAK_RE.test(value.charAt(end - 1))) {
            end -= 1;
        }

        if (end <= 0) {
            return null;
        }

        let start = end;
        while (start > 0 && !TOKEN_BREAK_RE.test(value.charAt(start - 1))) {
            start -= 1;
        }

        return start < end ? { start, end } : null;
    }

    function getReplacementToken(token, context) {
        const value = String(token || '');
        if (!value) {
            return value;
        }

        if (isLikelyMistypedModelToken(value)) {
            return translateLayout(value, RU_TO_EN);
        }

        return value;
    }

    function getShortRussianPhraseTokenReplacement(token) {
        const value = String(token || '').trim();
        if (!/^[A-Za-z]{1,3}$/.test(value)) {
            return value;
        }

        const translated = translateLayout(value, EN_TO_RU);
        const normalized = translated.toLowerCase();
        const commonShortTokens = new Set([
            'и', 'а', 'в', 'к', 'с', 'у', 'не', 'на', 'но', 'по', 'из', 'от', 'до',
            'за', 'да', 'нет', 'как', 'для', 'при', 'или', 'под', 'без', 'это', 'тв'
        ]);

        return commonShortTokens.has(normalized) ? translated : value;
    }

    function applyFieldValue(field, nextValue, caret) {
        if (!field || field.getAttribute(APPLYING_ATTR) === '1') {
            return;
        }

        field.setAttribute(APPLYING_ATTR, '1');
        field.value = nextValue;

        if (typeof field.setSelectionRange === 'function' && typeof caret === 'number') {
            field.setSelectionRange(caret, caret);
        }

        field.dispatchEvent(new Event('input', { bubbles: true }));
        field.dispatchEvent(new Event('change', { bubbles: true }));
        field.removeAttribute(APPLYING_ATTR);
    }

    function fixPreviousToken(field, options = {}) {
        if (!field || field.getAttribute(APPLYING_ATTR) === '1') {
            return false;
        }

        const value = String(field.value || '');
        const caret = options.useEnd === true
            ? value.length
            : Math.max(0, Math.min(typeof field.selectionStart === 'number' ? field.selectionStart : value.length, value.length));
        const ranges = [];
        let index = 0;

        while (index < caret) {
            while (index < caret && TOKEN_BREAK_RE.test(value.charAt(index))) {
                index += 1;
            }

            if (index >= caret) {
                break;
            }

            const start = index;
            while (index < caret && !TOKEN_BREAK_RE.test(value.charAt(index))) {
                index += 1;
            }

            const end = index;
            if (start < end) {
                ranges.push({ start, end });
            }
        }

        if (!ranges.length) {
            return false;
        }

        const preparedRanges = ranges.map((range) => {
            const token = value.slice(range.start, range.end);
            const context = value.slice(Math.max(0, range.start - 24), range.start);
            const replacement = isUrlContext(value, range) ? token : getReplacementToken(token, context);

            return {
                range,
                token,
                replacement
            };
        });

        const hasPhraseLevelRussianConversion = preparedRanges.some((entry) =>
            entry.replacement !== entry.token
            && entry.token.length >= 4
            && /[А-Яа-яЁё]/.test(entry.replacement)
        );

        let changed = false;
        let delta = 0;
        let lastIndex = 0;
        let nextValue = '';

        preparedRanges.forEach((entry) => {
            const { range, token } = entry;
            let replacement = entry.replacement;

            if (hasPhraseLevelRussianConversion && replacement === token) {
                replacement = getShortRussianPhraseTokenReplacement(token);
            }

            nextValue += value.slice(lastIndex, range.start) + replacement;

            if (replacement !== token) {
                changed = true;
                delta += replacement.length - token.length;
            }

            lastIndex = range.end;
        });

        if (!changed) {
            return false;
        }

        nextValue += value.slice(lastIndex);
        applyFieldValue(field, nextValue, caret + delta);
        return true;
    }

    function isEligibleField(field) {
        if (!field || field.getAttribute(BOUND_ATTR) === '1' || field.disabled || field.readOnly) {
            return false;
        }

        if (field.classList.contains('select2-search__field')) {
            return false;
        }

        const tagName = String(field.tagName || '').toLowerCase();
        if (tagName === 'input') {
            const type = String(field.type || 'text').toLowerCase();
            if (type && !['text', 'search'].includes(type)) {
                return false;
            }

            const meta = `${field.name || ''} ${field.id || ''} ${field.className || ''}`.toLowerCase();
            if (/(phone|date|time|email|url|price|sum|amount|count|qty|zip|postcode)/.test(meta)) {
                return false;
            }
        }

        return true;
    }

    function bindField(field) {
        if (!isEligibleField(field)) {
            return false;
        }

        field.setAttribute(BOUND_ATTR, '1');

        field.addEventListener('keydown', (event) => {
            if (event.ctrlKey || event.metaKey || event.altKey) {
                return;
            }

            const key = String(event.key || '');
            if (key === ' ' || key === 'Enter' || key === 'Tab') {
                field.setAttribute(PENDING_ATTR, '1');
            }
        });

        field.addEventListener('input', () => {
            if (field.getAttribute(APPLYING_ATTR) === '1') {
                return;
            }

            if (field.getAttribute(PENDING_ATTR) !== '1') {
                return;
            }

            field.removeAttribute(PENDING_ATTR);
            fixPreviousToken(field);
        });

        field.addEventListener('blur', () => {
            field.removeAttribute(PENDING_ATTR);
            fixPreviousToken(field, { useEnd: true });
        });

        return true;
    }

    function bindFields() {
        document.querySelectorAll(FIELD_SELECTOR).forEach((field) => {
            bindField(field);
        });
    }

    bindFields();

    if (document.documentElement) {
        observer = new MutationObserver(() => {
            bindFields();
        });
        observer.observe(document.documentElement, { childList: true, subtree: true });
    }

    console.log('⌨️ Автоисправление раскладки v1.4 активно: только модели');
}

